var TRAPS=[{"id":6271,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67263.png","v":null,"a":[{"t":"водачът на зеления автомобил е задължен да пропусне червения автомобил","ok":false,"i":null,"es":"el conductor del coche verde está obligado a ceder al rojo"},{"t":"водачът на червения автомобил е задължен да пропусне зеления автомобил","ok":true,"i":null,"es":"el conductor del coche rojo está obligado a ceder al verde"}],"sim":1,"es":"En esta situación:","explain":"EL CONDUCTOR DEL COCHE ROJO ESTÁ OBLIGADO A CEDER AL VERDE. Una sola correcta.\n\nQUÉ VES. El coche VERDE (en primer plano) tiene una señal de CEDA EL PASO y va a girar a la derecha (intermitente y flecha). De frente viene un coche ROJO, que también llega por una vía secundaria, con el intermitente puesto para girar a SU izquierda. Los dos van a entrar en la misma calle (la de la derecha del verde).\n\nLOS DOS ESTÁN EN SECUNDARIA, así que entre ellos el ceda el paso no decide nada. Decide la regla del giro:\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«EL VERDE ESTÁ OBLIGADO A CEDER AL ROJO» es el cebo: es la misma frase con los colores cambiados.\n\nCLAVE: lee con cuidado qué color va en cada lado de la frase. Ver Leyes → «Giro a la izquierda»."},{"id":5693,"bg":"На кои колела на автомобила се поставят при необходимост веригите за сняг?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"веригите за сняг се поставят винаги на предните колела","ok":false,"i":null,"es":"las cadenas van siempre en las ruedas delanteras"},{"t":"на колелата, които не се задвижват от двигателя","ok":false,"i":null,"es":"en las ruedas que NO son motrices"},{"t":"на колелата, които се задвижват от двигателя","ok":true,"i":null,"es":"en las ruedas MOTRICES (las que impulsa el motor)"},{"t":"веригите за сняг се поставят винаги на задните колела","ok":false,"i":null,"es":"las cadenas van siempre en las ruedas traseras"}],"sim":0.88,"es":"¿En qué ruedas se colocan las cadenas de nieve?","explain":"⚠️ TRAMPA: siempre en las ruedas MOTRICES — las que reciben potencia del motor. En un coche de tracción delantera: delante. En tracción trasera: detrás. No siempre delante ni siempre detrás."},{"id":8247,"bg":"Към категория АМ принадлежат превозни средства с конструктивна максимална скорост до 45 km/h и двигатели с вътрешно горене с работен обем до 50 cm3, които са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"с две колела","ok":true,"i":null,"es":"dos ruedas"},{"t":"с три колела","ok":true,"i":null,"es":"tres ruedas"},{"t":"с четири колела и маса без товар не повече от 350 kg","ok":true,"i":null,"es":"cuatro ruedas y masa sin carga no superior a 350 kg"},{"t":"с четири колела и маса без товар не повече от 400 kg","ok":false,"i":null,"es":"cuatro ruedas y masa sin carga no superior a 400 kg"}],"sim":0.85,"es":"A la categoría AM pertenecen vehículos con velocidad máxima hasta 45 km/h y motor... con:","explain":"⚠️ TRAMPA: cuatro ruedas = máximo 350 kg (no 400). El límite exacto es 350 kg — memoriza este número específico."},{"id":6303,"bg":"Когато над платното за движение е поставен пътен знак с допълнителната табела “Стрелка”, това означава, че:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57156.png","v":null,"a":[{"t":"знакът се отнася само за пътната лента, над която е поставен","ok":true,"i":null,"es":"la señal se refiere solo al carril sobre el que está colocada"},{"t":"знакът не се отнася за пътната лента, над която е поставен","ok":false,"i":null,"es":"la señal NO se refiere al carril sobre el que está"},{"t":"знакът се отнася само за тези, които след него продължават движението си направо","ok":false,"i":null,"es":"la señal se refiere solo a los que continúan recto"},{"t":"знакът се отнася за цялата широчина на платното за движение","ok":false,"i":null,"es":"la señal se refiere a toda la anchura de la calzada"}],"sim":0.83,"es":"Cuando sobre la calzada hay una señal con tablilla complementaria 'Flecha', esto significa:","explain":"LA SEÑAL SE REFIERE SOLO AL CARRIL SOBRE EL QUE ESTÁ COLOCADA. Una sola correcta.\n\nQUÉ VES. Calle de varios carriles. Colgada de un pórtico sobre el carril IZQUIERDO, una señal de PROHIBIDA LA ENTRADA A CAMIONES con una placa con una flecha hacia ABAJO.\n\nLA FLECHA HACIA ABAJO apunta al carril al que se aplica la señal. Los demás carriles no están afectados.\n\n«NO SE REFIERE A ESE CARRIL» le da la vuelta. «TODA LA ANCHURA» es lo que haría la señal sin la flecha. «SOLO A LOS QUE SIGUEN RECTO» inventa una condición.\n\nCLAVE: compárala con la 6306 y la 11869. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11686,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62875.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"пътното платно да е с не по-малко от три пътни ленти за движение в една посока","ok":false,"i":null,"es":"la calzada tiene no menos de tres carriles en una dirección"},{"t":"разрешената скорост за движение да е не по-голяма от 50 km/h","ok":false,"i":null,"es":"la velocidad máxima es no superior a 50 km/h"}],"sim":0.83,"es":"¿Qué condiciones deben darse para poder usar carriles distintos al derecho en zona urbana? (2 correctas)","explain":"QUE LA CALZADA TENGA DOS O MÁS CARRILES EN UN SENTIDO Y QUE LA VELOCIDAD MÁXIMA PERMITIDA NO SUPERE 80 km/h. Dos correctas.\n\nQUÉ VES. Calle urbana con señales de máxima 60 y placas que indican TRES carriles en tu sentido.\n\nLA EXCEPCIÓN DE LA POBLACIÓN TIENE DOS CONDICIONES. En población puedes usar el carril que te resulte más cómodo (no solo el derecho) si: hay dos o más carriles en tu sentido y la velocidad máxima permitida no pasa de 80 km/h. Aquí se cumplen las dos.\n\n«NO MENOS DE TRES CARRILES» exige de más: bastan dos.\n\n«VELOCIDAD MÁXIMA NO SUPERIOR A 50 km/h» también exige de más: el límite de la condición es 80.\n\nCLAVE: población + 2 carriles o más en tu sentido + máximo ≤ 80 km/h = libertad de carril. Ver Leyes → «Carril: dónde debes circular»."},{"id":5934,"bg":"Когато и двете секции на този светофар не работят и няма пътен знак за броя и посоките на движение по пътните ленти, това означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45488.png","v":null,"a":[{"t":"навлизането по пътната лента, над която е поставен светофарът, е забранено","ok":true,"i":null,"es":"la entrada al carril sobre el que está el semáforo está PROHIBIDA"},{"t":"навлизането по пътната лента, над която е поставен светофарът, е разрешено","ok":false,"i":null,"es":"la entrada está permitida"},{"t":"водачът трябва да спре на линията, на която е поставен светофарът","ok":false,"i":null,"es":"el conductor debe parar en la línea del semáforo"}],"sim":0.82,"es":"Cuando ambas secciones de este semáforo de carril no funcionan y no hay señal de tráfico:","explain":"⚠️ TRAMPA: semáforo de carril apagado = carril CERRADO, entrada prohibida. Un semáforo apagado no significa paso libre — significa que ese carril no está disponible."},{"id":6192,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334696.png","v":null,"a":[{"t":"задължава водачите да се движат само наляво пред знака","ok":true,"i":null,"es":"obliga a circular solo a la izquierda ANTES de la señal"},{"t":"задължава водачите да се движат само наляво след знака","ok":false,"i":null,"es":"obliga a circular solo a la izquierda DESPUÉS de la señal"},{"t":"задължава водачите да преминат отляво на знака","ok":false,"i":null,"es":"obliga a pasar por la izquierda de la señal"}],"sim":0.8,"es":"Esta señal:","explain":"OBLIGA A CIRCULAR SOLO A LA IZQUIERDA ANTES DE LA SEÑAL. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con una flecha blanca HORIZONTAL hacia la izquierda.\n\nLA FLECHA HORIZONTAL obliga a girar ANTES de llegar a la señal, que suele estar al fondo de un cruce en T.\n\n«DESPUÉS DE LA SEÑAL» es la flecha que sube y GIRA. «PASAR POR LA IZQUIERDA DE LA SEÑAL» es la flecha OBLICUA hacia abajo.\n\nCLAVE: compárala con la 6191 (la misma pregunta en otra forma). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6218,"bg":"С допълнителната табела към този пътен знак се указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53812.png","v":null,"a":[{"t":"разстоянието до стеснения участък от платното за движение","ok":true,"i":null,"es":"la DISTANCIA hasta el tramo estrecho"},{"t":"дължината на стеснения участък от платното за движение","ok":false,"i":null,"es":"la LONGITUD del tramo estrecho"},{"t":"разстоянието до края на стеснения участък от платното за движение","ok":false,"i":null,"es":"la distancia hasta el FINAL del tramo estrecho"}],"sim":0.8,"es":"La tablilla complementaria junto a esta señal indica:","explain":"LA DISTANCIA HASTA EL TRAMO ESTRECHO. Una sola correcta.\n\nQUÉ VES. Triángulo de ESTRECHAMIENTO por ambos lados con una placa debajo: «200 m», sin flechas.\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso (dónde empieza lo marca la distancia normal de colocación: 50-100 m en población, 100-150 m fuera).\n\n«LA LONGITUD DEL TRAMO» sería con flechas (compárala con la 6224). «LA DISTANCIA AL FINAL» no la indica ninguna de estas placas.\n\nCLAVE: cifra sola = cuánto falta. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5928,"bg":"Значението на този светлинен сигнал е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44560.png","v":null,"a":[{"t":"„Навлизането е разрешено” по пътната лента, над която е поставен","ok":true,"i":null,"es":"'Entrada PERMITIDA' en el carril sobre el que está"},{"t":"„Задължителна посока за движение”","ok":false,"i":null,"es":"'Dirección obligatoria'"},{"t":"„Навлизането е забранено” по пътната лента, над която е поставен","ok":false,"i":null,"es":"'Entrada PROHIBIDA' en el carril sobre el que está"},{"t":"„Място за задължително спиране” в пътната лента, над която е поставен","ok":false,"i":null,"es":"'Lugar de parada obligatoria'"}],"sim":0.8,"es":"El significado de esta señal luminosa es:","explain":"⚠️ TRAMPA: flecha verde hacia abajo = PERMITIDA. Comparar con ID 5932 donde X roja = PROHIBIDA. Son opuestas — esta es la versión 'permitida'."},{"id":5932,"bg":"Значението на този светлинен сигнал е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44686.png","v":null,"a":[{"t":"„Навлизането е забранено” по пътната лента, над която е поставен","ok":true,"i":null,"es":"'Entrada PROHIBIDA' en el carril sobre el que está"},{"t":"„Следва кръстовище на равнозначни пътища”","ok":false,"i":null,"es":"'Sigue intersección de vías equivalentes'"},{"t":"„Навлизането е разрешено” по пътната лента, над която е поставен","ok":false,"i":null,"es":"'Entrada PERMITIDA' en el carril sobre el que está"},{"t":"„Място за задължително спиране”","ok":false,"i":null,"es":"'Lugar de parada obligatoria'"}],"sim":0.8,"es":"El significado de esta señal luminosa es:","explain":"⚠️ TRAMPA: X roja = PROHIBIDA. Comparar con ID 5928 donde flecha verde = PERMITIDA. Esta es la versión 'prohibida' — X siempre = prohibición."},{"id":11622,"bg":"В района на спирка на превозните средства от редовните линии за обществен превоз на пътници, на други превозни средства е разрешено да спират за:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"слизане на пътници, само ако не пречат на превозните средства, за които е предназначена спирката","ok":true,"i":null,"es":"bajada de pasajeros, solo si no interfieren con los vehículos de línea"},{"t":"качване на пътници, ако не пречат на превозните средства, за които е предназначена спирката","ok":false,"i":null,"es":"subida de pasajeros, si no interfieren con los de línea"},{"t":"извършване на товаро-разтоварна дейност","ok":false,"i":null,"es":"carga y descarga de mercancías"}],"sim":0.8,"es":"En la zona de parada del transporte público, otros vehículos solo pueden realizar:","explain":"⚠️ TRAMPA: solo BAJADA de pasajeros está permitida (no subida). La diferencia es sutil pero importante — subir pasajeros en parada de bus no está permitido."},{"id":5701,"bg":"Какви са изискванията към водача, който управлява тегленото МПС?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да бъде правоспособен за категорията на тегленото МПС","ok":true,"i":null,"es":"debe tener permiso para la categoría del vehículo REMOLCADO"},{"t":"трябва да бъде правоспособен за категорията на теглещото МПС","ok":false,"i":null,"es":"debe tener permiso para la categoría del vehículo REMOLCADOR"},{"t":"не е задължително да бъде правоспособен водач","ok":false,"i":null,"es":"no es obligatorio que sea conductor autorizado"},{"t":"достатъчно е да бъде правоспособен водач, независимо за коя категория","ok":false,"i":null,"es":"достатъчно е да бъде правоспособен водач, независимо за коя категория"}],"sim":0.8,"es":"¿Qué requisito debe cumplir el conductor del vehículo REMOLCADO?","explain":"⚠️ TRAMPA: permiso para el vehículo REMOLCADO (el que va detrás), no el remolcador. El conductor del vehículo de atrás necesita el permiso correspondiente a ese tipo de vehículo."},{"id":5610,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на велосипедна пътека","ok":true,"i":null,"es":"en carril bici"},{"t":"на разстояние, по-малко от 5 метра преди велосипедна пътека","ok":true,"i":null,"es":"a menos de 5 metros ANTES del carril bici"},{"t":"на разстояние, по-малко от 5 метра след велосипедна пътека","ok":false,"i":null,"es":"a menos de 5 metros DESPUÉS del carril bici"}],"sim":0.8,"es":"La parada breve (prestoy) está PROHIBIDA:","explain":"⚠️ TRAMPA CLÁSICA: prohibido EN el carril bici y a 5m ANTES. DESPUÉS del carril bici no hay restricción. Esta distinción antes/después es una de las trampas más repetidas."},{"id":5630,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на велосипедна пътека","ok":true,"i":null,"es":"en carril bici"},{"t":"на разстояние, по-малко от 5 метра преди велосипедна пътека","ok":true,"i":null,"es":"a menos de 5 metros ANTES del carril bici"},{"t":"на разстояние, по-малко от 5 метра след велосипедна пътека","ok":false,"i":null,"es":"a menos de 5 metros DESPUÉS del carril bici"}],"sim":0.8,"es":"El aparcamiento está PROHIBIDO:","explain":"⚠️ TRAMPA: igual que prestoy — prohibido EN y a 5m ANTES. DESPUÉS no está restringido. Memoriza: la restricción es siempre antes, nunca después."},{"id":7809,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на разстояние по-малко от 5 м преди пешеходна пътека","ok":true,"i":null,"es":"a menos de 5 m ANTES del paso de peatones"},{"t":"на разстояние по-малко от 5 м след пешеходна пътека","ok":false,"i":null,"es":"a menos de 5 m DESPUÉS del paso de peatones"}],"sim":0.8,"es":"El aparcamiento está PROHIBIDO:","explain":"⚠️ TRAMPA: EN el paso y a 5m ANTES. Después no hay restricción de distancia. Esta es una de las preguntas más repetidas del examen — memoriza el ANTES."},{"id":11892,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на разстояние по-малко от 5 метра преди пешеходна пътека","ok":true,"i":null,"es":"a menos de 5 m ANTES del paso de peatones"},{"t":"на разстояние по-малко от 5 метра след пешеходна пътека","ok":false,"i":null,"es":"a menos de 5 m DESPUÉS del paso de peatones"}],"sim":0.8,"es":"La parada breve está PROHIBIDA:","explain":"⚠️ TRAMPA: igual que aparcamiento — EN y a 5m ANTES. DESPUÉS no está restringido. Esta regla (5m antes, no después) aparece con mucha frecuencia en el examen."},{"id":5184,"bg":"Леки са автомобилите, предназначени за превоз на пътници с не повече от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"8 места за сядане без мястото на водача","ok":true,"i":null,"es":"8 plazas sentadas sin contar al conductor"},{"t":"6 места за сядане без мястото на водача","ok":false,"i":null,"es":"6 plazas"},{"t":"10 места за сядане без мястото на водача","ok":false,"i":null,"es":"10 plazas"},{"t":"12 места за сядане без мястото на водача","ok":false,"i":null,"es":"12 plazas"}],"sim":0.78,"es":"Son turismos los automóviles destinados al transporte de pasajeros con no más de:","explain":"⚠️ TRAMPA: máximo 8 plazas SIN contar al conductor. El conductor no cuenta. 8+1(conductor)=9 personas máximo en total."},{"id":8214,"bg":"Извън населените места, при липса на банкет, лицата бутащи мотопед са длъжни да се движат по платното за движение, като:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"се придържат възможно най-близо до дясната му граница","ok":true,"i":null,"es":"pegados todo lo posible al borde DERECHO"},{"t":"се придържат възможно най-близо до лявата му граница","ok":false,"i":null,"es":"pegados todo lo posible al borde IZQUIERDO"}],"sim":0.78,"es":"Fuera de población, sin arcén, las personas empujando un ciclomotor deben circular por la calzada:","explain":"⚠️ TRAMPA: todo lo posible a la DERECHA, no a la izquierda. Cuando empujas un vehículo eres tratado como peatón-vehículo y vas a la derecha."},{"id":6056,"bg":"Използването на звуковия сигнал е разрешено:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"извън населените места, като допълнителен сигнал за маневра","ok":true,"i":null,"es":"fuera de población, como señal adicional de maniobra"},{"t":"навсякъде, за недопускане на ПТП","ok":true,"i":null,"es":"en cualquier lugar, para evitar un accidente"},{"t":"в населените места, като допълнителен сигнал за маневра","ok":false,"i":null,"es":"en zona urbana, como señal adicional de maniobra"},{"t":"навсякъде, без ограничения","ok":false,"i":null,"es":"en cualquier lugar, sin restricciones"}],"sim":0.78,"es":"El uso del claxon está PERMITIDO: (2 correctas)","explain":"⚠️ TRAMPA: el claxon como señal de maniobra solo fuera de ciudad + en cualquier lugar para evitar accidente. En ciudad NO está permitido como señal de maniobra — solo en emergencia."},{"id":6175,"bg":"Този пътен знак забранява влизането на пътни превозни средства:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52215.png","v":null,"a":[{"t":"с височина, включително и товара, по-голяма от означената","ok":true,"i":null,"es":"con altura, incluyendo carga, superior a la indicada"},{"t":"с дължина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con longitud, incluyendo carga, superior a la indicada"},{"t":"с широчина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con anchura, incluyendo carga, superior a la indicada"},{"t":"движещи се едно зад друго на разстояние по-малко от означеното","ok":false,"i":null,"es":"que circulan en convoy a menos de la distancia indicada"}],"sim":0.78,"es":"Esta señal prohíbe la entrada de vehículos:","explain":"CON ALTURA, INCLUIDA LA CARGA, SUPERIOR A LA INDICADA. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con «3,5 m» y dos triángulos negros, uno ARRIBA y otro ABAJO, apuntando al número.\n\nLAS SEÑALES DE TONELADAS Y METROS:\n• solo «3 t» = masa total con carga;\n• «t» sobre un EJE = carga por eje;\n• «m» con flechas ARRIBA y ABAJO = altura; a los LADOS = anchura; con un camión y flechas delante y detrás = longitud.\n\nLAS PUNTAS ARRIBA Y ABAJO = ALTURA: no pueden pasar los vehículos de más de 3,5 m de alto, contando la carga (típica antes de un puente o un túnel bajo).\n\n«LONGITUD», «ANCHURA» y «DISTANCIA ENTRE VEHÍCULOS» tienen las flechas en otra posición o un dibujo distinto.\n\nCLAVE: mira hacia dónde apuntan las puntas. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6176,"bg":"Този пътен знак забранява влизането след него на превозно средство, на което:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52235.png","v":null,"a":[{"t":"височината на превозното средство е по-голяма от означената","ok":true,"i":null,"es":"altura del vehículo es superior a la indicada"},{"t":"височината на превозното средство с товара е по-голяма от означената","ok":true,"i":null,"es":"altura del vehículo CON CARGA es superior a la indicada"},{"t":"дължината на превозното средство е по-голяма от означената","ok":false,"i":null,"es":"longitud del vehículo es superior a la indicada"},{"t":"товарът е с дължина по-голяма от означената","ok":false,"i":null,"es":"longitud de la carga es superior a la indicada"}],"sim":0.78,"es":"Esta señal prohíbe la entrada de vehículos cuya: (2 correctas)","explain":"LA ALTURA DEL VEHÍCULO Y LA ALTURA DEL VEHÍCULO CON CARGA SUPERIORES A LA INDICADA. Dos correctas.\n\nLA SEÑAL. Círculo con borde ROJO, «3,5 m» y dos puntas negras, una ARRIBA y otra ABAJO.\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\nLAS DOS CORRECTAS SON LA MISMA IDEA: no puede pasar el vehículo que mida más de 3,5 m de alto, ni por sí mismo ni con lo que lleva encima.\n\n«LONGITUD» (dos opciones) es el cebo: es la señal del camión.\n\nCLAVE: compárala con la 6175. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6177,"bg":"Този пътен знак забранява влизането на ППС:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52837.png","v":null,"a":[{"t":"с широчина, включително и товара, по-голяма от означената","ok":true,"i":null,"es":"con anchura, incluyendo carga, superior a la indicada"},{"t":"с дължина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con longitud, incluyendo carga, superior a la indicada"},{"t":"с височина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con altura, incluyendo carga, superior a la indicada"},{"t":"движещи се едно зад друго, на разстояние по-малко от означеното","ok":false,"i":null,"es":"que circulan en convoy a menos de la distancia indicada"}],"sim":0.78,"es":"Esta señal prohíbe la entrada de vehículos:","explain":"CON ANCHURA, INCLUIDA LA CARGA, SUPERIOR A LA INDICADA. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO, «2,5 m» y dos puntas negras a la IZQUIERDA y a la DERECHA.\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\n«ALTURA» y «LONGITUD» tienen las puntas o el dibujo en otro sitio. «DISTANCIA ENTRE VEHÍCULOS» tiene dos coches y una cifra (6182).\n\nCLAVE: puntas a los lados = anchura. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6178,"bg":"Този пътен знак забранява влизането след него на превозно средство, на което:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52862.png","v":null,"a":[{"t":"широчината на превозното средство е по-голяма от означената","ok":true,"i":null,"es":"anchura del vehículo es superior a la indicada"},{"t":"широчината на превозното средство с товара е по-голяма от означената","ok":true,"i":null,"es":"anchura del vehículo CON CARGA es superior a la indicada"},{"t":"дължината на превозното средство е по-голяма от означената","ok":false,"i":null,"es":"longitud del vehículo es superior a la indicada"},{"t":"товарът е с дължина по-голяма от означената","ok":false,"i":null,"es":"longitud de la carga es superior a la indicada"}],"sim":0.78,"es":"Esta señal prohíbe la entrada cuya: (2 correctas)","explain":"LA ANCHURA DEL VEHÍCULO Y LA ANCHURA DEL VEHÍCULO CON CARGA SUPERIORES A LA INDICADA. Dos correctas.\n\nLA SEÑAL. La misma que la 6177: «2,5 m» con puntas a la IZQUIERDA y a la DERECHA.\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\n«LONGITUD DEL VEHÍCULO» y «LONGITUD DE LA CARGA» son los cebos: es otra señal.\n\nCLAVE: compárala con la 6176 (la misma pregunta con la altura). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6180,"bg":"Този пътен знак забранява влизането на ППС:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53311.png","v":null,"a":[{"t":"с дължина, включително и товара, по-голяма от означената","ok":true,"i":null,"es":"con longitud, incluyendo carga, superior a la indicada"},{"t":"движещи се едно зад друго, на разстояние по-малко от означеното","ok":false,"i":null,"es":"que circulan en convoy a menos de la distancia indicada"},{"t":"с широчина, включително и товара, по-голяма от означената","ok":false,"i":null,"es":"con anchura, incluyendo carga, superior a la indicada"}],"sim":0.78,"es":"Esta señal prohíbe la entrada de vehículos:","explain":"CON LONGITUD, INCLUIDA LA CARGA, SUPERIOR A LA INDICADA. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con un CAMIÓN y, debajo, «← 10 m →».\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\n«DISTANCIA ENTRE VEHÍCULOS» tiene dos coches con la cifra entre ellos (6182). «ANCHURA» tiene puntas a los lados de la cifra.\n\nCLAVE: camión con flecha horizontal = longitud. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6181,"bg":"Този пътен знак забранява влизането след него на превозно средство, на което:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53311.png","v":null,"a":[{"t":"дължината на превозното средство е по-голяма от означената","ok":true,"i":null,"es":"longitud del vehículo es superior a la indicada"},{"t":"дължината на превозното средство с товара е по-голяма от означената","ok":true,"i":null,"es":"longitud del vehículo CON CARGA es superior a la indicada"},{"t":"широчината на превозното средство е по-голяма от означената","ok":false,"i":null,"es":"anchura del vehículo es superior a la indicada"},{"t":"товарът е с широчина по-голяма от означената","ok":false,"i":null,"es":"anchura de la carga es superior a la indicada"}],"sim":0.78,"es":"Esta señal prohíbe la entrada cuya: (2 correctas)","explain":"LA LONGITUD DEL VEHÍCULO Y LA LONGITUD DEL VEHÍCULO CON CARGA SUPERIORES A LA INDICADA. Dos correctas.\n\nLA SEÑAL. La misma que la 6180: un CAMIÓN con «← 10 m →».\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\n«ANCHURA DEL VEHÍCULO» y «ANCHURA DE LA CARGA» son los cebos: es la señal de las puntas a los lados.\n\nCLAVE: compárala con la 6176 y la 6178 (la misma pregunta con altura y anchura). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6182,"bg":"Този пътен знак означава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53426.png","v":null,"a":[{"t":"забрана за движение на дистанция, по-малка от означената","ok":true,"i":null,"es":"prohibición de circular a distancia INFERIOR a la indicada"},{"t":"разстояние между автомобилите при паркиране","ok":false,"i":null,"es":"distancia entre vehículos al aparcar"},{"t":"забрана за движение на дистанция, по-голяма от означената","ok":false,"i":null,"es":"prohibición de circular a distancia SUPERIOR a la indicada"}],"sim":0.78,"es":"Esta señal significa:","explain":"PROHIBICIÓN DE CIRCULAR A UNA DISTANCIA INFERIOR A LA INDICADA. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con dos coches, uno detrás de otro, y «70 m» entre ellos.\n\nPROHÍBE IR MÁS CERCA DE 70 m del vehículo de delante (habitual en puentes y túneles).\n\n«DISTANCIA AL APARCAR» es el cebo: la señal es de circulación, no de estacionamiento.\n\n«DISTANCIA SUPERIOR» es el cebo al revés: lo peligroso es ir demasiado cerca, no demasiado lejos.\n\nCLAVE: cifra entre dos coches = distancia mínima de seguridad. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6263,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54814.png","v":null,"a":[{"t":"начало на участъка, в който е забранено паркирането","ok":true,"i":null,"es":"INICIO del tramo donde está prohibido aparcar"},{"t":"край на участъка, в който е забранено паркирането","ok":false,"i":null,"es":"FIN del tramo donde está prohibido aparcar"}],"sim":0.78,"es":"La tablilla complementaria junto a la señal indica:","explain":"INICIO DEL TRAMO DONDE ESTÁ PROHIBIDO APARCAR.\n\nQUÉ VES. Señal de PROHIBIDO ESTACIONAR (círculo azul con borde rojo y una sola barra) con una placa con una flecha VERTICAL de una sola punta hacia ARRIBA.\n\nLA FLECHA DE UNA SOLA PUNTA EN LA PLACA:\n• hacia DELANTE (arriba, en una señal de frente) = aquí EMPIEZA la zona;\n• hacia ATRÁS (abajo) = aquí TERMINA;\n• de DOS puntas = sigues dentro de la zona.\n\n«FIN DEL TRAMO» llevaría la flecha hacia abajo (compárala con la 6258).\n\nCLAVE: flecha hacia delante = empieza. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6272,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54849.png","v":null,"a":[{"t":"начало на участъка, в който е забранено паркирането","ok":true,"i":null,"es":"INICIO del tramo donde está prohibido aparcar"},{"t":"край на участъка, в който е забранено паркирането","ok":false,"i":null,"es":"FIN del tramo donde está prohibido aparcar"}],"sim":0.78,"es":"La tablilla complementaria junto a la señal indica:","explain":"INICIO DEL TRAMO DONDE ESTÁ PROHIBIDO APARCAR.\n\nQUÉ VES. Señal de PROHIBIDO ESTACIONAR con una placa con una flecha HORIZONTAL de una sola punta hacia la IZQUIERDA.\n\nES LA VERSIÓN PARA UNA SEÑAL COLOCADA EN PARALELO A LA CALZADA. Según el banco, la flecha hacia la izquierda marca el INICIO del tramo prohibido; la que apunta a la derecha marca el fin (compárala con la 6260).\n\n«FIN DEL TRAMO» es el cebo.\n\nCLAVE: compárala con la 6263 y la 6260. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6328,"bg":"При несъответствие между временната пътна маркировка и постоянната пътна маркировка, водачите:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"трябва да се съобразяват с временната пътна маркировка","ok":true,"i":null,"es":"deben atenerse a la marcación TEMPORAL"},{"t":"трябва да се съобразяват с постоянната пътна маркировка","ok":false,"i":null,"es":"deben atenerse a la marcación PERMANENTE"},{"t":"не трябва да се съобразяват с пътната маркировка","ok":false,"i":null,"es":"no deben atenerse a ninguna marcación"}],"sim":0.78,"es":"Cuando la marcación temporal y la permanente no coinciden, los conductores:","explain":"⚠️ TRAMPA: la marcación TEMPORAL prevalece sobre la permanente. Igual que las señales temporales prevalecen sobre las fijas. Lo más reciente siempre manda."},{"id":6462,"bg":"Мотопедистите могат да използват за движение пътния банкет, който:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се намира отдясно по посока на движението им","ok":true,"i":null,"es":"está a la DERECHA en su sentido de marcha"},{"t":"се намира отляво по посока на движението им","ok":false,"i":null,"es":"está a la IZQUIERDA en su sentido de marcha"},{"t":"е по-удобен за тях, независимо от коя страна на пътя се намира","ok":false,"i":null,"es":"sea más cómodo independientemente del lado"}],"sim":0.78,"es":"Los ciclomotores pueden usar el arcén que:","explain":"⚠️ TRAMPA: solo el arcén DERECHO. Los ciclomotores siempre circulan por la derecha — nunca usan el arcén izquierdo aunque sea más cómodo."},{"id":6492,"bg":"При тази ситуация водачът на бавнодвижещото се ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65857.png","v":null,"a":[{"t":"е задължен да използва най-дясната пътна лента","ok":true,"i":null,"es":"está obligado a usar el carril más a la derecha"},{"t":"може да използва средната пътна лента при заобикаляне","ok":true,"i":null,"es":"puede usar el carril central al rodear un obstáculo"},{"t":"може да използва крайната лява лента при завиване","ok":true,"i":null,"es":"puede usar el carril izquierdo al girar"},{"t":"може да използва крайната лява лента при изпреварване","ok":false,"i":null,"es":"puede usar el carril izquierdo al ADELANTAR"}],"sim":0.78,"es":"En esta situación el conductor del vehículo lento: (3 correctas)","explain":"⚠️ TRAMPA: el carril izquierdo se puede usar para GIRAR pero NO para adelantar. Los vehículos lentos tienen acceso limitado al carril izquierdo — solo para giros, no para adelantamientos."},{"id":5247,"bg":"Разделителната ивица е надлъжна част от пътя, която:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20394.png","v":null,"a":[{"t":"разделя пътя на отделни платна за движение","ok":true,"i":null,"es":"separa la vía en CALZADAS separadas"},{"t":"разделя пътя на отделни ленти за движение","ok":false,"i":null,"es":"separa la vía en CARRILES"},{"t":"отделя платното за движение от другите елементи на пътя","ok":false,"i":null,"es":"separa la calzada de otros elementos de la vía"}],"sim":0.75,"es":"La mediana es la parte longitudinal del camino que:","explain":"SEPARA LA VÍA EN CALZADAS SEPARADAS. Una sola correcta.\n\nQUÉ VES. Una AUTOPISTA (señal verde) con dos calzadas, una para cada sentido, separadas por una franja con hierba y una barrera metálica.\n\nLA FRANJA DIVISORIA (MEDIANA) divide la vía en DOS CALZADAS, una por sentido.\n\n«SEPARA EN CARRILES» es el cebo: los carriles se separan con líneas pintadas, dentro de la misma calzada.\n\n«SEPARA LA CALZADA DE OTROS ELEMENTOS» describe el arcén o la acera, no la mediana.\n\nCLAVE: mediana = entre calzadas; línea = entre carriles. Compárala con la 5409 (prohibido cruzar la mediana)."},{"id":5537,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"широчината му, включително товара, е 2,8 м","ok":true,"i":null,"es":"su ANCHURA, incluyendo carga, es 2.8 m"},{"t":"височината му, включително товара, е 2,8 м","ok":false,"i":null,"es":"su ALTURA, incluyendo carga, es 2.8 m"},{"t":"дължината му, включително товара, е 12 м","ok":false,"i":null,"es":"su LONGITUD, incluyendo carga, es 12 m"}],"sim":0.75,"es":"Un vehículo es 'fuera de gálibo' cuando:","explain":"⚠️ TRAMPA: anchura máxima = 2.55m (redondeado a 2.5m para normalidad). 2.8m de anchura SÍ es fuera de gálibo. La altura máxima es 4m y la longitud 12m (que NO es fuera de gálibo)."},{"id":5539,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,5 м","ok":true,"i":null,"es":"4.5 m"},{"t":"височината му, включително товара, е 4,8 м","ok":true,"i":null,"es":"4.8 m"},{"t":"височината му, включително товара, е 2,5 м","ok":false,"i":null,"es":"2.5 m"},{"t":"височината му, включително товара, е 3,5 м","ok":false,"i":null,"es":"3.5 m"}],"sim":0.75,"es":"Un vehículo es 'fuera de gálibo' cuando su altura, incluyendo carga, es: (2 correctas)","explain":"⚠️ TRAMPA: altura máxima = 4.0 m. Fuera de gálibo: 4.5m y 4.8m. Las alturas de 2.5m y 3.5m están dentro del límite. El umbral es exactamente 4 metros."},{"id":11889,"bg":"По този път извън населено място, участъкът с опасни завои започва на разстояние:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56122.png","v":null,"a":[{"t":"от 100 до 150 метра след знака","ok":true,"i":null,"es":"entre 100 y 150 metros después de la señal"},{"t":"от 50 до 100 метра след знака","ok":false,"i":null,"es":"entre 50 y 100 metros después"},{"t":"на 250 метра след знака","ok":false,"i":null,"es":"a 250 metros"},{"t":"не повече от 250 метра","ok":false,"i":null,"es":"no más de 250 metros"}],"sim":0.75,"es":"Por esta carretera fuera de población, el tramo con curvas peligrosas empieza a:","explain":"ENTRE 100 Y 150 m DESPUÉS DE LA SEÑAL. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población con curvas balizadas. A la derecha, el triángulo de CURVAS SUCESIVAS con una placa «↑ 250 m ↑» (ampliada en la imagen).\n\nLA PLACA CON FLECHAS DA LA LONGITUD del tramo (250 m), no dónde empieza. Dónde empieza lo marca la regla general: fuera de población, las señales de peligro se ponen de 100 a 150 m antes.\n\n«A 250 m» y «NO MÁS DE 250 m» son los cebos: leen la longitud como una distancia.\n\n«50-100 m» es la distancia en población.\n\nCLAVE: compárala con la 6238 y la 6287. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6435,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64344.png","v":null,"a":[{"t":"трябва да премина в дясната пътна лента","ok":true,"i":null,"es":"debo cambiar al carril DERECHO"},{"t":"трябва да премина в лявата пътна лента","ok":false,"i":null,"es":"debo cambiar al carril IZQUIERDO"},{"t":"мога да продължа движението си в същата пътна лента","ok":false,"i":null,"es":"puedo continuar en el mismo carril"}],"sim":0.75,"es":"En esta situación:","explain":"⚠️ TRAMPA: la señal indica que debes moverte al carril DERECHO (el actual carril termina o está reservado). No al izquierdo ni continuar igual."},{"id":6237,"bg":"Когато има остров в средата на пътно платно с двупосочно движение, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124137.png","v":null,"a":[{"t":"трябва да премине от неговата дясна страна","ok":true,"i":null,"es":"debe pasar por su lado DERECHO"},{"t":"трябва да премине от неговата лява страна","ok":false,"i":null,"es":"debe pasar por su lado IZQUIERDO"},{"t":"може да премине от неговата дясна или лява страна","ok":false,"i":null,"es":"puede pasar por cualquier lado"}],"sim":0.75,"es":"Cuando hay una isla en el centro de la calzada de doble sentido, el conductor:","explain":"DEBE PASAR POR SU LADO DERECHO. Una sola correcta.\n\nQUÉ VES. Una calle de DOBLE SENTIDO con una ISLETA alargada en el centro y un bolardo de señalización en su extremo.\n\nLA ISLETA SE DEJA SIEMPRE A LA IZQUIERDA. En una calzada de doble sentido, pasas por la DERECHA de la isleta: así sigues en tu mitad de la calzada.\n\n«POR SU LADO IZQUIERDO» es meterte en el sentido contrario.\n\n«POR CUALQUIER LADO» es el cebo cómodo: solo valdría si una señal lo permitiera expresamente.\n\nCLAVE: isleta en el centro de una calle de doble sentido = por la derecha. Es la misma lógica que en la rotonda (compárala con la 6378). Ver Leyes → «Carril: dónde debes circular»."},{"id":7962,"bg":"При тази ситуация задължени ли сте да пропуснете товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917864.png","v":null,"a":[{"t":"да, независимо от посоката, в която ще продължи да се движи","ok":true,"i":null,"es":"sí, independientemente de la dirección en que continúe"},{"t":"зависи от посоката, в която ще продължи да се движи","ok":false,"i":null,"es":"depende de la dirección"},{"t":"не","ok":false,"i":null,"es":"no"}],"sim":0.75,"es":"En esta situación ¿está obligado a ceder el paso al camión?","explain":"SÍ, INDEPENDIENTEMENTE DE LA DIRECCIÓN EN QUE CONTINÚE.\n\nQUÉ VES. Vas recto (flecha). En el poste de la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. Por la derecha llega un CAMIÓN azul. En los accesos de la izquierda y de enfrente hay señales de ceda el paso.\n\nLOS DOS ESTÁIS EN LA VÍA CON PRIORIDAD. El trazo grueso une tu acceso con el del camión. Entre dos vehículos que circulan por la preferente decide la regla de la derecha, y el camión está a tu derecha: pasa él primero.\n\nNO DEPENDE DE ADÓNDE VAYA ÉL. El orden de paso se decide por la vía y la posición, no por la trayectoria que el otro vaya a tomar.\n\n«DEPENDE DE LA DIRECCIÓN» es el cebo: parece lógico pensar que, si gira hacia otro lado, no te estorba. Pero el orden de paso no cambia según su maniobra.\n\n«NO» ignora el panel: si solo miraras el rombo, creerías que tienes prioridad sobre todos.\n\nCLAVE: es la misma escena que la 7963, preguntada de otra forma.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":5777,"bg":"При теглене на повреден автомобил е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"теглене при намалена видимост под 50 метра","ok":true,"i":null,"es":"remolcar con visibilidad inferior a 50 metros"},{"t":"теглене с гъвкава връзка по хлъзгав път","ok":true,"i":null,"es":"remolcar con cable flexible en carretera resbaladiza"},{"t":"теглене при ограничена видимост","ok":false,"i":null,"es":"remolcar con visibilidad limitada"},{"t":"теглене с твърда връзка по хлъзгав път","ok":false,"i":null,"es":"remolcar con barra rígida en carretera resbaladiza"}],"sim":0.75,"es":"Al remolcar un vehículo averiado está PROHIBIDO: (2 correctas)","explain":"⚠️ TRAMPA: prohibido con visibilidad bajo 50m Y con cable flexible en vía resbaladiza. Con barra rígida en vía resbaladiza SÍ está permitido — la barra da más control que el cable."},{"id":8296,"bg":"При заплащане на глоба за изършено нарушение, наложена с електронен фиш, в 14-дневен срок от получаването на фиша:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"се заплаща 70% от размера на глобата","ok":true,"i":null,"es":"el 70% del importe de la multa"},{"t":"се заплаща пълния размера на глобата","ok":false,"i":null,"es":"el 100% (importe completo)"},{"t":"се заплаща 50% от размера на глобата","ok":false,"i":null,"es":"el 50%"}],"sim":0.75,"es":"Al pagar una multa por sanción electrónica en los primeros 14 días desde su recepción, se paga:","explain":"⚠️ TRAMPA: pago anticipado = 70% (descuento del 30%). No el 50% ni el 100%. Bulgaria aplica un descuento del 30% por pago dentro de 14 días."},{"id":11409,"bg":"При служебно прекратяване на регистрацията на ППС със съставянето на акта за установяване на административното нарушение се отнемат:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"табелите с регистрационен номер","ok":true,"i":null,"es":"las placas de matrícula"},{"t":"част 2 на свидетелството за регистрация на ППС","ok":true,"i":null,"es":"la parte 2 del permiso de circulación"},{"t":"част 1 на свидетелството за регистрация ППС","ok":false,"i":null,"es":"la parte 1 del permiso de circulación"}],"sim":0.75,"es":"Al cancelar de oficio el registro de un vehículo, se retiran: (2 correctas)","explain":"⚠️ TRAMPA: se retiran las matrículas Y la parte 2 del permiso (ficha técnica). La parte 1 (carta de circulación) la conserva el propietario."},{"id":11448,"bg":"Когато контролните органи отнемат табелите с регистрационен номер на МПС, то трябва да бъде транспортирано до място за съхранение:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 2 часа от установяване на нарушението","ok":false,"i":null,"es":"hasta 2 horas tras el establecimiento de la infracción"},{"t":"до 12 часа от установяване на нарушението","ok":true,"i":null,"es":"hasta 12 horas"},{"t":"до 24 часа от установяване на нарушението","ok":false,"i":null,"es":"hasta 24 horas"}],"sim":0.75,"es":"Cuando las autoridades retiran las matrículas de un vehículo, debe ser trasladado a depósito:","explain":"⚠️ TRAMPA: 12 horas (no 2 ni 24). El plazo para trasladar el vehículo al depósito es exactamente 12 horas desde la detección de la infracción."},{"id":11814,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828334.png","v":null,"a":[{"t":"товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра","ok":true,"i":null,"es":"camiones con masa máxima autorizada superior a 3500 kg y longitud superior a 7 metros"},{"t":"товарните автомобили с допустима максимална маса над 2500 kg и дължина над 5 метра","ok":false,"i":null,"es":"camiones con masa superior a 2500 kg y longitud superior a 5 metros"},{"t":"всички товарни автомобили","ok":false,"i":null,"es":"todos los camiones"}],"sim":0.73,"es":"Con esta señal de identificación se marcan:","explain":"CAMIONES DE MÁS DE 3500 kg Y DE MÁS DE 7 m DE LONGITUD. Una sola correcta.\n\nQUÉ VES. La parte trasera de un camión con dos placas verticales de FRANJAS DIAGONALES ROJAS Y AMARILLAS.\n\nLAS FRANJAS DIAGONALES las llevan los camiones que cumplen LAS DOS condiciones: más de 3500 kg y más de 7 m.\n\n«MÁS DE 2500 kg Y MÁS DE 5 m» inventa otras cifras. «TODOS LOS CAMIONES» olvida las dos condiciones.\n\nCLAVE: compárala con la 11813 y la 11815."},{"id":11627,"bg":"Моторни превозни средства със специален режим на движение са автомобилите и мотоциклетите, които при движението си подават:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"светлинен сигнал с проблясваща синя и/или червена светлина и специален звуков сигнал","ok":true,"i":null,"es":"señal luminosa de luz azul y/o roja parpadeante Y señal acústica especial"},{"t":"светлинен сигнал с проблясваща синя и/или червена светлина","ok":false,"i":null,"es":"solo señal luminosa de luz azul y/o roja parpadeante"},{"t":"специален звуков сигнал","ok":false,"i":null,"es":"solo señal acústica especial"},{"t":"светлинен сигнал с жълта пробляскваща светлина","ok":false,"i":null,"es":"señal luminosa de luz amarilla parpadeante"}],"sim":0.73,"es":"Los vehículos de motor con régimen especial de circulación son los que usan:","explain":"⚠️ TRAMPA: AMBAS señales son necesarias (luz + sonido). Solo con la luz azul o solo con el sonido no es régimen especial. La luz amarilla es para vehículos de servicio, no de emergencia."},{"id":6438,"bg":"При тази ситуация, на водача на червения автомобил е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64417.png","v":null,"a":[{"t":"да продължи движението си в същата пътна лента","ok":true,"i":null,"es":"continuar en el mismo carril"},{"t":"да премине в дясната пътна лента","ok":true,"i":null,"es":"pasar al carril DERECHO"},{"t":"да премине в лявата пътна лента","ok":false,"i":null,"es":"pasar al carril IZQUIERDO"}],"sim":0.71,"es":"En esta situación al conductor del coche rojo le está PERMITIDO: (2 correctas)","explain":"⚠️ TRAMPA: puede quedarse en su carril O pasar al DERECHO. El izquierdo está prohibido en esta situación específica."},{"id":5780,"bg":"Разрешено ли е теглене на повреден автомобил, когато пътят е хлъзгав?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, но само с твърда връзка","ok":true,"i":null,"es":"sí, pero solo con barra RÍGIDA"},{"t":"да, но само с гъвкава връзка","ok":false,"i":null,"es":"sí, pero solo con cable FLEXIBLE"},{"t":"да, без ограничение","ok":false,"i":null,"es":"sí, sin restricciones"},{"t":"не","ok":false,"i":null,"es":"no"}],"sim":0.71,"es":"¿Está permitido remolcar en carretera resbaladiza?","explain":"⚠️ TRAMPA: solo con barra RÍGIDA en carretera resbaladiza. El cable flexible está prohibido porque sin tracción el vehículo remolcado puede desviarse peligrosamente."},{"id":9856,"bg":"На кръстовище, на пешеходците е разрешено да преминават през платното за движение по продължението на тротоара:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044567.png","v":null,"a":[{"t":"когато продължението е очертано с пътна маркировка","ok":true,"i":null,"es":"cuando el prolongamiento está marcado con líneas"},{"t":"когато продължението не е очертано с пътна маркировка","ok":true,"i":null,"es":"cuando el prolongamiento NO está marcado"},{"t":"само когато това е указано с пътен знак","ok":false,"i":null,"es":"solo cuando hay señal específica"},{"t":"само когато продължението е очертано с пътна маркировка тип “Зебра”","ok":false,"i":null,"es":"solo cuando hay paso tipo cebra"}],"sim":0.7,"es":"En intersección, los peatones pueden cruzar por el prolongamiento de la acera: (2 correctas)","explain":"CUANDO LA PROLONGACIÓN ESTÁ MARCADA CON MARCAS VIALES Y CUANDO NO LO ESTÁ. Dos correctas.\n\nQUÉ VES. Un cruce con señal de vía con prioridad y pasos tipo cebra pintados en las calles.\n\nQUÉ DICE ESTO EN LA PRÁCTICA. En una intersección, los peatones pueden cruzar la calzada por la prolongación imaginaria de la acera, aunque allí no haya nada pintado. Ese cruce es legítimo y el conductor debe contar con él.\n\nPOR ESO LAS DOS OPCIONES QUE PARECEN OPUESTAS SON AMBAS CORRECTAS: la ley no distingue: marcado o sin marcar, el peatón puede cruzar por ahí.\n\n«SOLO CUANDO LO INDICA UNA SEÑAL» y «SOLO CUANDO ES DE TIPO CEBRA» son las falsas, y otra vez el problema es la palabra «solo»: convierten un caso válido en el único válido.\n\nQUÉ SIGNIFICA PARA TI AL VOLANTE. Al girar en una intersección, la prolongación de la acera que vas a cruzar es zona de peatones aunque el asfalto esté liso. Girar mirando solo a los coches es el error que más atropellos causa en ciudad.\n\nCLAVE: es la gemela de la 9854 aplicada a las esquinas. Misma doctrina: la protección del peatón no depende de la pintura.\n\nMÉTODO CON PEATONES: la protección no depende de que el paso esté pintado ni de que haya señal. Depende de que el peatón esté cruzando donde tiene derecho. Ver Leyes → «Paso de peatones»."},{"id":8299,"bg":"Какво наказание се налага на водач, когато за период от една година има влезли в сила две наказателни постановления за неосигуряване на предимство на пешеходци на пешеходна пътека?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso de conducir"},{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"}],"sim":0.7,"es":"¿Qué sanción se impone a un conductor con dos sanciones firmes en un año?","explain":"⚠️ TRAMPA: AMBAS sanciones se aplican — multa Y privación del permiso. No es una u otra — son acumulativas por reincidencia."},{"id":11411,"bg":"Водач, който се движи в платното за насрещно движение по автомагистрала и/или скоростен път, се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"},{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso"}],"sim":0.7,"es":"El conductor que circula por el carril contrario en autopista/vía rápida es sancionado con:","explain":"⚠️ TRAMPA: infracción grave = multa Y privación del permiso simultáneamente. Las infracciones graves en Bulgaria siempre conllevan ambas sanciones."},{"id":11413,"bg":"Водач, който oрганизира или участва в нерегламентирани състезания по пътищата, отворени за обществено ползване се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"},{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso"}],"sim":0.7,"es":"El conductor que organiza o participa en carreras no autorizadas en vías públicas es sancionado con:","explain":"⚠️ TRAMPA: carreras ilegales = multa Y privación del permiso. Infracción muy grave con doble sanción."},{"id":11415,"bg":"Водач, който ползва пътищата, отворени за обществено ползване за други цели, освен в съответствие с тяхното предназначение се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"},{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso"}],"sim":0.7,"es":"El conductor que usa las vías públicas para fines distintos a la circulación es sancionado con:","explain":"⚠️ TRAMPA: uso ilegal de vía pública = multa Y privación. Mismo patrón que otras infracciones graves."},{"id":11728,"bg":"Водач, който превиши разрешената максимална скорост за движение в населено място с над 50 km/h се наказва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само с глоба","ok":false,"i":null,"es":"solo multa"},{"t":"само с лишаване от право да управлява МПС","ok":false,"i":null,"es":"solo privación del permiso"},{"t":"с глоба и лишаване от право да управлява МПС","ok":true,"i":null,"es":"multa Y privación del permiso"}],"sim":0.7,"es":"El conductor que supera el límite de velocidad en zona urbana en más de 50 km/h es sancionado con:","explain":"⚠️ TRAMPA: exceso grave de velocidad (+50 km/h en ciudad) = multa Y privación del permiso. El patrón 'ambas sanciones' es para infracciones muy graves."},{"id":6163,"bg":"В кой случай ефектът от действието на антиблокиращата спирачна система (ABS) е най–голям?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при спиране на хлъзгъв път","ok":true,"i":null,"es":"al frenar en carretera resbaladiza"},{"t":"при спиране на сух път","ok":false,"i":null,"es":"al frenar en carretera seca"},{"t":"когато накладките на спирачните механизми са износени","ok":false,"i":null,"es":"cuando las pastillas de freno están desgastadas"}],"sim":0.67,"es":"¿Cuándo es mayor el efecto del sistema ABS?","explain":"⚠️ TRAMPA: ABS es más eficaz en carretera RESBALADIZA. En seco un conductor experimentado puede frenar igual de bien. El ABS existe precisamente para situaciones de baja adherencia."},{"id":5450,"bg":"Пониженото ниво на коя от изброените течности може да причини пътнотранспортно произшествие?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"на течността в спирачната система","ok":true,"i":null,"es":"el líquido del sistema de FRENOS"},{"t":"на течността в охладителната система","ok":false,"i":null,"es":"el líquido del sistema de refrigeración"},{"t":"на маслото в трансмисията","ok":false,"i":null,"es":"el aceite de la transmisión"}],"sim":0.67,"es":"¿El nivel bajo de qué líquido puede causar un accidente?","explain":"⚠️ TRAMPA: el líquido de FRENOS — si baja, los frenos fallan directamente. El refrigerante bajo puede dañar el motor pero no causa un fallo inmediato de seguridad activa."},{"id":8246,"bg":"Триколесно МПС задвижвано от електродвигател, с конструктивна максимална скорост не по-висока от 45 km/h, се управлява с правоспособност за категория АМ ако максималната постоянна номинална мощност на двигателя е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"не повече от 3 kW","ok":false,"i":null,"es":"no más de 3 kW"},{"t":"не повече от 4 kW","ok":true,"i":null,"es":"no más de 4 kW"},{"t":"не повече от 5 kW","ok":false,"i":null,"es":"no más de 5 kW"},{"t":"не повече от 6 kW","ok":false,"i":null,"es":"no más de 6 kW"}],"sim":0.67,"es":"Vehículo de tres ruedas eléctrico con velocidad máxima ≤45 km/h, tiene una potencia máxima de:","explain":"⚠️ TRAMPA: el límite para este tipo de vehículo eléctrico de 3 ruedas es 4 kW (no 3, 5 ni 6). Número específico a memorizar."},{"id":6051,"bg":"Когато пътепоказателите са повредени, как трябва да сигнализирате преди заобикаляне с отклонение наляво?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"с изпъната встрани лява ръка","ok":true,"i":null,"es":"con el brazo IZQUIERDO extendido lateralmente"},{"t":"с вдигната вертикално нагоре ръка","ok":false,"i":null,"es":"con el brazo levantado verticalmente"},{"t":"с изпъната встрани дясна ръка","ok":false,"i":null,"es":"con el brazo DERECHO extendido lateralmente"},{"t":"не съм задължен да сигнализирам","ok":false,"i":null,"es":"no estoy obligado a señalizar"}],"sim":0.67,"es":"Con los intermitentes averiados, ¿cómo señalizas antes de rodear un obstáculo desviándote a la izquierda?","explain":"⚠️ TRAMPA: brazo IZQUIERDO extendido = señal de giro/desvío a la izquierda. El brazo derecho es para la derecha. Brazo levantado = parada. Siempre se señaliza."},{"id":6057,"bg":"Сигналът за маневра, подаден със светлинен пътепоказател, трябва да бъде прекратен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"непосредствено след приключване на маневрата","ok":true,"i":null,"es":"inmediatamente DESPUÉS de completar la maniobra"},{"t":"непосредствено след започване на маневрата","ok":false,"i":null,"es":"inmediatamente al INICIO de la maniobra"},{"t":"по време на извършване на маневрата","ok":false,"i":null,"es":"DURANTE la ejecución de la maniobra"},{"t":"непосредствено преди приключване на маневрата","ok":false,"i":null,"es":"inmediatamente ANTES de completar la maniobra"}],"sim":0.67,"es":"La señal de maniobra con intermitente luminoso debe cancelarse:","explain":"⚠️ TRAMPA temporal: DESPUÉS de completar, no antes ni durante. El intermitente se mantiene encendido durante toda la maniobra y se apaga al terminar."},{"id":5936,"bg":"Този пътен знак предупреждава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41210.png","v":null,"a":[{"t":"за приближаване към подвижен мост","ok":true,"i":null,"es":"de la proximidad de un PUENTE MÓVIL"},{"t":"за приближаване към повреден мост","ok":false,"i":null,"es":"de la proximidad de un puente dañado"},{"t":"че пътят води до кей или бряг","ok":false,"i":null,"es":"que el camino lleva a un muelle o ribera"},{"t":"че пътят е затворен за движение","ok":false,"i":null,"es":"que la vía está cerrada"}],"sim":0.67,"es":"Esta señal advierte:","explain":"DE LA PROXIMIDAD DE UN PUENTE MÓVIL. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con un PUENTE LEVADIZO (un tablero que se levanta) sobre el AGUA.\n\nEL TABLERO LEVANTADO es el puente móvil: puede estar abierto para dejar pasar barcos.\n\n«MUELLE O RIBERA» es el cebo más parecido: ese dibujo es un coche cayendo al agua desde un borde (compárala con la 5939).\n\n«PUENTE DAÑADO» y «VÍA CERRADA» no son el significado.\n\nCLAVE: tablero levantado = puente móvil; coche cayendo = muelle. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6220,"bg":"Пътният знак с допълнителна табела предупреждават че:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53872.png","v":null,"a":[{"t":"разстоянието до участъка с последователни опасни завои е 50 м","ok":true,"i":null,"es":"la DISTANCIA hasta el tramo de curvas sucesivas es 50 m"},{"t":"дължината на участъка с последователни опасни завои е 50 м","ok":false,"i":null,"es":"la LONGITUD del tramo de curvas sucesivas es 50 m"},{"t":"разстоянието от знака до края на участъка с последователни завои е 50 м","ok":false,"i":null,"es":"la distancia hasta el FINAL del tramo es 50 m"}],"sim":0.67,"es":"La señal y tablilla advierten que:","explain":"LA DISTANCIA HASTA EL TRAMO DE CURVAS SUCESIVAS ES 50 m. Una sola correcta.\n\nQUÉ VES. Carretera con curvas balizadas. A la derecha, el triángulo de CURVAS SUCESIVAS con una placa debajo: «50 m», sin flechas (ampliada en la imagen).\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso (dónde empieza lo marca la distancia normal de colocación: 50-100 m en población, 100-150 m fuera).\n\n«LA LONGITUD ES 50 m» es el cebo: llevaría las flechas (compárala con la 6238).\n\nCLAVE: cifra sola = cuánto falta. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6238,"bg":"Пътният знак с допълнителна табела предупреждават че:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53982.png","v":null,"a":[{"t":"дължината на участъка с последователни опасни завои е 1000 м","ok":true,"i":null,"es":"la LONGITUD del tramo de curvas peligrosas es 1000 m"},{"t":"разстоянието до участъка с последователни опасни завои е 1000 м","ok":false,"i":null,"es":"la DISTANCIA hasta el tramo es 1000 m"},{"t":"разстоянието от знака до края на участъка с последователни завои е 1000 м","ok":false,"i":null,"es":"la distancia hasta el FINAL del tramo es 1000 m"}],"sim":0.67,"es":"La señal y tablilla advierten que:","explain":"LA LONGITUD DEL TRAMO DE CURVAS PELIGROSAS ES 1000 m. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6225: triángulo de CURVAS SUCESIVAS con la placa «↑ 1000 m ↑».\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso (dónde empieza lo marca la distancia normal de colocación: 50-100 m en población, 100-150 m fuera).\n\n«LA DISTANCIA HASTA EL TRAMO» sería la cifra sola (compárala con la 6220).\n\nCLAVE: compárala con la 6225 y la 6224. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6287,"bg":"На какво разстояние след знака, когато е поставен извън населено място, се намира опасният завой?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55851.png","v":null,"a":[{"t":"от 100 до 150 м","ok":true,"i":null,"es":"entre 100 y 150 m"},{"t":"от 150 до 200 м","ok":false,"i":null,"es":"entre 150 y 200 m"},{"t":"от 200 до 500 м","ok":false,"i":null,"es":"entre 200 y 500 m"},{"t":"над 500 м","ok":false,"i":null,"es":"más de 500 m"}],"sim":0.67,"es":"¿A qué distancia después de la señal, colocada fuera de población, está la curva peligrosa?","explain":"ENTRE 100 Y 150 m. Una sola correcta.\n\nLA SEÑAL. Triángulo de CURVA PELIGROSA a la derecha, colocado FUERA de población.\n\nLAS SEÑALES DE PELIGRO SE COLOCAN ANTES DEL PELIGRO:\n• fuera de población: de 100 a 150 m;\n• en población: de 50 a 100 m.\n\n«150-200 m», «200-500 m» y «más de 500 m» son demasiado lejos: si la distancia es distinta, lo indica una placa.\n\nCLAVE: compárala con la 11888 y la 6288. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6288,"bg":"На какво разстояние след знака, когато е поставен в населено място, се намира пешеходната пътека?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55888.png","v":null,"a":[{"t":"от 50 до 100 м","ok":true,"i":null,"es":"entre 50 y 100 m"},{"t":"от 100 до 150 м","ok":false,"i":null,"es":"entre 100 y 150 m"},{"t":"не повече от 50 м","ok":false,"i":null,"es":"no más de 50 m"},{"t":"непосредствено след знака","ok":false,"i":null,"es":"inmediatamente después"}],"sim":0.67,"es":"¿A qué distancia después de la señal, colocada en zona urbana, está el paso de peatones?","explain":"ENTRE 50 Y 100 m. Una sola correcta.\n\nLA SEÑAL. Triángulo de PASO DE PEATONES, colocado EN población.\n\nEN POBLACIÓN, LAS SEÑALES DE PELIGRO van de 50 a 100 m antes del peligro (fuera de población, de 100 a 150 m).\n\n«100-150 m» es la distancia fuera de población. «NO MÁS DE 50 m» e «INMEDIATAMENTE DESPUÉS» no dejan tiempo para reaccionar.\n\nCLAVE: compárala con la 6287 y la 11888. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6291,"bg":"При тази ситуация на какво разстояние трябва да очакваме опасния завой, за който ни предупреждава пътният знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55978.png","v":null,"a":[{"t":"от 100 до 150 м","ok":true,"i":null,"es":"entre 100 y 150 m"},{"t":"от 50 до 100 м","ok":false,"i":null,"es":"entre 50 y 100 m"},{"t":"на повече от 200 м","ok":false,"i":null,"es":"más de 200 m"},{"t":"на повече от 50 м","ok":false,"i":null,"es":"más de 50 m"}],"sim":0.67,"es":"En esta situación, ¿a qué distancia debemos esperar la curva que advierte la señal?","explain":"ENTRE 100 Y 150 m. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población con varios vehículos delante. A la derecha, un triángulo de CURVA PELIGROSA a la izquierda.\n\nFUERA DE POBLACIÓN, LAS SEÑALES DE PELIGRO van de 100 a 150 m antes del peligro (en población, de 50 a 100 m). Si la distancia fuera otra, lo diría una placa.\n\n«50-100 m» es la distancia en población. «MÁS DE 200 m» y «MÁS DE 50 m» no son la regla.\n\nCLAVE: compárala con la 6287 y la 11888. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6293,"bg":"При тази ситуация, на какво разстояние след пътния знак се намира пешеходната пътека?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56031.png","v":null,"a":[{"t":"от 50 до 100 м","ok":true,"i":null,"es":"entre 50 y 100 m"},{"t":"до 50 м","ok":false,"i":null,"es":"hasta 50 m"},{"t":"от 100 до 150 м","ok":false,"i":null,"es":"entre 100 y 150 m"},{"t":"на 200 м","ok":false,"i":null,"es":"a 200 m"}],"sim":0.67,"es":"En esta situación, ¿a qué distancia después de la señal está el paso de peatones?","explain":"ENTRE 50 Y 100 m. Una sola correcta.\n\nQUÉ VES. Calle urbana de varios carriles con un coche rojo y un camión delante. A la derecha, el triángulo de PASO DE PEATONES.\n\nEN POBLACIÓN, LAS SEÑALES DE PELIGRO van de 50 a 100 m antes del peligro.\n\n«HASTA 50 m» no deja tiempo para frenar. «100-150 m» es la distancia fuera de población. «200 m» no es la regla.\n\nCLAVE: compárala con la 6288 y la 11888. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5428,"bg":"На какво разстояние зад МПС, принудително спряло на автомагистрала, се поставя предупредителният светлоотразителен триъгълник?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"не по-малко от 100 м","ok":true,"i":null,"es":"no menos de 100 m"},{"t":"не по-малко от 30 м","ok":false,"i":null,"es":"no menos de 30 m"},{"t":"не по-малко от 50 м","ok":false,"i":null,"es":"no menos de 50 m"},{"t":"не по-малко от 70 м","ok":false,"i":null,"es":"no menos de 70 m"}],"sim":0.67,"es":"¿A qué distancia detrás de un vehículo averiado en autopista se coloca el triángulo de emergencia?","explain":"⚠️ TRAMPA de distancias: autopista = 100m mínimo. Ciudad = 30m. Carretera convencional = 30m también. Solo en autopista es 100m por las altas velocidades."},{"id":6087,"bg":"При тази ситуация, на път извън населено място, на водачите е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/140619.png","v":null,"a":[{"t":"да се движат в най-дясната свободна пътна лента","ok":true,"i":null,"es":"circular en el carril derecho disponible"},{"t":"да се движат в средната пътна лента, когато дясната е заета","ok":true,"i":null,"es":"usar el carril central cuando el derecho está ocupado"},{"t":"да навлизат в средната лента при изпреварване","ok":true,"i":null,"es":"entrar en el carril central para adelantar"},{"t":"да навлизат в крайната лява лента при изпреварване","ok":false,"i":null,"es":"entrar en el carril izquierdo para adelantar"}],"sim":0.67,"es":"En esta situación fuera de población, en 3 carriles, está PERMITIDO: (3 correctas)","explain":"CIRCULAR POR EL CARRIL DERECHO DISPONIBLE, USAR EL CENTRAL CUANDO EL DERECHO ESTÁ OCUPADO Y ENTRAR EN EL CENTRAL PARA ADELANTAR. Tres correctas.\n\nQUÉ VES. La misma escena que la 6085: fuera de población, TRES carriles; la señal azul indica DOS carriles en tu sentido (flechas hacia arriba) y UNO en sentido contrario (flecha hacia abajo, el de la izquierda).\n\nTUS CARRILES SON EL DERECHO Y EL CENTRAL. Vas por el derecho si está libre; usas el central cuando el derecho está ocupado o para adelantar.\n\n«ENTRAR EN EL CARRIL IZQUIERDO PARA ADELANTAR» es el cebo: según la señal, ese carril es del sentido contrario.\n\nCLAVE: lee primero la señal de carriles: cuántas flechas son tuyas y cuántas del otro sentido. Ver Leyes → «Carril: dónde debes circular»."},{"id":6404,"bg":"При тази ситуация няма да извърша нарушение ако:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64182.png","v":null,"a":[{"t":"премина в дясната пътна лента","ok":true,"i":null,"es":"paso al carril derecho"},{"t":"продължа движението си в същата пътна лента","ok":true,"i":null,"es":"continúo en el mismo carril"},{"t":"премина в лявата пътна лента","ok":false,"i":null,"es":"paso al carril izquierdo"},{"t":"спра пред светофара, в лентата, над която е поставен","ok":false,"i":null,"es":"paro ante el semáforo en mi carril"}],"sim":0.67,"es":"En esta situación no cometo infracción si: (2 correctas)","explain":"⚠️ TRAMPA: puedo quedarme en mi carril O pasar al derecho. El izquierdo y parar en el carril incorrecto son infracciones."},{"id":6432,"bg":"При тази ситуация ще извърша нарушение ако:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64279.png","v":null,"a":[{"t":"продължа движението си в същата пътна лента","ok":true,"i":null,"es":"continúo en el mismo carril"},{"t":"премина в лявата пътна лента","ok":true,"i":null,"es":"paso al carril izquierdo"},{"t":"спра пред светофара, в лентата, над която е поставен","ok":true,"i":null,"es":"paro ante el semáforo en mi carril"},{"t":"премина в дясната пътна лента","ok":false,"i":null,"es":"paso al carril derecho"}],"sim":0.67,"es":"En esta situación COMETERÉ infracción si: (3 correctas)","explain":"SEGUIR EN EL MISMO CARRIL, PASAR AL CARRIL IZQUIERDO Y PARARSE ANTE EL SEMÁFORO EN SU CARRIL. Tres correctas (son las tres infracciones).\n\nQUÉ VES. Un pórtico con semáforos de carril. Sobre TU carril hay un ASPA ROJA: ese carril está cerrado. El carril de tu derecha no tiene aspa.\n\nEL ASPA ROJA TE OBLIGA A SALIR DE ESE CARRIL hacia uno abierto. Por eso son infracción:\n• seguir por el mismo carril (está cerrado);\n• pasar al carril izquierdo (no es el carril abierto que te corresponde);\n• pararte bajo el aspa (el aspa no significa «para», significa «deja este carril»).\n\nLO ÚNICO CORRECTO es pasar al carril DERECHO.\n\nCLAVE: la pregunta pide las infracciones; marca todo lo que NO sea cambiarte al carril abierto. Compárala con la 5933 y la 6443. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5838,"bg":"За стабилно и сигурно движение на превозното средство, стойността на коефициента на сцепление на автомобилните гуми с пътя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да е възможно по-голяма","ok":true,"i":null,"es":"lo más GRANDE posible"},{"t":"трябва да е възможно по-малка","ok":false,"i":null,"es":"lo más PEQUEÑO posible"},{"t":"е без значение","ok":false,"i":null,"es":"no tiene importancia"}],"sim":0.67,"es":"Para una circulación estable y segura, el coeficiente de rozamiento debe ser:","explain":"⚠️ TRAMPA: cuanto MAYOR es el rozamiento, mayor es la adherencia y más seguro el frenado. Mayor rozamiento = más seguro. Menor rozamiento (hielo, lluvia) = peligroso."},{"id":5856,"bg":"Блокирането на колелата на превозното средство при спиране може да доведе до:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"влошаване управляемостта на превозното средство","ok":true,"i":null,"es":"EMPEORAMIENTO de la manejabilidad"},{"t":"подобряване управляемостта на превозното средство","ok":false,"i":null,"es":"MEJORA de la manejabilidad"},{"t":"увеличаване сцеплението на гумите с пътя","ok":false,"i":null,"es":"aumento del rozamiento de los neumáticos con el asfalto"}],"sim":0.67,"es":"El bloqueo de las ruedas durante el frenado puede provocar:","explain":"⚠️ TRAMPA: bloquear ruedas = EMPEORA la manejabilidad (el coche no responde a la dirección). El ABS existe precisamente para evitar el bloqueo y mantener la dirección."},{"id":5858,"bg":"Какво влияние оказва върху дължината на спирачния път блокирането на колелата при спиране?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"увеличава дължината на спирачния път","ok":true,"i":null,"es":"AUMENTA la distancia de frenado"},{"t":"не оказва влияние върху дължината на спирачния път","ok":false,"i":null,"es":"no tiene efecto"},{"t":"намалява дължината на спирачния път","ok":false,"i":null,"es":"REDUCE la distancia de frenado"}],"sim":0.67,"es":"¿Qué efecto tiene el bloqueo de ruedas en la distancia de frenado?","explain":"⚠️ TRAMPA: bloquear ruedas AUMENTA la distancia de frenado y hace patinar el coche. El frenado controlado (sin bloqueo) es más corto y efectivo."},{"id":5861,"bg":"След пътния знак движението трябва да се извършва на дистанция от предния автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57706.png","v":null,"a":[{"t":"не по-малка от 70 м","ok":true,"i":null,"es":"no MENOS de 70 m"},{"t":"не по-голяма от 70 м","ok":false,"i":null,"es":"no MÁS de 70 m"}],"sim":0.67,"es":"Después de esta señal, la distancia de seguridad con el vehículo de delante debe ser:","explain":"NO MENOS DE 70 m. Una sola correcta.\n\nQUÉ VES. Carretera con dos carriles en tu sentido. A la derecha, una señal circular de borde ROJO con DOS VEHÍCULOS y la cifra «70 m». Delante circulan un camión, un coche rojo y un coche azul.\n\nUN CÍRCULO ROJO PROHÍBE. Esta señal prohíbe circular a una distancia MENOR de 70 m del vehículo de delante. Es decir: la distancia debe ser de 70 m como mínimo.\n\n«NO MÁS DE 70 m» es el cebo: invierte el sentido. Nadie te obliga a ir más cerca; lo que se prohíbe es acercarse demasiado.\n\nCLAVE: señal de distancia mínima = «no menos de» la cifra.\n\nMÉTODO: 1) ¿qué forma y color tiene la señal? 2) círculo rojo = prohibición 3) ¿qué prohíbe? ir más cerca de lo indicado. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11707,"bg":"Каква трябва да бъде скоростта на движение, когато широчината на пътя не позволява разминаване без допълнителни мерки за сигурност?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"такава, че водачът да може да спре на половината от дължината на пътя, който вижда","ok":true,"i":null,"es":"tal que el conductor pueda parar en la MITAD de la distancia que ve"},{"t":"не по-голяма от 50 km/h","ok":false,"i":null,"es":"no superior a 50 km/h"},{"t":"такава, че водачът да може да спре в зоната на пътя, който вижда","ok":false,"i":null,"es":"tal que pueda parar en toda la distancia que ve"}],"sim":0.67,"es":"¿Qué velocidad usar cuando la anchura de la vía no permite el cruce sin retroceder?","explain":"⚠️ TRAMPA: la velocidad debe ser tal que puedas frenar en la MITAD de lo que ves (para dejar margen al otro). No toda la distancia visible ni un límite fijo de 50 km/h."},{"id":6358,"bg":"Как се извършва завиването в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"чрез движение със завиване наляво","ok":true,"i":null,"es":"mediante un giro a la IZQUIERDA"},{"t":"чрез движение със завиване надясно","ok":false,"i":null,"es":"mediante un giro a la DERECHA"}],"sim":0.67,"es":"¿Cómo se realiza el cambio de sentido?","explain":"⚠️ TRAMPA: siempre por la IZQUIERDA. Dar la vuelta = giro a la izquierda. Nunca a la derecha (eso sería dar una vuelta completa a la manzana)."},{"id":6526,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57381.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder el paso al coche rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder el paso al azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"sim":0.67,"es":"En esta situación debo: (2 correctas)","explain":"CEDER EL PASO AL COCHE ROJO Y PASAR ANTES QUE EL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay una señal de VÍA CON PRIORIDAD (rombo, sin panel). Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. De frente viene un coche ROJO. Por la DERECHA, por la vía transversal, llega una furgoneta AZUL.\n\nAL ROJO LE CEDES: viene de frente por la misma vía preferente que tú, y el que gira a la izquierda cede al que viene de frente.\n\nAL AZUL LE PASAS TÚ: viene por la vía secundaria, así que te cede aunque esté a tu derecha.\n\n«CEDER AL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: el rombo te da preferencia sobre la secundaria, no sobre el que viene de frente por tu misma vía. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6530,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57673.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"}],"sim":0.67,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL COCHE ROJO Y PASAR ANTES QUE EL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay un CEDA EL PASO. Vas RECTO. Por la IZQUIERDA, por la vía principal, llega un coche ROJO. De frente, por la otra vía secundaria, viene un coche AZUL con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL ROJO LE CEDES: va por la vía principal y tú llevas ceda el paso, aunque venga por tu izquierda.\n\nAL AZUL LE PASAS TÚ: también viene por una vía secundaria, así que la señal no os separa; entre vosotros, el que gira a la izquierda (el azul) cede al que va recto (tú).\n\n«CEDER AL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: primero la señal (cedo a los de la principal); entre secundarias, las reglas de giro y de la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Vía con prioridad»."},{"id":6536,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58116.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"}],"sim":0.67,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA color: pasas antes que el ROJO, cedes al AZUL. Inverso al anterior — lee la imagen con cuidado."},{"id":6537,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68558.png","v":null,"a":[{"t":"да пропусне синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да премине преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусне червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да премине преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"}],"sim":0.67,"es":"En esta situación el conductor del coche verde debe: (2 correctas)","explain":"CEDER AL AZUL Y PASAR ANTES QUE EL ROJO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. El coche VERDE (en primer plano) lleva el intermitente IZQUIERDO. Por su IZQUIERDA llega un coche ROJO; por su DERECHA, una furgoneta AZUL.\n\nSIN SEÑALES MANDA LA DERECHA. El azul le llega al verde por la derecha: el verde le cede. El rojo le llega por la izquierda: el verde pasa antes.\n\n«CEDER AL ROJO» y «PASAR ANTES QUE EL AZUL» son las respuestas al revés.\n\nCLAVE: el giro a la izquierda solo obliga a ceder a lo que viene de FRENTE; con los laterales decide la derecha. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches. Ver Leyes → «Regla de la derecha»."},{"id":6538,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58268.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"}],"sim":0.67,"es":"En esta situación debo: (2 correctas)","explain":"PASAR ANTES QUE EL ROJO Y CEDER AL AZUL. Dos correctas.\n\nQUÉ VES. En tu poste hay una señal de STOP. Vas RECTO. Por la DERECHA, por la vía principal, llega un CAMIÓN azul con el intermitente puesto. De frente, por la otra vía secundaria, viene un coche ROJO con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL CAMIÓN LE CEDES: va por la principal y tú tienes STOP.\n\nAL ROJO LE PASAS TÚ: viene por la secundaria, como tú, así que la señal no os separa; entre vosotros, el que gira a la izquierda (el rojo) cede al que va recto.\n\n«CEDER AL ROJO» y «PASAR ANTES QUE EL AZUL» son las respuestas al revés.\n\nCLAVE: el STOP te obliga ante la principal, no ante el otro de la secundaria. Compárala con la 6532. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Vía con prioridad»."},{"id":6549,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65617.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"}],"sim":0.67,"es":"En esta situación debo: (2 correctas)","explain":"PASAR ANTES QUE EL ROJO Y CEDER AL AZUL. Dos correctas.\n\nQUÉ VES. Vas RECTO. A la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la DERECHA. Por la DERECHA, sobre la rama gruesa, una furgoneta AZUL con el intermitente. De frente, por la rama fina, un coche ROJO con el intermitente.\n\nAL AZUL LE CEDES: estáis los dos en la preferente y te llega por la derecha.\n\nAL ROJO LE PASAS TÚ: viene por la secundaria.\n\n«PASAR ANTES QUE EL AZUL» y «CEDER AL ROJO» son las respuestas al revés.\n\nCLAVE: es la misma escena que la 6548 (verificada antes), con otra forma de preguntar. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6555,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68438.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"}],"sim":0.67,"es":"En esta situación debo: (2 correctas)","explain":"MÉTODO PARA RESOLVER CUALQUIER PREGUNTA DE 'A QUIÉN CEDO EL PASO': Mira la imagen y sigue este orden de comprobación: 1) ¿Hay alguna señal de STOP, ceda el paso o vía prioritaria visible? Esa señal manda sobre todo lo demás. 2) Si no hay señales, ¿qué vehículo está a tu derecha? Ese tiene prioridad sobre ti (regla del dásnostoящ). 3) ¿Algún vehículo va a girar a la izquierda cruzando tu trayectoria? Ese debe cederte el paso a ti si vienes recto o girando a la derecha. 4) ¿Tu vía termina ahí o continúa? El vehículo en la vía que continúa tiene prioridad sobre el que sale de una vía que termina. En esta pregunta concreta, la respuesta correcta es ceder al rojo y pasar antes que el azul — eso te dice que el rojo está en posición de prioridad (probablemente a tu derecha o en vía con continuidad) y el azul no."},{"id":6571,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68203.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al azul"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"}],"sim":0.67,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA color: cedes al AZUL, pasas antes que el ROJO. Inverso a otros — la imagen determina cuál tiene prioridad."},{"id":6581,"bg":"След подаването на този сигнал от светофара:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103424.png","v":null,"a":[{"t":"навлизането в кръстовището е забранено","ok":true,"i":null,"es":"está PROHIBIDO entrar en la intersección"},{"t":"трябва да се подготвя за потегляне","ok":true,"i":null,"es":"debo prepararme para ARRANCAR"},{"t":"може да завия надясно, но с повишено внимание","ok":false,"i":null,"es":"se puede girar a la derecha con precaución"},{"t":"навлизането в кръстовището е разрешено","ok":false,"i":null,"es":"está PERMITIDO entrar"}],"sim":0.67,"es":"Después de esta señal del semáforo: (2 correctas)","explain":"ESTÁ PROHIBIDO ENTRAR EN LA INTERSECCIÓN Y DEBO PREPARARME PARA ARRANCAR. Dos correctas.\n\nQUÉ VES. El semáforo de la derecha tiene encendidas a la vez la luz ROJA y la ÁMBAR.\n\nROJO + ÁMBAR = «PREPÁRATE, PERO TODAVÍA NO». Mientras el rojo siga encendido no puedes entrar. El ámbar añadido anuncia que va a llegar el verde: es el momento de preparar el arranque.\n\n«ESTÁ PERMITIDO ENTRAR» es falso mientras el rojo esté encendido.\n\n«SE PUEDE GIRAR A LA DERECHA CON PRECAUCIÓN» es el cebo: no hay flecha verde adicional que lo permita.\n\nCLAVE: rojo + ámbar = sigues parado, pero te preparas.\n\nMÉTODO: 1) ¿qué luces están encendidas? 2) ¿está el rojo? Entonces no entro. 3) ¿le acompaña el ámbar? Me preparo. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":11891,"bg":"Когато мястото за спиране преди жп прелеза се определя по отношение на релсите, разстоянието от първата релса трябва да бъде:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не по-малко от 2 метра","ok":true,"i":null,"es":"no MENOS de 2 metros"},{"t":"не повече от 2 метра","ok":false,"i":null,"es":"no MÁS de 2 metros"},{"t":"възможно най-малкото","ok":false,"i":null,"es":"la menor posible"},{"t":"по преценка на водача","ok":false,"i":null,"es":"a criterio del conductor"}],"sim":0.67,"es":"La distancia de parada antes del paso a nivel respecto a los raíles debe ser:","explain":"⚠️ TRAMPA: MÍNIMO 2 metros (no máximo). 'No menos de' = mínimo. Parar a menos de 2m de los raíles es insuficiente e ilegal."},{"id":12053,"bg":"При тази ситуация трябва да:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"осигурите предимство на зеления автомобил","ok":true,"i":null,"es":"ceder el paso al coche verde"},{"t":"осигурите предимство на червения автомобил","ok":false,"i":null,"es":"ceder el paso al coche rojo"},{"t":"изчакате преминаването на велосипедиста","ok":true,"i":null,"es":"esperar al ciclista"}],"sim":0.67,"es":"En esta situación debes: (2 correctas)","explain":"⚠️ TRAMPA: cedes al verde Y esperas al ciclista. El rojo NO tiene prioridad aquí. Lee la situación con cuidado."},{"id":5702,"bg":"Каква трябва да бъде дължината на твърдата връзка при теглене на повредено МПС?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от 2 до 4 м","ok":true,"i":null,"es":"de 2 a 4 m"},{"t":"до 2 м","ok":false,"i":null,"es":"hasta 2 m"},{"t":"от 4 до 6 м","ok":false,"i":null,"es":"de 4 a 6 m"}],"sim":0.67,"es":"¿Cuál debe ser la longitud de la barra rígida al remolcar un vehículo averiado?","explain":"⚠️ TRAMPA longitudes: barra RÍGIDA = 2-4 metros. Cable FLEXIBLE = 4-6 metros. La barra es más corta. Memoriza el par: rígida(2-4) / flexible(4-6)."},{"id":5709,"bg":"Каква трябва да бъде дължината на гъвкавата връзка (въже, верига) при теглене на повредено МПС?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от 4 до 6 м","ok":true,"i":null,"es":"de 4 a 6 m"},{"t":"от 2 до 3 м","ok":false,"i":null,"es":"de 2 a 3 m"},{"t":"от 3 до 4 м","ok":false,"i":null,"es":"de 3 a 4 m"},{"t":"до 2 м","ok":false,"i":null,"es":"hasta 2 m"}],"sim":0.67,"es":"¿Cuál debe ser la longitud del cable flexible al remolcar un vehículo averiado?","explain":"⚠️ TRAMPA: cable FLEXIBLE = 4-6 metros. Barra RÍGIDA = 2-4 metros. El cable es más largo que la barra."},{"id":5544,"bg":"След този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42178.png","v":null,"a":[{"t":"е забранено спирането за престой","ok":true,"i":null,"es":"está PROHIBIDA la parada breve"},{"t":"е забранено паркирането","ok":true,"i":null,"es":"está PROHIBIDO aparcar"},{"t":"е разрешено спирането за престой","ok":false,"i":null,"es":"está PERMITIDA la parada breve"},{"t":"е разрешено паркирането","ok":false,"i":null,"es":"está PERMITIDO aparcar"}],"sim":0.67,"es":"Después de esta señal: (2 correctas)","explain":"ESTÁN PROHIBIDAS LA PARADA BREVE Y EL APARCAMIENTO. Dos correctas.\n\nQUÉ VES. Calle urbana. A la derecha, junto a la acera, la señal de DOS BARRAS EN ASPA.\n\nEL ASPA PROHÍBE LAS DOS COSAS: ni parada breve ni aparcamiento.\n\n«PERMITIDA LA PARADA BREVE» es lo que permite la señal de UNA barra (5549). «PERMITIDO APARCAR» es lo contrario.\n\nCLAVE: una barra = una prohibición; dos barras = dos. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5549,"bg":"След този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42231.png","v":null,"a":[{"t":"е разрешено спирането за престой","ok":true,"i":null,"es":"está PERMITIDA la parada breve"},{"t":"е забранено паркирането","ok":true,"i":null,"es":"está PROHIBIDO aparcar"},{"t":"е забранено спирането за престой","ok":false,"i":null,"es":"está PROHIBIDA la parada breve"},{"t":"е разрешено паркирането","ok":false,"i":null,"es":"está PERMITIDO aparcar"}],"sim":0.67,"es":"Después de esta señal: (2 correctas)","explain":"ESTÁ PERMITIDA LA PARADA BREVE Y ESTÁ PROHIBIDO APARCAR. Dos correctas.\n\nQUÉ VES. Calle urbana. A la derecha, junto a la acera con peatones, la señal de UNA sola barra (prohibido estacionar).\n\nPARADA Y ESTACIONAMIENTO, QUE SE CONFUNDEN:\n• PARADA BREVE («престой») = detenerte el tiempo justo para subir o bajar personas o cargar, sin alejarte del vehículo;\n• ESTACIONAMIENTO («паркиране») = dejar el vehículo más tiempo o alejarte de él.\n\nLAS DOS CORRECTAS SON LAS DOS CARAS DE LA MISMA BARRA: puedes parar para que baje alguien, pero no dejar el coche.\n\n«PROHIBIDA LA PARADA BREVE» describe el aspa. «PERMITIDO APARCAR» es lo contrario de la señal.\n\nCLAVE: compárala con la 5546. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5684,"bg":"Превключването от дълги на къси светлини преди разминаване през нощта се извършва, когато разстоянието между двата автомобила е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"не по-малко от 50 м","ok":false,"i":null,"es":"no menos de 50 m"},{"t":"не по-малко от 100 м","ok":false,"i":null,"es":"no menos de 100 m"},{"t":"не по-малко от 150 м","ok":true,"i":null,"es":"no menos de 150 m"},{"t":"не по-малко от 200 м","ok":false,"i":null,"es":"no menos de 200 m"}],"sim":0.67,"es":"El cambio de largas a cortas al cruzarse de noche se hace cuando la distancia es:","explain":"⚠️ TRAMPA: cambio a cortas a no menos de 150 metros. No 50, 100 ni 200. El número exacto es 150m — memorízalo."},{"id":5685,"bg":"При разминаване през нощта превключването от дълги на къси светлини е задължително, когато:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"разстоянието между превозните средства е не по-малко от 150 м","ok":true,"i":null,"es":"la distancia entre vehículos es no menos de 150 m"},{"t":"насрещният водач подаде сигнал чрез превключването на светлините","ok":true,"i":null,"es":"el conductor contrario señaliza con sus luces"},{"t":"разстоянието между превозните средства е не по-повече от 50 м","ok":false,"i":null,"es":"la distancia es no más de 50 m"}],"sim":0.67,"es":"De noche, cambiar de largas a cortas al cruzarse es OBLIGATORIO cuando: (2 correctas)","explain":"⚠️ TRAMPA: obligatorio a 150m de distancia Y cuando el contrario te señaliza. A 50m o menos ya es demasiado tarde — deberías haberlas cambiado antes."},{"id":5302,"bg":"Водачите от коя възрастова група попадат най-често в пътнотранспортни произшествия?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"от 18 до 24 години","ok":true,"i":null,"es":"de 18 a 24 años"},{"t":"от 24 до 36 години","ok":false,"i":null,"es":"de 24 a 36 años"},{"t":"от 36 до 45 години","ok":false,"i":null,"es":"de 36 a 45 años"},{"t":"от 56 до 65 години","ok":false,"i":null,"es":"de 56 a 65 años"}],"sim":0.67,"es":"¿Qué grupo de edad tiene mayor tasa de accidentes de tráfico?","explain":"⚠️ TRAMPA estadística: el grupo 18-24 años tiene el mayor riesgo — inexperiencia + conductas de riesgo. No los conductores mayores ni los de mediana edad."},{"id":6041,"bg":"Кратковременното превключване на светлините като допълнителен сигнал при извършване на маневра е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"забранено да се използва при движение в населени места","ok":false,"i":null,"es":"PROHIBIDO en zona urbana"},{"t":"разрешено да се използва при движение извън населени места","ok":true,"i":null,"es":"PERMITIDO fuera de zona urbana"},{"t":"разрешено да се използва при движение по автомобилни пътища","ok":true,"i":null,"es":"PERMITIDO en vías rápidas"},{"t":"забранено да се използва при движение по автомагистрали","ok":false,"i":null,"es":"PROHIBIDO en autopistas"}],"sim":0.64,"es":"El parpadeo de luces como señal adicional de maniobra está: (2 correctas)","explain":"⚠️ TRAMPA: el parpadeo de luces como señal de maniobra está permitido fuera de ciudad Y en vías rápidas/autopistas. Solo prohibido en ciudad."},{"id":6186,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334694.png","v":null,"a":[{"t":"задължава водачите да се движат само направо след знака","ok":true,"i":null,"es":"obliga a circular solo RECTO después de la señal"},{"t":"сигнализира за еднопосочно движение след знака","ok":false,"i":null,"es":"señaliza tráfico de sentido único después"},{"t":"указва посоката на пътя с предимство","ok":false,"i":null,"es":"indica la dirección de la vía preferente"},{"t":"препоръчва на водачите да се движат направо след знака","ok":false,"i":null,"es":"recomienda ir recto"}],"sim":0.64,"es":"Esta señal:","explain":"OBLIGA A CIRCULAR SOLO RECTO DESPUÉS DE LA SEÑAL. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con una flecha blanca recta hacia arriba.\n\nCÍRCULO AZUL = OBLIGACIÓN: en el cruce siguiente solo puedes seguir recto.\n\n«SENTIDO ÚNICO» es el CUADRADO azul con la misma flecha (compárala con la 6199).\n\n«RECOMIENDA» es el cebo: las señales azules circulares obligan. «DIRECCIÓN DE LA VÍA PREFERENTE» se indica con un panel bajo el rombo.\n\nCLAVE: compárala con la 6187. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6224,"bg":"С допълнителната табела към този пътен знак се указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53909.png","v":null,"a":[{"t":"дължината на стеснения участък от платното за движение","ok":true,"i":null,"es":"la LONGITUD del tramo estrecho"},{"t":"разстоянието до стеснения участък от платното за движение","ok":false,"i":null,"es":"la DISTANCIA hasta el tramo estrecho"},{"t":"разстоянието до края на стеснения участък от платното за движение","ok":false,"i":null,"es":"la distancia hasta el FINAL del tramo"}],"sim":0.64,"es":"La tablilla complementaria junto a esta señal indica:","explain":"LA LONGITUD DEL TRAMO ESTRECHO. Una sola correcta.\n\nQUÉ VES. Triángulo de ESTRECHAMIENTO por ambos lados con una placa debajo: «↑ 200 m ↑».\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso (dónde empieza lo marca la distancia normal de colocación: 50-100 m en población, 100-150 m fuera).\n\n«LA DISTANCIA HASTA EL TRAMO» sería la cifra sola (compárala con la 6218).\n\nCLAVE: flechas a los lados de la cifra = longitud. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11868,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828540.png","v":null,"a":[{"t":"„Забранено е влизането на товарни автомобили с допустима максимална маса над 7 t”","ok":true,"i":null,"es":"prohibida la entrada de camiones con masa autorizada superior a 7 t"},{"t":"„Забранено влизането на товарни автомобили с товароносимост над 7 t”","ok":false,"i":null,"es":"prohibida la entrada de camiones con capacidad de carga superior a 7 t"},{"t":"„Забранено влизането на товарни автомобили, на които товарът е над 7 t”","ok":false,"i":null,"es":"prohibida la entrada de camiones cuya carga supere 7 t"},{"t":"„Забранено влизането на товарни автомобили, на които натоварването на ос е над 7 t”","ok":false,"i":null,"es":"prohibida la entrada si la carga por eje supera 7 t"}],"sim":0.64,"es":"El significado de esta señal es:","explain":"«PROHIBIDA LA ENTRADA DE CAMIONES CON MASA MÁXIMA AUTORIZADA SUPERIOR A 7 t». Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con un CAMIÓN y «7 t» debajo.\n\nCAMIÓN + CIFRA = el límite es la MASA MÁXIMA AUTORIZADA del camión (la que figura en su documentación), no lo que lleva cargado en ese momento.\n\n«CAPACIDAD DE CARGA» y «CARGA SUPERIOR A 7 t» son cebos de vocabulario. «CARGA POR EJE» es la señal con el eje dibujado.\n\nCLAVE: compárala con la 5979 (la misma señal con 5 t). Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11887,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828560.png","v":null,"a":[{"t":"начало на участък с дължина 10 метра, където е забранено паркирането","ok":true,"i":null,"es":"inicio de un tramo de 10 m donde está prohibido aparcar"},{"t":"че началото на участъка, в който е забранено паркирането, е след 10 метра","ok":false,"i":null,"es":"que el inicio de la zona prohibida está a 10 m"},{"t":"края на участък с дължина 10 метра, в който е забранено паркирането","ok":false,"i":null,"es":"fin de un tramo de 10 m donde está prohibido aparcar"}],"sim":0.64,"es":"La tablilla complementaria junto a la señal indica:","explain":"INICIO DE UN TRAMO DE 10 m DONDE ESTÁ PROHIBIDO APARCAR. Una sola correcta.\n\nQUÉ VES. Señal de PROHIBIDO ESTACIONAR con una placa con una flecha VERTICAL hacia ARRIBA y «10 m» debajo.\n\nLA FLECHA HACIA DELANTE = AQUÍ EMPIEZA la zona, y la cifra dice cuánto mide: 10 m a partir de la señal.\n\n«EL INICIO ESTÁ A 10 m» confunde esta placa con la de distancia (cifra sola, sin flecha). «FIN DEL TRAMO» llevaría la flecha hacia abajo.\n\nCLAVE: compárala con la 6263 y la 6281. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5730,"bg":"При теглене с твърда връзка:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"тегличът трябва да е с дължина от 2 до 4 метра","ok":true,"i":null,"es":"la barra debe tener entre 2 y 4 metros"},{"t":"тегличът трябва да е оцветен напречно с червени и бели ивици","ok":true,"i":null,"es":"la barra debe estar pintada en franjas rojas y blancas"},{"t":"тегленото МПС трябва да бъде с изправна кормилна уредба","ok":true,"i":null,"es":"el vehículo remolcado debe tener la dirección en buen estado"},{"t":"тегленото МПС трябва да е с изправна спирачна уредба","ok":false,"i":null,"es":"el vehículo remolcado debe tener los frenos en buen estado"}],"sim":0.64,"es":"Al remolcar con barra rígida: (3 correctas)","explain":"⚠️ TRAMPA: 2-4m + franjas rojo/blanco + dirección OK = obligatorios. Los FRENOS del vehículo remolcado en barra rígida NO son obligatoriamente funcionales — con la barra el remolcador frena por los dos."},{"id":6171,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/52103.png","v":null,"a":[{"t":"„Забранено е влизането на ППС, с маса с товар, по-голяма от означената”","ok":true,"i":null,"es":"'Prohibida la entrada de vehículos con masa con carga superior a la indicada'"},{"t":"„Забранено е влизането на ППС, с товар е по-голям от означения”","ok":false,"i":null,"es":"'Prohibida la entrada de vehículos cuya carga supere lo indicado'"},{"t":"„Забранено е влизането на ППС с товароносимост по-голяма от означената”","ok":false,"i":null,"es":"'Prohibida la entrada de vehículos con capacidad de carga superior'"},{"t":"„Забранено е влизането на ППС с натоварване, на която и да е от осите по-голямо от означеното”","ok":false,"i":null,"es":"'Prohibida la entrada si la carga por eje supera lo indicado'"}],"sim":0.62,"es":"El significado de esta señal es:","explain":"«PROHIBIDA LA ENTRADA DE VEHÍCULOS CON MASA CON CARGA SUPERIOR A LA INDICADA». Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO y solo «3 t», sin ningún dibujo.\n\nLAS SEÑALES DE TONELADAS Y METROS:\n• solo «3 t» = masa total con carga;\n• «t» sobre un EJE = carga por eje;\n• «m» con flechas ARRIBA y ABAJO = altura; a los LADOS = anchura; con un camión y flechas delante y detrás = longitud.\n\n«CARGA SUPERIOR» y «CAPACIDAD DE CARGA» son cebos de vocabulario: la señal limita lo que pesa el vehículo entero con su carga.\n\n«CARGA POR EJE» es la señal con el eje dibujado (6173).\n\nCLAVE: compárala con la 5979 y la 6173. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5495,"bg":"Какви мерки се прилагат при управление на МПС, което няма застраховка “Гражданска отговорност”?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"временно спиране от движение на МПС и временно отнемане на свидетелството за управление на МПС на водача","ok":true,"i":null,"es":"inmovilización del vehículo Y retirada provisional del permiso"},{"t":"само временно спиране от движение на МПС","ok":false,"i":null,"es":"solo inmovilización del vehículo"},{"t":"само временно отнемане на свидетелството за управление на МПС на водача","ok":false,"i":null,"es":"solo retirada del permiso"}],"sim":0.62,"es":"¿Qué medidas se aplican al conducir un vehículo sin seguro de responsabilidad civil?","explain":"⚠️ TRAMPA: AMBAS medidas simultáneas — inmovilización Y retirada del permiso. No es una u otra. Sin seguro = doble sanción inmediata."},{"id":5462,"bg":"Използването на зимни гуми през летния сезон, води до:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"увеличаване на разхода на гориво","ok":true,"i":null,"es":"mayor consumo de combustible"},{"t":"по-бързо износване на гумите","ok":true,"i":null,"es":"desgaste más rápido de los neumáticos"},{"t":"намаляване на разхода на гориво","ok":false,"i":null,"es":"menor consumo de combustible"}],"sim":0.6,"es":"Usar neumáticos de invierno en verano provoca: (2 correctas)","explain":"⚠️ TRAMPA: las gomas de invierno en verano son más blandas (el calor las ablanda más), aumentan el consumo Y se desgastan más rápido. No reducen el consumo — lo aumentan."},{"id":7879,"bg":"Към МПС от категория В принадлежат автомобили, за превоз на пътници, които, без мястото на водача, имат не повече от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"8 места за сядане","ok":true,"i":null,"es":"8 plazas"},{"t":"6 места за сядане","ok":false,"i":null,"es":"6 plazas"},{"t":"9 места за сядане","ok":false,"i":null,"es":"9 plazas"},{"t":"12 места за сядане","ok":false,"i":null,"es":"12 plazas"}],"sim":0.6,"es":"A la categoría B pertenecen los automóviles de pasajeros que, sin contar al conductor, tienen hasta:","explain":"⚠️ TRAMPA: categoría B = máximo 8 plazas sin contar al conductor. 9 sería categoría D (minibús). Memoriza: B=8 plazas de pasajeros."},{"id":11866,"bg":"На водач с правоспособност за категория В е разрешено да управлява товарен автомобил, когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"допустимата максимална маса на автомобила не надвишава 3,5 t","ok":true,"i":null,"es":"la masa máxima autorizada no supera 3.5 t"},{"t":"товара на автомобила не надвишава 3,5 t","ok":false,"i":null,"es":"la masa con carga no supera 3.5 t"},{"t":"водачът има стаж над 5 години","ok":false,"i":null,"es":"el conductor tiene más de 5 años de experiencia"},{"t":"притежава правоспособност за категория Ткт","ok":false,"i":null,"es":"posee permiso categoría Tkt"}],"sim":0.6,"es":"Al conductor con permiso categoría B le está permitido conducir un camión cuando:","explain":"⚠️ TRAMPA técnica: el límite es la MASA MÁXIMA AUTORIZADA (MMA/GVWR), no la masa con carga real. 3.5t de MMA es el límite, independientemente de cuánto cargue en un momento dado."},{"id":6040,"bg":"Сигналът за извършване на маневра се подава:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"преди започване на маневрата","ok":true,"i":null,"es":"ANTES de iniciar la maniobra"},{"t":"със започване на маневрата","ok":false,"i":null,"es":"AL INICIO de la maniobra"},{"t":"след започване на маневрата","ok":false,"i":null,"es":"DESPUÉS de iniciar la maniobra"}],"sim":0.6,"es":"La señal de maniobra se da:","explain":"⚠️ TRAMPA temporal: ANTES. El intermitente se activa antes de ejecutar, no simultáneamente. El aviso previo es esencial para que los demás puedan anticiparse."},{"id":5850,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/35032.png","v":null,"a":[{"t":"мога да премина направо","ok":true,"i":null,"es":"continuar RECTO"},{"t":"мога да завия надясно","ok":true,"i":null,"es":"girar a la DERECHA"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"girar a la IZQUIERDA"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"dar la VUELTA"}],"sim":0.6,"es":"La señal del agente regulador significa que puedo: (2 correctas)","explain":"⚠️ TRAMPA: con brazos extendidos lateralmente, los de frente/detrás pueden recto Y derecha. Girar a la izquierda y dar la vuelta = prohibidos."},{"id":5853,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/35066.png","v":null,"a":[{"t":"мога да премина направо","ok":true,"i":null,"es":"continuar RECTO"},{"t":"мога да завия надясно","ok":true,"i":null,"es":"girar a la DERECHA"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"girar a la IZQUIERDA"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"dar la VUELTA"}],"sim":0.6,"es":"La señal del agente regulador significa que puedo: (2 correctas)","explain":"PUEDO SEGUIR RECTO Y PUEDO GIRAR A LA DERECHA. Dos correctas.\n\nQUÉ VES. Un AGENTE en el cruce, con los BRAZOS BAJADOS, que te muestra su COSTADO.\n\nCÓMO SE LEE AL AGENTE CON LOS BRAZOS EXTENDIDOS O BAJADOS:\n• Si te muestra el COSTADO (izquierdo o derecho): puedes seguir RECTO o girar a la DERECHA.\n• Si te muestra el PECHO o la ESPALDA: prohibido pasar.\n\n«GIRAR A LA IZQUIERDA» y «DAR LA VUELTA» son los cebos: con el agente de costado solo se permite recto y derecha.\n\nCLAVE: costado = recto y derecha, nada más. Compárala con la 5834 (la misma posición vista desde varios coches). Ver Leyes → «Quién manda sobre quién»."},{"id":5923,"bg":"Мигащата червена светлина или две последователно мигащи една след друга червени светлини означават:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44332.png","v":null,"a":[{"t":"че преминаването е забранено","ok":true,"i":null,"es":"el paso está PROHIBIDO"},{"t":"че преминаването е разрешено","ok":false,"i":null,"es":"el paso está permitido"},{"t":"че това е сигнал само за водачите на релсови превозни средства","ok":false,"i":null,"es":"es una señal solo para tranvías"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"}],"sim":0.6,"es":"La luz roja parpadeante o dos rojas alternativas significa:","explain":"⚠️ TRAMPA: rojo parpadeante = PROHIBIDO sin excepciones. No es 'atención' ni señal solo para tranvías. Es la señal de mayor urgencia en paso a nivel."},{"id":6070,"bg":"При тази ситуация трябва да се движа:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59902.png","v":null,"a":[{"t":"в дясната пътна лента","ok":true,"i":null,"es":"en el carril DERECHO"},{"t":"в по-удобната за мен пътна лента","ok":false,"i":null,"es":"en el más cómodo"},{"t":"в лявата пътна лента","ok":false,"i":null,"es":"en el IZQUIERDO"}],"sim":0.6,"es":"En esta situación debo circular:","explain":"EN EL CARRIL DERECHO. Una sola correcta.\n\nQUÉ VES. Carretera FUERA DE POBLACIÓN con dos carriles en tu sentido. Vas por el IZQUIERDO. En el retrovisor se ve un coche ROJO detrás de ti que te hace ráfagas con las luces: quiere adelantar.\n\nFUERA DE POBLACIÓN, EL CARRIL DE LA DERECHA. Los carriles de la izquierda son para adelantar, no para viajar por ellos. Si no estás adelantando a nadie, vuelves a la derecha.\n\nQUE VENGA ALGUIEN DETRÁS NO CREA LA OBLIGACIÓN: la norma se aplica igual con la carretera vacía. El coche del retrovisor solo hace evidente el problema.\n\n«EN EL CARRIL MÁS CÓMODO» solo es posible en población y con carriles señalizados. Aquí estás fuera.\n\n«EN EL CARRIL IZQUIERDO» es la infracción que la pregunta quiere que reconozcas.\n\nCLAVE: derecha por defecto; izquierda solo mientras adelantas.\n\nMÉTODO DE CARRILES: 1) ¿estoy en población o fuera? 2) ¿cuántos carriles hay en MI sentido y están señalizados? 3) ¿estoy adelantando? Fuera de población, sin adelantar, siempre el carril derecho. Ver Leyes → «Carril: dónde debes circular»."},{"id":6072,"bg":"На двупосочен път, с по една пътна лента за движение във всяка посока, превозните средства трябва да се движат:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/123692.png","v":null,"a":[{"t":"в дясната пътна лента","ok":true,"i":null,"es":"en el carril DERECHO"},{"t":"в средната част на пътя","ok":false,"i":null,"es":"por el centro del camino"},{"t":"в лявата пътна лента","ok":false,"i":null,"es":"en el carril IZQUIERDO"}],"sim":0.6,"es":"En vía de doble sentido con un carril por sentido, los vehículos deben circular:","explain":"EN EL CARRIL DERECHO. Una sola correcta.\n\nQUÉ VES. Una carretera de DOBLE SENTIDO con un carril para cada sentido, separados por la línea central.\n\nCADA UNO POR SU DERECHA. En una vía de doble sentido con un carril por sentido, tu carril es el de la derecha; el izquierdo es el de los vehículos que vienen de frente.\n\n«POR EL CENTRO DEL CAMINO» es el cebo de quien se separa del borde por comodidad: invades parcialmente el carril contrario.\n\n«EN EL CARRIL IZQUIERDO» es circular en sentido contrario.\n\nCLAVE: doble sentido + un carril por sentido = siempre el derecho. Ver Leyes → «Carril: dónde debes circular»."},{"id":5842,"bg":"Влияние върху големината на коефициента на сцепление на автомобилните гуми с пътя оказват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"видът на пътната настилка","ok":true,"i":null,"es":"el tipo de pavimento"},{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"видът на автомобилните гуми","ok":true,"i":null,"es":"el tipo de neumático"},{"t":"диаметърът на автомобилните гуми","ok":false,"i":null,"es":"el diámetro del neumático"}],"sim":0.6,"es":"El coeficiente de rozamiento neumático-asfalto está influido por: (3 correctas)","explain":"⚠️ TRAMPA: tipo de pavimento + estado del pavimento + tipo de neumático influyen. El DIÁMETRO del neumático no afecta significativamente al coeficiente de rozamiento."},{"id":6231,"bg":"Кой от водачите е с предимство при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69569.png","v":null,"a":[{"t":"водачът на лекия автомобил","ok":true,"i":null,"es":"el turismo"},{"t":"водачът на товарния автомобил","ok":false,"i":null,"es":"el camión"}],"sim":0.6,"es":"¿Qué conductor tiene prioridad en esta situación?","explain":"EL CONDUCTOR DEL TURISMO. Una sola correcta.\n\nQUÉ VES. Una calzada de tres carriles en el mismo sentido. Un CAMIÓN blanco va por un carril de la izquierda y lleva el intermitente DERECHO: se cambia hacia el carril central. A la DERECHA, un turismo AZUL se cambia también hacia ese mismo carril central (la flecha lo indica).\n\nDOS CAMBIOS DE CARRIL HACIA EL MISMO CARRIL. Cuando dos vehículos quieren ocupar a la vez el mismo carril desde lados opuestos, tiene preferencia el que está a la DERECHA. El azul está a la derecha del camión: pasa él.\n\nEL TAMAÑO DEL CAMIÓN NO CUENTA. Ser grande no da ningún derecho.\n\n«EL CAMIÓN» es el cebo para quien piensa que el que puso antes el intermitente o el más grande tiene preferencia.\n\n(Corrección: la explicación anterior decía que el camión salía de un estacionamiento con las luces de emergencia. En la imagen lleva solo el intermitente derecho y está cambiando de carril).\n\nCLAVE: dos que convergen al mismo carril = pasa el de la derecha. Es la misma regla que la 6233.\n\nMÉTODO: 1) ¿hacia qué carril va cada uno? 2) si van al mismo, ¿quién está a la derecha? 3) ese pasa primero. Ver Leyes → «Regla de la derecha»."},{"id":6233,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69669.png","v":null,"a":[{"t":"водачът на синия автомобил","ok":true,"i":null,"es":"el coche AZUL"},{"t":"водачът на червения автомобил","ok":false,"i":null,"es":"el coche ROJO"}],"sim":0.6,"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL COCHE AZUL. Una sola correcta.\n\nQUÉ VES. Calle con TRES CARRILES en el mismo sentido (señales de carriles a ambos lados). El coche ROJO va por el carril IZQUIERDO con el intermitente derecho; el coche AZUL va por el carril DERECHO con el intermitente izquierdo. Los dos se cambian al carril CENTRAL a la vez.\n\nPASA EL DE LA DERECHA. Cuando dos vehículos quieren ocupar el mismo carril desde lados opuestos, tiene preferencia el que está a la derecha. El azul está a la derecha del rojo.\n\nQUE LOS DOS MANIOBREN NO CAMBIA NADA: la ley mira la posición relativa, no quién empezó antes ni quién puso antes el intermitente.\n\n«EL COCHE ROJO» es el cebo para quien piensa que el carril izquierdo es «el rápido» y por eso manda.\n\n(Corrección: la explicación anterior hablaba de carriles contiguos; en la imagen hay un carril libre entre los dos y ambos van hacia él).\n\nCLAVE: es la gemela de la 6231 (camión y turismo) y de la 6234 (la misma regla en teoría).\n\nMÉTODO: 1) ¿hacia qué carril va cada uno? 2) si van al mismo, ¿quién está a la derecha? 3) ese pasa primero. Ver Leyes → «Regla de la derecha»."},{"id":6236,"bg":"Кой от водачите е с предимство при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69768.png","v":null,"a":[{"t":"водачът на товарния автомобил","ok":true,"i":null,"es":"el conductor del CAMIÓN"},{"t":"водачът на лекия автомобил","ok":false,"i":null,"es":"el conductor del turismo"},{"t":"водачът на автомобила, който пръв достигне до препятствието","ok":false,"i":null,"es":"el conductor que llegue primero al obstáculo"}],"sim":0.6,"es":"¿Qué conductor tiene prioridad en esta situación?","explain":"EL CONDUCTOR DEL CAMIÓN. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6235: un OBSTÁCULO en el carril del turismo AZUL, que lleva el intermitente izquierdo para rodearlo, y un CAMIÓN rojo que viene de frente por su carril.\n\nEL CAMIÓN TIENE PREFERENCIA porque circula por su carril, que está libre. El azul tiene el obstáculo en su lado y, para rodearlo, invadiría el carril del camión.\n\n«EL TURISMO» es el cebo de quien piensa que el que señaliza o el más pequeño tiene preferencia.\n\n«EL QUE LLEGUE PRIMERO AL OBSTÁCULO» es una regla inventada: aquí no hay carrera.\n\nCLAVE: el obstáculo decide: quien lo tiene en su carril, cede. Ver Leyes → «Carril: dónde debes circular»."},{"id":6270,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70250.png","v":null,"a":[{"t":"автомобилът, който завива надясно","ok":true,"i":null,"es":"el que gira a la DERECHA"},{"t":"автомобилът, който завива наляво","ok":false,"i":null,"es":"el que gira a la IZQUIERDA"}],"sim":0.6,"es":"En esta situación tiene prioridad:","explain":"EL QUE GIRA A LA DERECHA. Una sola correcta.\n\nQUÉ VES. Un coche VERDE (en primer plano) con el intermitente DERECHO, que gira a la derecha. De frente viene un coche ROJO con el intermitente, que gira a SU izquierda. Los dos van a entrar en la misma calle (la de la derecha del verde).\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«EL QUE GIRA A LA IZQUIERDA» es el cebo de quien piensa que el que llega antes al cruce tiene preferencia.\n\nCLAVE: mismo destino desde lados opuestos = el de la derecha primero. Ver Leyes → «Giro a la izquierda»."},{"id":6363,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71077.png","v":null,"a":[{"t":"водачът на лекия автомобил","ok":true,"i":null,"es":"el conductor del TURISMO"},{"t":"водачът на товарния автомобил","ok":false,"i":null,"es":"el conductor del CAMIÓN"}],"sim":0.6,"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL TURISMO. Una sola correcta.\n\nQUÉ VES. La misma escena que la 6362: un CAMIÓN en el carril derecho, con el intermitente izquierdo, va a dar la vuelta desde ese carril; por el carril izquierdo, en el mismo sentido, va un turismo ROJO.\n\nEL QUE DA LA VUELTA CEDE. El camión, para cambiar de sentido, tiene que cruzar el carril del turismo. El turismo sigue recto por su carril: tiene preferencia.\n\n«EL CAMIÓN» es el cebo de quien piensa que el camión, por estar a la derecha o por haber señalizado, pasa primero.\n\nCLAVE: cambio de sentido = cede a todos. Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":6365,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/142934.png","v":null,"a":[{"t":"водачът на товарния автомобил","ok":true,"i":null,"es":"el conductor del CAMIÓN"},{"t":"водачът на лекия автомобил","ok":false,"i":null,"es":"el conductor del turismo"}],"sim":0.6,"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL CAMIÓN. Una sola correcta.\n\nQUÉ VES. Una carretera con mediana. En una abertura de la mediana hay una señal azul que PERMITE el CAMBIO DE SENTIDO. El coche AZUL lleva el intermitente izquierdo y va a dar la vuelta por ahí. Por el otro lado viene un CAMIÓN rojo.\n\nLA SEÑAL PERMITE LA MANIOBRA, NO DA PRIORIDAD. Puedes dar la vuelta en ese punto, pero cediendo a los que circulan por la calzada a la que entras, como el camión.\n\n«EL TURISMO» es el cebo de quien confunde «está permitido» con «tengo preferencia».\n\nCLAVE: señal de cambio de sentido permitido = puedo hacerlo, cediendo el paso. Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":6383,"bg":"На път с голям надлъжен наклон, когато разминаването е невъзможно и редът за преминаване не е уреден с пътни знаци, предимство има ППС, което:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се изкачва по наклона","ok":true,"i":null,"es":"SUBE la pendiente"},{"t":"се спуска по наклона","ok":false,"i":null,"es":"BAJA la pendiente"},{"t":"се движи по-бързо","ok":false,"i":null,"es":"va más rápido"},{"t":"се намира по-близо до стеснения участък","ok":false,"i":null,"es":"está más cerca del tramo estrecho"}],"sim":0.6,"es":"En vía con gran pendiente, cuando el cruce es imposible y no hay norma establecida, tiene prioridad el que:","explain":"⚠️ TRAMPA: prioridad para el que SUBE. Reanudar la marcha cuesta arriba es más difícil — por eso tiene prioridad. El que baja puede retroceder más fácilmente."},{"id":6428,"bg":"При изпреварване задължението за осигуряване на достатъчно странично разстояние е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на водача на изпреварващото ППС","ok":true,"i":null,"es":"del conductor del vehículo ADELANTANTE"},{"t":"на водача на изпреварваното ППС","ok":false,"i":null,"es":"del conductor del vehículo ADELANTADO"},{"t":"на двамата водачи","ok":false,"i":null,"es":"de ambos conductores"}],"sim":0.6,"es":"La obligación de garantizar distancia lateral suficiente al adelantar es:","explain":"⚠️ TRAMPA: responsabilidad exclusiva del que ADELANTA. El vehículo adelantado no tiene obligación de proporcionar espacio — la responsabilidad es completamente del adelantante."},{"id":5940,"bg":"При несъответствие между сигналите на регулировчика, сигналите на светофара и пътните знаци относно предимството трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51102.png","v":null,"a":[{"t":"със сигналите на регулировчика","ok":true,"i":null,"es":"las señales del AGENTE"},{"t":"с предписанията на пътните знаци","ok":false,"i":null,"es":"las señales de tráfico"},{"t":"със сигналите на светофара","ok":false,"i":null,"es":"las señales del SEMÁFORO"}],"sim":0.6,"es":"Cuando hay conflicto entre agente, semáforo y señales de prioridad, debes atenerte a:","explain":"⚠️ TRAMPA: siempre el AGENTE. Orden: agente > semáforo > señales. Esta jerarquía es absoluta e inamovible."},{"id":5942,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51152.png","v":null,"a":[{"t":"със сигналите на регулировчика","ok":true,"i":null,"es":"las señales del AGENTE"},{"t":"със сигналите на светофара","ok":false,"i":null,"es":"las señales del semáforo"},{"t":"с предписанията на пътните знаци относно предимството","ok":false,"i":null,"es":"las señales de prioridad"}],"sim":0.6,"es":"En esta situación al pasar por la intersección debes atenerte a:","explain":"LAS SEÑALES DEL AGENTE REGULADOR. Una sola correcta.\n\nQUÉ VES. Los tres escalones a la vez: un AGENTE en el centro del cruce, un SEMÁFORO en verde y la señal de VÍA CON PRIORIDAD (rombo) encima del semáforo.\n\nMANDA EL PRIMERO DE LA ESCALERA, y el primero es el agente. Está por encima del semáforo y por encima de las señales de prioridad.\n\n«EL SEMÁFORO» sería correcta solo si no hubiera agente. «LAS SEÑALES DE PRIORIDAD», solo si no hubiera ni agente ni semáforo.\n\nCLAVE: no hay que evaluar los tres; hay que encontrar el más alto. En cuanto ves al agente, él decide el orden de paso (aunque sigues obligado a respetar las señales de prohibición y de dirección obligatoria).\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Quién manda sobre quién»."},{"id":5945,"bg":"При тази ситуация редът за преминаване на автомобилите през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51266.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del AGENTE"},{"t":"от сигналите на светофара","ok":false,"i":null,"es":"las del semáforo"},{"t":"с „правилото на десния”","ok":false,"i":null,"es":"la regla de la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de los vehículos"}],"sim":0.6,"es":"En esta situación el orden de paso lo determinan:","explain":"⚠️ TRAMPA: AGENTE. Mismo principio — el agente siempre tiene prioridad sobre cualquier otro sistema de control de tráfico."},{"id":5545,"bg":"Този пътен знак указва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38358.png","v":null,"a":[{"t":"начало на автобусна спирка","ok":true,"i":null,"es":"INICIO de parada de autobús"},{"t":"край на автобусна спирка","ok":false,"i":null,"es":"FIN de parada de autobús"},{"t":"пресичане на път, по който се движат автобуси","ok":false,"i":null,"es":"cruce de ruta de autobús"}],"sim":0.6,"es":"Esta señal indica:","explain":"INICIO DE PARADA DE AUTOBÚS. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con un recuadro blanco y un AUTOBÚS.\n\nSE COLOCA AL PRINCIPIO DE LA PARADA; desde ahí empieza la zona donde no puedes detenerte ni aparcar.\n\n«FIN DE PARADA» no se indica con esta señal. «CRUCE DE RUTA DE AUTOBÚS» no existe como señal.\n\nCLAVE: compárala con la 5547 y la 5562. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5742,"bg":"При теглене на повредено МПС с гъвкава връзка то трябва да бъде:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с изправна кормилна уредба","ok":true,"i":null,"es":"la dirección en buen estado"},{"t":"с изправна спирачна уредба","ok":true,"i":null,"es":"los frenos en buen estado"},{"t":"с изправен двигател","ok":false,"i":null,"es":"el motor en buen estado"},{"t":"с изправна осветителна уредба","ok":false,"i":null,"es":"el sistema de iluminación en buen estado"}],"sim":0.6,"es":"Al remolcar con cable flexible el vehículo remolcado debe tener: (2 correctas)","explain":"⚠️ TRAMPA: con cable flexible son obligatorios DIRECCIÓN Y FRENOS del remolcado. El motor y la iluminación no son requisitos para el remolque."},{"id":12067,"bg":"Какво трябва да направите при тази ситуация? Оставам в заеманата лента, като:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се движа в средата на лентата","ok":false,"i":null,"es":"circulo por el centro del carril"},{"t":"се движа възможно най-вдясно","ok":true,"i":null,"es":"circulo todo lo posible a la DERECHA"},{"t":"се движа възможно най-вляво","ok":false,"i":null,"es":"circulo todo lo posible a la IZQUIERDA"}],"sim":0.6,"es":"¿Qué debes hacer en esta situación? Mantengo mi carril y...","explain":"⚠️ TRAMPA: todo lo posible a la DERECHA para dar espacio. Nunca al centro ni a la izquierda cuando hay un vehículo de emergencia o un obstáculo que requiere espacio."},{"id":11893,"bg":"Престоят на ППС е забранен на кръстовище и на разстояние от него, по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 метра преди кръстовище","ok":true,"i":null,"es":"5 metros ANTES de la intersección"},{"t":"5 метра след кръстовище","ok":true,"i":null,"es":"5 metros DESPUÉS de la intersección"},{"t":"10 метра преди кръстовище","ok":false,"i":null,"es":"10 metros antes"},{"t":"10 метра след кръстовище","ok":false,"i":null,"es":"10 metros después"}],"sim":0.6,"es":"La parada breve está prohibida en intersección y a una distancia inferior a: (2 correctas)","explain":"⚠️ TRAMPA: 5m ANTES Y 5m DESPUÉS de la intersección. A diferencia del paso de peatones (solo antes), en intersecciones la restricción aplica en ambos lados."},{"id":11894,"bg":"Паркирането на ППС е забранено на кръстовище и на разстояние от него, по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 метра преди кръстовище","ok":true,"i":null,"es":"5 metros ANTES de la intersección"},{"t":"5 метра след кръстовище","ok":true,"i":null,"es":"5 metros DESPUÉS de la intersección"},{"t":"10 метра преди кръстовище","ok":false,"i":null,"es":"10 metros antes"},{"t":"10 метра след кръстовище","ok":false,"i":null,"es":"10 metros después"}],"sim":0.6,"es":"El aparcamiento está prohibido en intersección y a una distancia inferior a: (2 correctas)","explain":"⚠️ TRAMPA: igual que el prestoy — 5m antes Y después en intersecciones. Diferente al paso de peatones donde la restricción es solo antes."},{"id":5665,"bg":"През нощта на осветен участък от пътя движението се извършва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"с включени къси светлини","ok":true,"i":null,"es":"con luces CORTAS encendidas"},{"t":"с включени дълги светлини","ok":false,"i":null,"es":"con luces LARGAS encendidas"},{"t":"с включени само габаритни светлини","ok":false,"i":null,"es":"con solo las luces de posición"},{"t":"без включени светлини","ok":false,"i":null,"es":"sin luces encendidas"}],"sim":0.6,"es":"De noche en un tramo iluminado artificialmente, se circula:","explain":"⚠️ TRAMPA: en tramo iluminado = CORTAS encendidas (no largas). Las largas deslumbrarían en un entorno ya iluminado. Siempre cortas en zona iluminada."},{"id":6118,"bg":"Какво влияние оказва алкохолът върху поведението на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"влошава координацията на движенията","ok":true,"i":null,"es":"empeora la coordinación"},{"t":"увеличава времето за реакция","ok":true,"i":null,"es":"aumenta el tiempo de reacción"},{"t":"подобрява координацията","ok":false,"i":null,"es":"mejora la coordinación"},{"t":"намалява времето за реакция","ok":false,"i":null,"es":"reduce el tiempo de reacción"}],"sim":0.6,"es":"¿Qué efecto tiene el alcohol en el conductor? (2 correctas)","explain":"⚠️ TRAMPA: alcohol empeora la coordinación Y AUMENTA el tiempo de reacción. El alcohol NUNCA mejora nada en la conducción — ambas respuestas positivas son incorrectas."},{"id":6137,"bg":"Влияе ли възрастта на водачите на способността им да виждат през нощта?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да, при водачите на възраст под 30 години","ok":false,"i":null,"es":"sí, en conductores MAYORES de 50 años"},{"t":"да, при водачите на възраст над 50 години","ok":true,"i":null,"es":"sí, en conductores menores de 30 años"},{"t":"възрастта е без значение","ok":false,"i":null,"es":"la edad no tiene importancia"}],"sim":0.6,"es":"¿Afecta la edad a la capacidad de ver de noche?","explain":"⚠️ TRAMPA: la visión nocturna empeora con la edad, especialmente a partir de los 50. Los conductores jóvenes tienen mejor visión nocturna — no al revés."},{"id":6141,"bg":"Продължителното слушане на силна музика при управление на автомобил:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"стимулира способността за концентриране","ok":false,"i":null,"es":"REDUCE la capacidad de concentración"},{"t":"намалява способността за концентриране","ok":true,"i":null,"es":"estimula la concentración"},{"t":"тренира и подобрява способността за чуване","ok":false,"i":null,"es":"entrena y mejora la audición"},{"t":"успокоява водача","ok":false,"i":null,"es":"tranquiliza al conductor"}],"sim":0.6,"es":"Escuchar música alta durante la conducción:","explain":"⚠️ TRAMPA: música alta REDUCE la concentración. No la mejora ni tranquiliza. Los estímulos auditivos intensos son una distracción real que aumenta el riesgo."},{"id":6146,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"трудност при съсредоточаване","ok":true,"i":null,"es":"dificultad para concentrarse"},{"t":"намаляване на обема на възприеманите обекти от пътната обстановка","ok":true,"i":null,"es":"reducción de los objetos percibidos del entorno"},{"t":"неправилни реакции","ok":true,"i":null,"es":"reacciones incorrectas"},{"t":"висока точност на възприеманите обекти от пътната обстановка","ok":false,"i":null,"es":"alta precisión en la percepción de objetos"}],"sim":0.6,"es":"Las señales de alerta de fatiga en el conductor son: (3 correctas)","explain":"⚠️ TRAMPA: fatiga = dificultad de concentración + menos objetos percibidos + reacciones incorrectas. La alta precisión es lo CONTRARIO — la fatiga REDUCE la precisión, no la aumenta."},{"id":5341,"bg":"Задължение за запазване на следите при ПТП имат:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"всички участници в ПТП","ok":true,"i":null,"es":"todos los implicados en el accidente"},{"t":"свидетелите на ПТП","ok":false,"i":null,"es":"los testigos del accidente"},{"t":"само виновните участници в ПТП","ok":false,"i":null,"es":"solo los culpables del accidente"},{"t":"всички участници в движението","ok":false,"i":null,"es":"todos los participantes en el tráfico"}],"sim":0.6,"es":"La obligación de preservar las huellas en un accidente corresponde a:","explain":"⚠️ TRAMPA: la obligación es de los IMPLICADOS en el accidente (los que sufrieron el accidente), no de todos los testigos ni de todos los conductores que pasen."},{"id":6179,"bg":"След този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53277.png","v":null,"a":[{"t":"забранено влизането на ППС с дължината по-голяма от означената","ok":true,"i":null,"es":"prohibida la entrada de vehículos con longitud superior a la indicada"},{"t":"разрешено влизането за ППС, на които товарът е с дължина по-голяма от означената","ok":false,"i":null,"es":"permitida la entrada si solo la carga supera la longitud"},{"t":"забранено влизането за ППС, на които дължината заедно с товара е по-голяма от означената","ok":true,"i":null,"es":"prohibida la entrada de vehículos cuya longitud con carga supere la indicada"}],"sim":0.59,"es":"Después de esta señal está: (2 correctas)","explain":"PROHIBIDA LA ENTRADA DE VEHÍCULOS CON LONGITUD SUPERIOR A LA INDICADA Y DE LOS QUE, CON LA CARGA, SUPERAN ESA LONGITUD. Dos correctas.\n\nLA SEÑAL. Círculo con borde ROJO con un CAMIÓN y, debajo, «← 10 m →».\n\nLAS TRES MEDIDAS, POR LA POSICIÓN DE LAS PUNTAS NEGRAS:\n• puntas ARRIBA y ABAJO del número = ALTURA;\n• puntas a la IZQUIERDA y DERECHA del número = ANCHURA;\n• un CAMIÓN con una flecha «← 10 m →» debajo = LONGITUD.\nLas tres cuentan el vehículo CON SU CARGA.\n\n«PERMITIDA SI SOLO LA CARGA SUPERA LA LONGITUD» es el cebo: la carga cuenta; lo que importa es lo que mide el conjunto.\n\nCLAVE: compárala con la 6180 y la 6181. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6588,"bg":"Този знак изисква от водачите да спрат:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55422.png","v":null,"a":[{"t":"винаги, независимо дали по пресичания път се движи превозно средство","ok":true,"i":null,"es":"siempre, independientemente de si hay vehículos en la vía cruzada"},{"t":"само ако по пресичания път се движи превозно средство","ok":false,"i":null,"es":"solo si hay vehículos en la vía cruzada"},{"t":"ако те преценят, че е необходимо","ok":false,"i":null,"es":"si el conductor lo considera necesario"}],"sim":0.58,"es":"Esta señal obliga a los conductores a parar:","explain":"SIEMPRE, INDEPENDIENTEMENTE DE SI HAY VEHÍCULOS EN LA VÍA QUE CRUZAS. Una sola correcta.\n\nQUÉ VES. Un cruce. En tu poste, la señal octogonal roja de STOP. En los otros accesos se ven rombos de vía con prioridad.\n\nSTOP = DETENCIÓN OBLIGATORIA. Tienes que pararte del todo antes de entrar en el cruce, venga alguien o no. Después cedes a los que circulan por la vía principal.\n\n«SOLO SI HAY VEHÍCULOS EN LA VÍA QUE CRUZAS» es el cebo: eso sería el ceda el paso.\n\n«SI EL CONDUCTOR LO CONSIDERA NECESARIO» convierte la obligación en una opción.\n\nCLAVE: ceda el paso = cedo si viene alguien; STOP = paro siempre y luego cedo. Ver Leyes → «Vía con prioridad»."},{"id":6296,"bg":"При тази ситуация забраната за изпреварване, е валидна:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56246.png","v":null,"a":[{"t":"до края на стеснения участък от пътя","ok":true,"i":null,"es":"hasta el FIN del tramo estrecho"},{"t":"до знак, който отменя забраната","ok":false,"i":null,"es":"hasta la señal que cancela la prohibición"},{"t":"до следващото кръстовище","ok":false,"i":null,"es":"hasta la próxima intersección"},{"t":"до края на пътя","ok":false,"i":null,"es":"hasta el final de la vía"}],"sim":0.57,"es":"En esta situación la prohibición de adelantamiento es válida:","explain":"HASTA EL FINAL DEL TRAMO ESTRECHO. Una sola correcta.\n\nQUÉ VES. Carretera fuera de población. A la derecha, un triángulo de ESTRECHAMIENTO y, debajo, la señal de PROHIBIDO ADELANTAR.\n\nLA PROHIBICIÓN VA COLGADA DEL TRIÁNGULO: no se puede adelantar porque la calzada se estrecha, así que la prohibición dura lo que dura el estrechamiento.\n\n«HASTA LA SEÑAL QUE LA CANCELA» y «HASTA LA PRÓXIMA INTERSECCIÓN» son la regla general para una prohibición que va sola. «HASTA EL FINAL DE LA VÍA» la alarga sin motivo.\n\nCLAVE: compárala con la 6297, la 6300 y la 6302. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":11885,"bg":"В кой от изброените отговори е посочено вярно значението на пътния знак с допълнителна табела?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828556.png","v":null,"a":[{"t":"стесненият участък от платното за движение започва на 200 метра след знака","ok":true,"i":null,"es":"el tramo estrecho empieza a 200 metros después de la señal"},{"t":"стесненият участък от платното за движение е с дължина 200 метра","ok":false,"i":null,"es":"el tramo estrecho tiene una longitud de 200 metros"},{"t":"стесненият участък от пътя завършва на 200 метра след знака","ok":false,"i":null,"es":"el tramo estrecho termina a 200 metros después"}],"sim":0.57,"es":"¿Cuál es el significado correcto de esta señal con tablilla?","explain":"EL TRAMO ESTRECHO EMPIEZA A 200 m DESPUÉS DE LA SEÑAL. Una sola correcta.\n\nQUÉ VES. Triángulo de ESTRECHAMIENTO por ambos lados con una placa «200 m», sin flechas.\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso.\n\n«LONGITUD DE 200 m» llevaría las flechas (compárala con la 11886). «TERMINA A 200 m» no lo indica ninguna placa.\n\nCLAVE: compárala con la 6218. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6085,"bg":"При тази ситуация, на път извън населено място, на водачите е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/140619.png","v":null,"a":[{"t":"да се движат в най-дясната свободна лента","ok":true,"i":null,"es":"circular en el carril disponible más a la derecha"},{"t":"да се движат в средната пътна лента, когато дясната е заета","ok":true,"i":null,"es":"circular en el carril central cuando el derecho está ocupado"},{"t":"да се движат в най удобната за тях пътна лента","ok":false,"i":null,"es":"circular en el carril más cómodo"},{"t":"да се движат в средната пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"circular en el central siempre que esté libre"}],"sim":0.57,"es":"En esta situación fuera de población, está PERMITIDO: (2 correctas)","explain":"CIRCULAR POR EL CARRIL LIBRE MÁS A LA DERECHA Y POR EL CENTRAL CUANDO EL DERECHO ESTÁ OCUPADO. Dos correctas.\n\nQUÉ VES. Carretera FUERA DE POBLACIÓN con TRES carriles. La señal azul de la derecha muestra dos flechas hacia arriba y una hacia abajo: DOS carriles en tu sentido y UNO para el sentido contrario (el de la izquierda).\n\nFUERA DE POBLACIÓN, EL CARRIL LIBRE MÁS A LA DERECHA. Si el derecho está ocupado, puedes usar el central (el segundo de tu sentido).\n\n«EL CARRIL MÁS CÓMODO» solo se permite en población con carriles señalizados.\n\n«EL CENTRAL SIEMPRE QUE ESTÉ LIBRE» es el cebo: si el derecho está libre, tienes que ir por él.\n\nCLAVE: fuera de población, la derecha libre manda; el siguiente carril solo cuando el derecho está ocupado o para adelantar (compárala con la 6087). Ver Leyes → «Carril: dónde debes circular»."},{"id":5810,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334712.png","v":null,"a":[{"t":"указва препоръчителна скорост за движение","ok":true,"i":null,"es":"indica velocidad RECOMENDADA"},{"t":"забранява движение със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"указва задължителна минимална скорост за движение","ok":false,"i":null,"es":"indica velocidad MÍNIMA obligatoria"}],"sim":0.57,"es":"Esta señal:","explain":"INDICA LA VELOCIDAD RECOMENDADA. Una sola correcta.\n\nLA SEÑAL. CUADRADO AZUL con «60» en blanco.\n\nLAS SEÑALES DE VELOCIDAD QUE SE CONFUNDEN:\n• Círculo blanco con BORDE ROJO y cifra negra = velocidad MÁXIMA.\n• Círculo AZUL con cifra blanca = velocidad MÍNIMA obligatoria.\n• CUADRADO AZUL con cifra blanca = velocidad RECOMENDADA.\n• Círculo blanco con la cifra TACHADA = FIN de la limitación.\n\n«PROHÍBE SUPERAR LA VELOCIDAD» sería el círculo de borde rojo.\n\n«VELOCIDAD MÍNIMA OBLIGATORIA» sería el círculo azul: mismo color, distinta forma. Esa es la trampa.\n\nCLAVE: azul cuadrado = recomendación; azul redondo = obligación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5821,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334713.png","v":null,"a":[{"t":"указва задължителна минимална скорост за движение","ok":true,"i":null,"es":"indica velocidad MÍNIMA obligatoria"},{"t":"забранява движение със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior"},{"t":"указва препоръчителна скорост за движение","ok":false,"i":null,"es":"indica velocidad RECOMENDADA"}],"sim":0.57,"es":"Esta señal:","explain":"INDICA LA VELOCIDAD MÍNIMA OBLIGATORIA. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con la cifra en BLANCO (30). El azul en una señal circular es OBLIGACIÓN.\n\nQUÉ TE OBLIGA A HACER. A no circular por debajo de esa velocidad (salvo que las condiciones de seguridad no lo permitan; compárala con la 5827). Si tu vehículo no puede alcanzarla, no debe entrar en esa vía o carril.\n\n«PROHÍBE CIRCULAR A VELOCIDAD SUPERIOR A LA INDICADA» es el cebo más elegido: el reflejo es leer cualquier número como un máximo. El máximo es un círculo con borde ROJO y la cifra en negro.\n\n«VELOCIDAD RECOMENDADA» es otra señal: cuadrada/rectangular azul, no circular.\n\nCLAVE: círculo azul con número = mínimo; círculo de borde rojo con número = máximo.\n\nMÉTODO: 1) ¿qué forma? 2) ¿qué color? 3) circular azul = obligación. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":8283,"bg":"Този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/125668477.png","v":null,"a":[{"t":"указва място, определено за паркиране на ППС, обслужващи хора с трайни увреждания","ok":true,"i":null,"es":"indica lugar reservado para aparcar vehículos que sirven a personas con discapacidad"},{"t":"предупреждава за възможна поява на ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"advierte de posible presencia de esos vehículos"},{"t":"забранява движението на ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"prohíbe la circulación de esos vehículos"},{"t":"указва пътна лента за ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"indica carril para esos vehículos"}],"sim":0.57,"es":"Esta señal:","explain":"INDICA UN LUGAR RESERVADO PARA APARCAR VEHÍCULOS QUE SIRVEN A PERSONAS CON DISCAPACIDAD. Una sola correcta.\n\nLA SEÑAL. Cuadrado AZUL con una persona en SILLA DE RUEDAS en blanco.\n\nCUADRADO AZUL = INFORMACIÓN: esa plaza está reservada para los vehículos que transportan a personas con discapacidad (con su tarjeta). Los demás no pueden aparcar ahí.\n\n«ADVIERTE DE SU PRESENCIA» sería un triángulo. «PROHÍBE SU CIRCULACIÓN» sería un círculo rojo. «CARRIL PARA ELLOS» no es el significado.\n\nCLAVE: silla de ruedas en azul = plaza reservada. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5538,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,2 м","ok":true,"i":null,"es":"su ALTURA, incluyendo carga, es 4.2 m"},{"t":"широчината му, включително товара, е 2,2 м","ok":false,"i":null,"es":"su ANCHURA, incluyendo carga, es 2.2 m"},{"t":"дължината му, включително товара, е 12 м","ok":false,"i":null,"es":"su LONGITUD, incluyendo carga, es 12 m"}],"sim":0.56,"es":"Un vehículo es 'fuera de gálibo' cuando:","explain":"⚠️ TRAMPA: altura 4.2m SÍ es fuera de gálibo (límite es 4.0m). Anchura 2.2m NO es fuera de gálibo (límite es 2.55m). Longitud 12m NO es fuera de gálibo (límite es mucho mayor)."},{"id":6692,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,5 м","ok":true,"i":null,"es":"su ALTURA, incluyendo carga, es 4.5 m"},{"t":"широчината му, включително товара, е 2,8 м","ok":true,"i":null,"es":"su ANCHURA, incluyendo carga, es 2.8 m"},{"t":"дължината му, включително товара, е 9 м","ok":false,"i":null,"es":"su LONGITUD, incluyendo carga, es 9 m"}],"sim":0.56,"es":"Un vehículo es 'fuera de gálibo' cuando: (2 correctas)","explain":"⚠️ TRAMPA: 4.5m de altura (>4m) y 2.8m de anchura (>2.55m) son fuera de gálibo. 9m de longitud NO es fuera de gálibo — el límite de longitud es mucho mayor (12-18m según tipo)."},{"id":5947,"bg":"Този пътен знак предупреждава водачите, че:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42567.png","v":null,"a":[{"t":"е възможна поява на диви животни на пътя","ok":true,"i":null,"es":"puede haber ANIMALES SALVAJES en la vía"},{"t":"преминават покрай зоопарк","ok":false,"i":null,"es":"pasan cerca de un zoo"},{"t":"пътят навлиза в ловен участък","ok":false,"i":null,"es":"la vía entra en zona de caza"},{"t":"е възможна появата на домашни животни на пътя","ok":false,"i":null,"es":"puede haber animales domésticos en la vía"}],"sim":0.56,"es":"Esta señal advierte a los conductores que:","explain":"PUEDE HABER ANIMALES SALVAJES EN LA VÍA. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con un CIERVO saltando.\n\nEL CIERVO = ANIMALES SALVAJES que cruzan, sobre todo al amanecer y al anochecer.\n\n«ANIMALES DOMÉSTICOS» se dibujan con una VACA (compárala con la 5946).\n\n«ZOO» y «ZONA DE CAZA» son cebos sin relación con esta señal.\n\nCLAVE: ciervo = salvajes; vaca = domésticos. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6455,"bg":"При тази ситуация в средната пътна лента е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65112.png","v":null,"a":[{"t":"разрешено движението на автобуси с ремаркета","ok":false,"i":null,"es":"permitida la circulación de autobuses con remolque"},{"t":"разрешено движението на леки автомобили с ремаркета","ok":false,"i":null,"es":"permitida la circulación de turismos con remolque"},{"t":"забранено движението на товарни автомобили с ремаркета","ok":true,"i":null,"es":"PROHIBIDA la circulación de camiones con remolque"},{"t":"забранено движението на товарни автомобили с полуремаркета","ok":true,"i":null,"es":"PROHIBIDA la circulación de camiones con semirremolque"}],"sim":0.56,"es":"En esta situación en el carril central está: (2 correctas)","explain":"⚠️ TRAMPA: el carril central prohíbe camiones con remolque Y semirremolque. Los autobuses y turismos con remolque SÍ pueden — no son camiones."},{"id":6007,"bg":"По кой от изброените начини може да се обозначи товар, който излиза отпред на най-издадената част на превозното средство с повече от 1 м?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с червен флаг при движение през деня","ok":true,"i":null,"es":"con bandera ROJA"},{"t":"с бял светлоотразител при движение през нощта","ok":true,"i":null,"es":"con reflectante BLANCO de noche"},{"t":"с бяла светлина при движение през нощта","ok":true,"i":null,"es":"con luz BLANCA de noche"},{"t":"с червена светлина при движение през деня","ok":false,"i":null,"es":"con luz ROJA de día"}],"sim":0.56,"es":"¿De qué formas puede señalizarse de día la carga que sobresale más de 1m por delante? (3 correctas)","explain":"⚠️ TRAMPA día/noche: de DÍA = bandera roja. De NOCHE = reflectante blanco O luz blanca. La luz roja de día no está permitida para señalizar carga por delante."},{"id":12024,"bg":"Какъв е правилният начин на действие?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"изпреварвам синия автомобил и преминавам в дясната лента","ok":true,"i":null,"es":"adelanto al azul y paso al carril derecho"},{"t":"намалявам скоростта, за да подканя превозното средство, което се движи след мен, да спазва необходимата дистанция","ok":false,"i":null,"es":"reduzco velocidad para que el de atrás me adelante"},{"t":"изпреварвам червения автомобил и се придвижвам в дясната лента","ok":false,"i":null,"es":"adelanto al rojo y paso al carril derecho"}],"sim":0.55,"es":"¿Cuál es la actuación correcta?","explain":"⚠️ TRAMPA: adelantas al AZUL (no al rojo) y te reincorporas al carril derecho. El coche a adelantar es el más lento que bloquea — identifica cuál es en la imagen."},{"id":11865,"bg":"Разрешено ли е водач с правоспособност за категория В да управлява товарен автомобил?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"да, когато допустимата му максимална маса не надвишава 3,5 t","ok":true,"i":null,"es":"sí, cuando la masa máxima autorizada no supera 3.5 t"},{"t":"да, когато масата му с товар не надвишава 3,5 t","ok":false,"i":null,"es":"sí, cuando la masa CON CARGA no supera 3.5 t"},{"t":"да, когато масата на товара не надвишава 3,5 t","ok":false,"i":null,"es":"sí, cuando la carga no supera 3.5 t"},{"t":"не","ok":false,"i":null,"es":"no"}],"sim":0.54,"es":"¿Está permitido al titular del permiso B conducir un camión?","explain":"⚠️ TRAMPA técnica: el límite es la MASA MÁXIMA AUTORIZADA (MMA), no la masa real con carga. La MMA es un valor fijo del vehículo, independientemente de cuánto cargue en cada viaje."},{"id":5982,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334708.png","v":null,"a":[{"t":"&quot;Забранено е влизането на МПС с ремаркета, освен с полуремаркета или единични едноосни ремаркета&quot;","ok":true,"i":null,"es":"'Prohibida la entrada de vehículos CON REMOLQUES, excepto semirremolques o remolques simples de un eje'"},{"t":"&quot;Забранено е влизането на МПС с ремаркета&quot;","ok":false,"i":null,"es":"'Prohibida la entrada de vehículos con remolques'"},{"t":"&quot;Забранено е влизането на товарни автомобили&quot;","ok":false,"i":null,"es":"'Prohibida la entrada de camiones'"}],"sim":0.54,"es":"El significado de esta señal es:","explain":"«PROHIBIDA LA ENTRADA DE VEHÍCULOS CON REMOLQUES, EXCEPTO SEMIRREMOLQUES O REMOLQUES SIMPLES DE UN EJE». Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con un vehículo que remolca un REMOLQUE DE DOS EJES.\n\nLAS DOS SEÑALES DE REMOLQUE, QUE SE CONFUNDEN:\n• REMOLQUE DE UN EJE dibujado solo (sin vehículo tractor) = prohibido a TODOS los vehículos con remolque (de uno o más ejes, y semirremolques);\n• vehículo con REMOLQUE DE DOS EJES = prohibido a los que llevan remolque, EXCEPTO semirremolques y remolques simples de un eje.\n\n«PROHIBIDA LA ENTRADA DE VEHÍCULOS CON REMOLQUES» (sin excepción) es la otra señal (5983).\n\n«CAMIONES» es otra señal distinta.\n\nCLAVE: compárala con la 5980 y la 5981. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5983,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51816.png","v":null,"a":[{"t":"&quot;Забранено е влизането на МПС с ремаркета&quot;","ok":true,"i":null,"es":"'Prohibida la entrada de vehículos CON REMOLQUES'"},{"t":"&quot;Забранено е влизането на МПС с ремаркета, освен с полуремаркета или единични едноосни ремаркета&quot;","ok":false,"i":null,"es":"'Prohibida la entrada excepto semirremolques y remolques simples'"}],"sim":0.54,"es":"El significado de esta señal es:","explain":"«PROHIBIDA LA ENTRADA DE VEHÍCULOS CON REMOLQUES». Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO con un REMOLQUE DE UN EJE dibujado solo.\n\nLAS DOS SEÑALES DE REMOLQUE, QUE SE CONFUNDEN:\n• REMOLQUE DE UN EJE dibujado solo (sin vehículo tractor) = prohibido a TODOS los vehículos con remolque (de uno o más ejes, y semirremolques);\n• vehículo con REMOLQUE DE DOS EJES = prohibido a los que llevan remolque, EXCEPTO semirremolques y remolques simples de un eje.\n\n«EXCEPTO SEMIRREMOLQUES Y REMOLQUES SIMPLES» es el significado de la señal del remolque de dos ejes (5982).\n\nCLAVE: remolque solo = ningún remolque. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6350,"bg":"На кръстовище на равнозначни пътища водачът на нерелсово ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да пропусне релсовите ППС, когато те завиват надясно","ok":true,"i":null,"es":"debe ceder al tranvía cuando gira a la derecha"},{"t":"не е длъжен да пропусне релсовите ППС, когато те завиват наляво","ok":false,"i":null,"es":"no está obligado a ceder al tranvía cuando gira a la izquierda"},{"t":"трябва да пропусне релсовите ППС, когато те продължават направо","ok":true,"i":null,"es":"debe ceder al tranvía cuando continúa recto"}],"sim":0.54,"es":"En intersección de vías equivalentes, el conductor no ferroviario: (2 correctas)","explain":"⚠️ TRAMPA: debes ceder al tranvía cuando gira a la derecha Y cuando va recto. Cuando el tranvía gira a la izquierda, la situación es diferente — NO estás obligado a cederle."},{"id":11628,"bg":"Моторни превозни средства със специален режим на движение са автомобилите и мотоциклетите, които при движението си подават едновременно:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"светлинен сигнал с проблясваща синя и/или червена светлина и специален звуков сигнал","ok":true,"i":null,"es":"señal luminosa azul y/o roja parpadeante Y señal acústica especial"},{"t":"авариен сигнал и специален звуков сигнал","ok":false,"i":null,"es":"señal de emergencia Y señal acústica"},{"t":"светлинен сигнал с жълта пробляскваща светлина и специален звуков сигнал","ok":false,"i":null,"es":"señal luminosa amarilla Y señal acústica"}],"sim":0.54,"es":"Los vehículos con régimen especial de circulación son los que usan:","explain":"⚠️ TRAMPA: azul/roja parpadeante + sonido especial = régimen especial (policía, ambulancia). Señal de emergencia (luces de avería) + sonido no es régimen especial. Amarillo = vehículos de servicio."},{"id":11886,"bg":"В кой отговор е посочено вярно значението на пътния знак с допълнителна табела?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828558.png","v":null,"a":[{"t":"стесненият участък от платното за движение е с дължина 200 метра","ok":true,"i":null,"es":"el tramo estrecho tiene una LONGITUD de 200 metros"},{"t":"стесненият участък от платното за движение започва на 200 метра след знака","ok":false,"i":null,"es":"el tramo estrecho empieza a 200 metros"},{"t":"стесненият участък от пътя завършва на 200 метра след знака","ok":false,"i":null,"es":"el tramo estrecho termina a 200 metros"}],"sim":0.53,"es":"¿Cuál es el significado correcto de esta señal con tablilla?","explain":"EL TRAMO ESTRECHO TIENE UNA LONGITUD DE 200 m. Una sola correcta.\n\nQUÉ VES. Triángulo de ESTRECHAMIENTO por ambos lados con una placa «↑ 200 m ↑».\n\nLAS DOS PLACAS DE METROS, QUE SE CONFUNDEN:\n• solo la cifra («200 m») = DISTANCIA desde la señal hasta donde empieza el peligro;\n• la cifra entre FLECHAS hacia arriba («↑ 200 m ↑») = LONGITUD del tramo peligroso.\n\n«EMPIEZA A 200 m» sería la cifra sola (compárala con la 11885).\n\nCLAVE: compárala con la 6224. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6362,"bg":"Когато при недостатъчна широчина на платното за движение завиването в обратна посока започва от дясната пътна лента, водачът на завиващото ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71077.png","v":null,"a":[{"t":"трябва да пропусне насрещно движещите се ППС","ok":true,"i":null,"es":"ceder al tráfico de frente"},{"t":"трябва да пропусне попътно движещите се от лявата му страна ППС","ok":true,"i":null,"es":"ceder al tráfico que viene por su izquierda"},{"t":"е с предимство пред насрещно движещите се ППС","ok":false,"i":null,"es":"tiene prioridad sobre el tráfico de frente"},{"t":"е с предимство пред попътно движещите се от лявата му страна ППС","ok":false,"i":null,"es":"tiene prioridad sobre el que viene por su izquierda"}],"sim":0.53,"es":"Cuando se da la vuelta desde la derecha por falta de anchura, el conductor debe: (2 correctas)","explain":"CEDER AL TRÁFICO DE FRENTE Y CEDER AL TRÁFICO QUE VIENE POR SU IZQUIERDA EN SU MISMO SENTIDO. Dos correctas.\n\nQUÉ VES. Un CAMIÓN en el carril DERECHO con el intermitente IZQUIERDO: por falta de anchura, va a dar la vuelta (cambio de sentido) empezando desde el carril derecho. Por el carril izquierdo, en su mismo sentido, va un coche ROJO.\n\nEL QUE HACE EL CAMBIO DE SENTIDO CEDE A TODOS. Al dar la vuelta desde la derecha atraviesa el carril de su izquierda (por donde va el rojo) y luego el carril contrario. Tiene que ceder a los que van en su sentido por la izquierda y a los que vienen de frente.\n\n«TIENE PRIORIDAD SOBRE LOS DE FRENTE» y «TIENE PRIORIDAD SOBRE LOS DE SU IZQUIERDA» son los cebos: el cambio de sentido no da prioridad sobre nadie.\n\nCLAVE: cambio de sentido = la maniobra que más cruza, y la que más cede. Compárala con la 6363 (la misma escena). Ver Leyes → «Cambio de sentido o media vuelta»."},{"id":5300,"bg":"Съединителят е предназначен:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"да прекъсва силовата връзка между двигателя и предавателната кутия","ok":true,"i":null,"es":"interrumpir la conexión entre el motor y la caja de cambios"},{"t":"да осъществява връзка между двигателя и карданното предаване","ok":false,"i":null,"es":"conectar el motor con la transmisión cardán"},{"t":"да съединява елементите на трансмисията с рамата","ok":false,"i":null,"es":"conectar los elementos de la transmisión con el chasis"},{"t":"да прекъсва връзката между предавателната кутия и карданното предаване","ok":false,"i":null,"es":"interrumpir la conexión entre la caja de cambios y el cardán"}],"sim":0.5,"es":"El embrague sirve para:","explain":"⚠️ TRAMPA mecánica: el embrague conecta/desconecta el motor de la CAJA DE CAMBIOS (no del cardán directamente). Es el primer eslabón de la transmisión."},{"id":5436,"bg":"При спускане по наклон честото и продължително използване на спирачките:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"влошава ефективността им","ok":true,"i":null,"es":"la eficacia de los frenos EMPEORA"},{"t":"подобрява ефективността им","ok":false,"i":null,"es":"la eficacia MEJORA"},{"t":"не влияе на ефективността им","ok":false,"i":null,"es":"no tiene efecto"}],"sim":0.5,"es":"Al bajar pendientes largas con frenos continuos y prolongados:","explain":"⚠️ TRAMPA: el uso continuo de frenos en descensos genera calor que REDUCE su eficacia (fading). Siempre usa el freno motor para descensos largos."},{"id":5440,"bg":"Количеството на течността в охладителната уредба е отчетено правилно, когато проверката на нивото на течността е извършена:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при студен двигател","ok":true,"i":null,"es":"con el motor FRÍO"},{"t":"без съобразяване с температурата на двигателя","ok":false,"i":null,"es":"sin importar la temperatura"},{"t":"при подгрят двигател","ok":false,"i":null,"es":"con el motor caliente"}],"sim":0.5,"es":"El nivel de líquido refrigerante se mide correctamente cuando:","explain":"⚠️ TRAMPA: siempre con el motor FRÍO. Con el motor caliente el líquido está bajo presión y en expansión — la lectura sería incorrecta y hay riesgo de quemarse."},{"id":5438,"bg":"При хидравлична охладителна уредба като охлаждаща течност може да се използва:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"вода","ok":true,"i":null,"es":"agua"},{"t":"нискозамръзваща течност /антифриз/","ok":true,"i":null,"es":"líquido anticongelante"},{"t":"смес от вода и спирачна течност","ok":false,"i":null,"es":"mezcla de agua y líquido de frenos"},{"t":"разредена със спирт нискозамръзваща течност /антифриз/","ok":false,"i":null,"es":"anticongelante diluido con alcohol"}],"sim":0.5,"es":"En sistemas de refrigeración hidráulica puede usarse como líquido: (2 correctas)","explain":"⚠️ TRAMPA: agua Y anticongelante son correctos. El líquido de frenos y el alcohol con anticongelante son incompatibles con los sistemas de refrigeración y los dañarían."},{"id":6706,"bg":"Масата с товар на превозното средство:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"включва масата на превозното средство","ok":true,"i":null,"es":"incluye la masa del vehículo"},{"t":"не включва масата на водача","ok":false,"i":null,"es":"no incluye la masa del conductor"},{"t":"не включва масата на пътниците","ok":false,"i":null,"es":"no incluye la masa de los pasajeros"},{"t":"включва масата на товара","ok":true,"i":null,"es":"incluye la masa de la carga"}],"sim":0.5,"es":"La masa con carga del vehículo: (2 correctas)","explain":"⚠️ TRAMPA: la masa con carga = masa del vehículo + carga + conductor + pasajeros. INCLUYE todo. Ningún elemento queda excluido — es la masa total en circulación."},{"id":12072,"bg":"Трамваите се приравняват към:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътните превозни средства","ok":true,"i":null,"es":"los vehículos de carretera (ПС/ППС)"},{"t":"моторните превозни средства","ok":false,"i":null,"es":"los vehículos a motor (МПС)"},{"t":"автомобилите със специално предназначение","ok":false,"i":null,"es":"los vehículos especiales"},{"t":"тролейбусите","ok":false,"i":null,"es":"los trolebuses"}],"sim":0.5,"es":"Los tranvías están equiparados a:","explain":"⚠️ TRAMPA: tranvía = vehículo de carretera (ПС). No es vehículo a MOTOR (МПС) porque no tiene motor de combustión. Tampoco es trolebús ni especial. Esta distinción legal tiene consecuencias en las normas."},{"id":5215,"bg":"Този знак предупреждава за възможна опасност от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334749.png","v":null,"a":[{"t":"работещи хора на платното за движение или в обхвата на пътя","ok":true,"i":null,"es":"trabajadores en la calzada o sus alrededores"},{"t":"строителни машини на платното за движение","ok":true,"i":null,"es":"maquinaria de construcción en la calzada"},{"t":"неравности по платното за движение","ok":true,"i":null,"es":"irregularidades en el pavimento"},{"t":"играещи деца на платното за движение","ok":false,"i":null,"es":"niños jugando en la calzada"}],"sim":0.5,"es":"Esta señal advierte del peligro de: (3 correctas)","explain":"TRABAJADORES EN LA CALZADA O SUS ALREDEDORES, MAQUINARIA DE CONSTRUCCIÓN E IRREGULARIDADES EN EL PAVIMENTO. Tres correctas.\n\nLA SEÑAL. Triángulo de peligro con fondo AMARILLO y un trabajador con pala: OBRAS.\n\nUNA OBRA TRAE TRES PELIGROS: personas trabajando, máquinas en la calzada y el firme levantado o irregular.\n\n«NIÑOS JUGANDO» es el cebo: tienen su propia señal (dos niños corriendo).\n\nCLAVE: compárala con la 5217 y la 5227. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5285,"bg":"Този пътен знак предупреждава за приближаване към:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334679.png","v":null,"a":[{"t":"железопътен прелез без бариери","ok":true,"i":null,"es":"paso a nivel SIN barreras"},{"t":"железопътен надлез","ok":false,"i":null,"es":"paso elevado sobre la vía ferroviaria"},{"t":"железопътна гара","ok":false,"i":null,"es":"estación de ferrocarril"},{"t":"железопътен прелез с автоматични бариери","ok":false,"i":null,"es":"paso a nivel CON barreras automáticas"}],"sim":0.5,"es":"Esta señal advierte de la proximidad de:","explain":"PASO A NIVEL SIN BARRERAS. Una sola correcta.\n\nLA SEÑAL. Triángulo de peligro con una LOCOMOTORA de vapor.\n\nLOCOMOTORA = PASO A NIVEL SIN BARRERAS. Como nada te detiene, la señal te enseña el tren.\n\n«CON BARRERAS AUTOMÁTICAS» se dibuja con la valla. «PASO ELEVADO» y «ESTACIÓN» no son el significado de esta señal.\n\nCLAVE: compárala con la 5286 y la 5287. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5290,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334681.png","v":null,"a":[{"t":"сигнализира, че железопътният прелез е с два или повече коловоза","ok":true,"i":null,"es":"indica que el paso a nivel tiene DOS O MÁS vías"},{"t":"забранява преминаването без спиране","ok":false,"i":null,"es":"prohíbe pasar sin detenerse"},{"t":"указва място за задължително спиране","ok":false,"i":null,"es":"indica lugar de parada obligatoria"},{"t":"сигнализира, че железопътният прелез е с един коловоз","ok":false,"i":null,"es":"indica que el paso a nivel tiene UNA vía"}],"sim":0.5,"es":"Esta señal:","explain":"INDICA QUE EL PASO A NIVEL TIENE DOS O MÁS VÍAS. Una sola correcta.\n\nLA SEÑAL. Cruz de San Andrés DOBLE: dos cruces rojas y blancas, una encima de otra.\n\nLA CRUZ DOBLE se coloca en el propio paso a nivel sin barreras cuando hay dos o más vías de tren. Detrás de un tren puede venir otro por la otra vía.\n\n«UNA VÍA» es la cruz simple. «PROHIBIDO PASAR SIN DETENERSE» y «PARADA OBLIGATORIA» son otras señales.\n\nCLAVE: compárala con la 5291 y la 5292. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5292,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334682.png","v":null,"a":[{"t":"сигнализира, че железопътният прелез е с един коловоз","ok":true,"i":null,"es":"indica que el paso a nivel tiene UNA vía"},{"t":"забранява навлизането срещу знака","ok":false,"i":null,"es":"prohíbe entrar en dirección contraria"},{"t":"предупреждава за кръстовище на равнозначни пътища","ok":false,"i":null,"es":"advierte de intersección de vías equivalentes"},{"t":"сигнализира, че железопътният прелез е с два или повече коловоза","ok":false,"i":null,"es":"indica que el paso a nivel tiene dos o más vías"}],"sim":0.5,"es":"Esta señal:","explain":"INDICA QUE EL PASO A NIVEL TIENE UNA SOLA VÍA. Una sola correcta.\n\nLA SEÑAL. Cruz de San Andrés SIMPLE, roja y blanca.\n\nLA CRUZ SIMPLE se coloca en el paso a nivel sin barreras de una sola vía.\n\n«DOS O MÁS VÍAS» es la cruz doble. «PROHIBIDA LA ENTRADA» es el círculo rojo con barra blanca. «CRUCE DE VÍAS IGUALES» es la X dentro de un triángulo.\n\nCLAVE: compárala con la 5290 y la 5293. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5540,"bg":"При коя от изброените височини автомобилът е извънгабаритен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височина 4,5 м","ok":true,"i":null,"es":"4.5 m"},{"t":"височина 4,3 м","ok":true,"i":null,"es":"4.3 m"},{"t":"височина 4,1 м","ok":true,"i":null,"es":"4.1 m"},{"t":"височина 3,9 м","ok":false,"i":null,"es":"3.9 m"}],"sim":0.5,"es":"¿A qué altura es un vehículo fuera de gálibo? (3 correctas)","explain":"⚠️ TRAMPA: fuera de gálibo si la altura supera 4.0 m. Son fuera de gálibo: 4.1, 4.3 y 4.5 m. Los 3.9 m están dentro del límite permitido."},{"id":5814,"bg":"Качването на дете до 12 години в автомобил, спрял на платното за движение, се извършва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"от страната на тротоара","ok":true,"i":null,"es":"el lado de la acera"},{"t":"от страната на пътния банкет","ok":true,"i":null,"es":"el lado del arcén"},{"t":"от която и да е страна на автомобила, когато детето е с възрастен придружител","ok":false,"i":null,"es":"cualquier lado si va con adulto"},{"t":"от страната на водача на МПС","ok":false,"i":null,"es":"el lado del conductor"}],"sim":0.5,"es":"La subida de niños menores de 12 años a un vehículo parado en calzada se hace por: (2 correctas)","explain":"⚠️ TRAMPA: los niños suben (y bajan) por el lado de la ACERA o del ARCÉN — nunca hacia el tráfico. Ir con adulto no cambia la regla. El lado del conductor puede ser el lado del tráfico."},{"id":6690,"bg":"При превоз на организирана група деца, автомобилът се обозначава с този опознавателен знак поставен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22861.png","v":null,"a":[{"t":"само отпред на автомобила","ok":false,"i":null,"es":"solo delante del automóvil"},{"t":"само отзад на автомобила","ok":false,"i":null,"es":"solo detrás del automóvil"},{"t":"отпред и отзад на автомобила","ok":true,"i":null,"es":"delante y detrás del automóvil"}],"sim":0.5,"es":"Al transportar un grupo organizado de niños, el coche lleva la señal:","explain":"DELANTE Y DETRÁS DEL AUTOMÓVIL. Una sola correcta.\n\nQUÉ VES. El distintivo NARANJA con dos niños caminando, el de transporte de un grupo organizado de niños.\n\nEL VEHÍCULO LO LLEVA DELANTE Y DETRÁS, para que lo vean tanto los que vienen de frente como los que van detrás.\n\n«SOLO DELANTE» y «SOLO DETRÁS» son los cebos: dejan sin aviso a una de las dos direcciones.\n\nCLAVE: compárala con la 5381 y la 5382."},{"id":6691,"bg":"При коя от изброените широчини, автомобилът е извънгабаритен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"широчина 2,9 м","ok":true,"i":null,"es":"2.9 m"},{"t":"широчина 2,7 м","ok":true,"i":null,"es":"2.7 m"},{"t":"широчина 2,5 м","ok":false,"i":null,"es":"2.5 m"},{"t":"широчина 2,3 м","ok":false,"i":null,"es":"2.3 m"}],"sim":0.5,"es":"¿A qué anchura es un vehículo fuera de gálibo? (2 correctas)","explain":"⚠️ TRAMPA: anchura máxima = 2.55m. Fuera de gálibo: 2.7m y 2.9m. Los 2.5m están dentro del límite permitido (exactamente en el umbral, pero se redondea a 2.5 como máximo)."},{"id":5975,"bg":"На кои от изброените превозни средства е забранено да навлизат след този знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334705.png","v":null,"a":[{"t":"мотоциклети с кош","ok":true,"i":null,"es":"motos CON sidecar"},{"t":"мотоциклети без кош","ok":false,"i":null,"es":"motos SIN sidecar"},{"t":"мотопеди","ok":false,"i":null,"es":"ciclomotores"},{"t":"велосипеди","ok":false,"i":null,"es":"bicicletas"}],"sim":0.5,"es":"¿A qué vehículos está PROHIBIDO entrar después de esta señal?","explain":"MOTOS CON SIDECAR. Una sola correcta.\n\nLA SEÑAL. Círculo con borde ROJO y la silueta de un COCHE: prohibida la entrada a los vehículos de motor, excepto motos SIN sidecar y ciclomotores.\n\nLA MOTO CON SIDECAR NO ESTÁ EXCEPTUADA: se trata como un coche, así que no puede entrar.\n\n«MOTOS SIN SIDECAR» y «CICLOMOTORES» son justo las excepciones. «BICICLETAS» no tienen motor.\n\nCLAVE: compárala con la 5973 y la 5974. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5984,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51835.png","v":null,"a":[{"t":"забранява влизането на МПС с ремаркета с две и повече оси","ok":true,"i":null,"es":"prohíbe la entrada de vehículos con remolques de dos o más ejes"},{"t":"не забранява влизането на МПС с полуремаркета","ok":false,"i":null,"es":"NO prohíbe la entrada de vehículos con semirremolques"},{"t":"забранява влизането на МПС с единични едноосни ремаркета","ok":true,"i":null,"es":"prohíbe la entrada de vehículos con remolques simples de un eje"}],"sim":0.5,"es":"Esta señal: (2 correctas)","explain":"PROHÍBE LA ENTRADA DE VEHÍCULOS CON REMOLQUES DE DOS O MÁS EJES Y CON REMOLQUES SIMPLES DE UN EJE. Dos correctas.\n\nLA SEÑAL. Círculo con borde ROJO con un REMOLQUE DE UN EJE dibujado solo (la misma de la 5983).\n\nLAS DOS SEÑALES DE REMOLQUE, QUE SE CONFUNDEN:\n• REMOLQUE DE UN EJE dibujado solo (sin vehículo tractor) = prohibido a TODOS los vehículos con remolque (de uno o más ejes, y semirremolques);\n• vehículo con REMOLQUE DE DOS EJES = prohibido a los que llevan remolque, EXCEPTO semirremolques y remolques simples de un eje.\n\n«NO PROHÍBE LOS SEMIRREMOLQUES» es el cebo: esa excepción es de la otra señal; esta prohíbe todos los remolques.\n\nCLAVE: compárala con la 5983. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6201,"bg":"Значението на този пътен знак е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334698.png","v":null,"a":[{"t":"еднопосочно движение след знака","ok":true,"i":null,"es":"tráfico de SENTIDO ÚNICO después de la señal"},{"t":"забранено е завиването наляво и надясно","ok":false,"i":null,"es":"prohibido girar a la izquierda y a la derecha"},{"t":"задължителна посока за движение","ok":false,"i":null,"es":"dirección OBLIGATORIA"},{"t":"движение само направо след знака","ok":false,"i":null,"es":"solo ir recto después"}],"sim":0.5,"es":"El significado de esta señal es:","explain":"SENTIDO ÚNICO DESPUÉS DE LA SEÑAL. Una sola correcta.\n\nLA SEÑAL. CUADRADO AZUL con una flecha blanca hacia arriba.\n\nEL CUADRADO AZUL INFORMA: la calle que empieza es de sentido único; todos circulan en la dirección de la flecha.\n\n«DIRECCIÓN OBLIGATORIA» y «SOLO RECTO» son el CÍRCULO azul con la misma flecha (6186). «PROHIBIDO GIRAR» serían señales circulares rojas.\n\nCLAVE: compárala con la 6199. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":6241,"bg":"Допълнителната табела указва, че забраната, въведена с този знак, важи само:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54125.png","v":null,"a":[{"t":"в неработни дни","ok":true,"i":null,"es":"en días NO laborables"},{"t":"в работни дни","ok":false,"i":null,"es":"en días laborables"}],"sim":0.5,"es":"La tablilla complementaria indica que la prohibición introducida por la señal aplica solo:","explain":"EN DÍAS NO LABORABLES.\n\nQUÉ VES. Señal de PROHIBIDA LA PARADA Y EL ESTACIONAMIENTO con una placa debajo con un MARTILLO Y UNA LLAVE cruzados, TACHADOS con una raya roja.\n\nEL MARTILLO Y LA LLAVE SIMBOLIZAN LOS DÍAS DE TRABAJO. Tachados = días NO laborables: la prohibición solo vale los fines de semana y festivos.\n\n«EN DÍAS LABORABLES» sería la misma placa sin tachar.\n\nCLAVE: herramientas = días laborables; herramientas tachadas = no laborables. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5834,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че може да премине направо или да завие надясно?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24064.png","v":null,"a":[{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche AZUL"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche VERDE"}],"sim":0.5,"es":"¿Para qué conductores la señal del agente significa paso PERMITIDO? (2 correctas)","explain":"PARA EL COCHE AMARILLO Y PARA EL COCHE AZUL. Dos correctas.\n\nQUÉ VES. Un AGENTE en el centro del cruce con los BRAZOS BAJADOS. Está de cara al coche ROJO (le muestra el pecho) y de espaldas al VERDE. El AMARILLO (a la izquierda) y el AZUL (a la derecha) lo ven de COSTADO.\n\nCÓMO SE LEE AL AGENTE CON LOS BRAZOS EXTENDIDOS O BAJADOS:\n• Si te muestra el COSTADO (izquierdo o derecho): puedes seguir RECTO o girar a la DERECHA.\n• Si te muestra el PECHO o la ESPALDA: prohibido pasar.\n\nPOR ESO pueden seguir recto o girar a la derecha el amarillo y el azul, que ven sus costados. El rojo (pecho) y el verde (espalda) tienen que parar.\n\n«EL ROJO» y «EL VERDE» son los cebos: están justo delante y detrás del agente, que es justo la posición que obliga a parar.\n\nCLAVE: costado = paso (recto y derecha); pecho o espalda = parar. Ver Leyes → «Quién manda sobre quién»."},{"id":5837,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че може да премине направо или да завие надясно?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24081.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche AZUL"}],"sim":0.5,"es":"¿Para qué conductores la señal del agente significa paso PERMITIDO? (2 correctas)","explain":"⚠️ TRAMPA color: el rojo Y el verde pueden pasar. El amarillo y el azul deben esperar. Esta posición del agente es diferente a la de ID 5834."},{"id":5839,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че преминаването е забранено във всички посоки?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24291.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche AZUL"}],"sim":0.5,"es":"¿Para qué conductores la señal del agente significa paso PROHIBIDO? (2 correctas)","explain":"⚠️ TRAMPA: PROHIBIDO para rojo Y verde. Permitido para amarillo y azul. La pregunta pregunta quién NO puede pasar — inverso a 5837."},{"id":5841,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че преминаването е забранено във всички посоки?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24340.png","v":null,"a":[{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche AZUL"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche VERDE"}],"sim":0.5,"es":"¿Para qué conductores la señal del agente significa paso PROHIBIDO? (2 correctas)","explain":"⚠️ TRAMPA: PROHIBIDO para amarillo Y azul. Permitido para rojo y verde. La pregunta pregunta quién NO puede pasar — inverso a 5834."},{"id":5857,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е разрешено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36480.png","v":null,"a":[{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche AZUL"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche AMARILLO"}],"sim":0.5,"es":"¿Para qué conductor la señal del agente tiene el significado de '¡Atención, para!'?","explain":"⚠️ TRAMPA: STOP para el AZUL — el agente tiene el brazo apuntando hacia él. Los demás colores pueden pasar o esperar según su posición."},{"id":5859,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е разрешено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36529.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche AZUL"}],"sim":0.5,"es":"¿Para qué conductor la señal del agente tiene el significado de '¡Atención, para!'?","explain":"⚠️ TRAMPA: STOP para el ROJO en esta posición específica del agente. Diferente a ID 5857 donde era el azul."},{"id":5867,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е забранено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36578.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche ROJO"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche AZUL"}],"sim":0.5,"es":"¿Para qué conductores la señal del agente significa '¡Atención, para!'? (3 correctas)","explain":"⚠️ TRAMPA: STOP para rojo, verde Y amarillo — tres coches. Solo el azul puede pasar. Cuando tres de cuatro deben parar, identifica al único que puede pasar."},{"id":5869,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е забранено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36662.png","v":null,"a":[{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche VERDE"},{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche AMARILLO"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche AZUL"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche ROJO"}],"sim":0.5,"es":"¿Para qué conductores la señal del agente significa paso PERMITIDO? (3 correctas)","explain":"⚠️ TRAMPA: paso permitido para verde, amarillo Y azul. Solo el rojo debe esperar. Tres de cuatro pueden pasar."},{"id":5891,"bg":"Значението на този немигащ сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39865.png","v":null,"a":[{"t":"„Преминаването е забранено”","ok":true,"i":null,"es":"'El paso está PROHIBIDO'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"}],"sim":0.5,"es":"El significado de esta señal fija del semáforo es:","explain":"«EL PASO ESTÁ PROHIBIDO». Una sola correcta.\n\nQUÉ VES. Un semáforo con la luz ROJA encendida, fija.\n\nROJO FIJO = «ПРЕМИНАВАНЕТО Е ЗАБРАНЕНО». Es la prohibición de pasar.\n\n«¡ATENCIÓN, PARA!» es el nombre oficial del ÁMBAR fijo, no del rojo. Es el cebo principal: los dos impiden entrar, pero cada luz tiene su nombre.\n\n«¡ATENCIÓN!» es el ámbar INTERMITENTE.\n\n«EL PASO ESTÁ PERMITIDO» es el verde.\n\nCLAVE: memoriza los cuatro nombres: rojo = paso prohibido; ámbar fijo = atención, para; ámbar intermitente = atención; verde = paso permitido. Ver Leyes → «El semáforo: cada luz tiene un nombre oficial»."},{"id":5900,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41967.png","v":null,"a":[{"t":"„Преминаването е забранено”","ok":true,"i":null,"es":"'El paso está PROHIBIDO'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"}],"sim":0.5,"es":"El significado de esta señal de semáforo es:","explain":"⚠️ TRAMPA: semáforo rojo = PROHIBIDO. Parece obvio pero aparece frecuentemente en el examen para asegurarse de que sabes exactamente el nombre de cada señal."},{"id":5830,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57569.png","v":null,"a":[{"t":"означава край на задължителната минимална скорост","ok":true,"i":null,"es":"indica FIN de la velocidad mínima obligatoria"},{"t":"забранява движението със скорост по-висока от означената","ok":false,"i":null,"es":"prohíbe velocidad superior a la indicada"},{"t":"забранява движението със скорост по-ниска от означената","ok":false,"i":null,"es":"prohíbe velocidad inferior a la indicada"},{"t":"означава край на препоръчителната скорост на движение","ok":false,"i":null,"es":"indica fin de la velocidad recomendada"}],"sim":0.5,"es":"Esta señal:","explain":"INDICA EL FIN DE LA VELOCIDAD MÍNIMA OBLIGATORIA. Una sola correcta.\n\nLA SEÑAL. Círculo AZUL con «30» en blanco, cruzado por una BARRA ROJA diagonal.\n\nEL CÍRCULO AZUL CON CIFRA ES LA VELOCIDAD MÍNIMA; la barra roja lo anula. A partir de aquí ya no estás obligado a ir al menos a 30 km/h.\n\n«PROHÍBE VELOCIDAD SUPERIOR» sería un círculo de borde rojo. «PROHÍBE VELOCIDAD INFERIOR» sería la propia señal de mínimo, sin tachar.\n\n«FIN DE LA VELOCIDAD RECOMENDADA» es el cebo fino: la recomendada es CUADRADA; esta es redonda.\n\nCLAVE: redondo azul + barra = fin del mínimo. Ver Leyes → «Señales verticales: la forma manda sobre el dibujo»."},{"id":5849,"bg":"При спиране на автомобила дължината на спирачния път зависи от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"скоростта на движение","ok":true,"i":null,"es":"la velocidad"},{"t":"състоянието на гумите","ok":true,"i":null,"es":"el estado de los neumáticos"},{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"диаметъра на гумите","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"sim":0.5,"es":"La distancia de frenado depende de: (3 correctas)","explain":"⚠️ TRAMPA: velocidad + estado de neumáticos + estado del pavimento determinan la distancia de frenado. El DIÁMETRO de los neumáticos no es un factor determinante."},{"id":5864,"bg":"Интервалът от 2 секунди между движещите се леки автомобили е достатъчен когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"пътят е сух","ok":true,"i":null,"es":"el camino está SECO"},{"t":"видимостта е намалена поради мъгла","ok":false,"i":null,"es":"la visibilidad está reducida por niebla"},{"t":"пътят е мокър","ok":false,"i":null,"es":"el camino está mojado"},{"t":"видимостта е ограничена","ok":false,"i":null,"es":"la visibilidad es limitada"}],"sim":0.5,"es":"El intervalo de 2 segundos entre turismos es suficiente cuando:","explain":"⚠️ TRAMPA: 2 segundos es suficiente SOLO en carretera SECA y buenas condiciones. Con lluvia, niebla o hielo la distancia debe aumentarse significativamente."},{"id":6230,"bg":"При тази ситуация с предимство е водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71987.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"el coche ROJO"},{"t":"на синия автомобил","ok":false,"i":null,"es":"el coche AZUL"}],"sim":0.5,"es":"En esta situación tiene prioridad:","explain":"EL CONDUCTOR DEL COCHE ROJO. Una sola correcta.\n\nQUÉ VES. Carretera de dos carriles en el mismo sentido. La señal azul de la derecha muestra que el carril DERECHO se ACABA y se une al izquierdo. El coche AZUL, en el carril derecho, lleva el intermitente izquierdo para pasarse al carril del ROJO.\n\nCEDE EL QUE CAMBIA DE CARRIL. Al terminarse su carril, el azul tiene que meterse en el del rojo, y para eso le cede el paso al que ya circula por él.\n\n«EL AZUL» es el cebo de quien aplica la regla de la derecha. Aquí no hay dos vehículos que convergen en un tercer carril (como en la 6233): hay uno que entra en el carril del otro.\n\nCLAVE: si tu carril se acaba, cedes al que va por el carril al que entras. Ver Leyes → «Carril: dónde debes circular»."},{"id":6234,"bg":"При тази ситуация с предимство е водачът на автомобила, който:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69702.png","v":null,"a":[{"t":"се намира отдясно","ok":true,"i":null,"es":"está a la DERECHA"},{"t":"се намира отляво","ok":false,"i":null,"es":"está a la IZQUIERDA"},{"t":"първи е подал сигнал за маневра","ok":false,"i":null,"es":"primero señalizó la maniobra"},{"t":"е по-напред от другия","ok":false,"i":null,"es":"está más adelantado"}],"sim":0.5,"es":"En esta situación tiene prioridad el conductor cuyo vehículo:","explain":"⚠️ TRAMPA: a la DERECHA. La regla de la derecha es la base de las intersecciones sin señalización. Señalizar primero o estar más adelante no da prioridad."},{"id":6267,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70117.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder el paso al ROJO"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el ROJO"}],"sim":0.5,"es":"En esta situación debo:","explain":"CEDER EL PASO AL ROJO. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. De frente viene un coche ROJO con el intermitente puesto, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«PASAR ANTES QUE EL ROJO» es el cebo de quien piensa que, como el rojo también gira, ya no hay que cederle.\n\nCLAVE: es la misma imagen que la 6266. Girar a la izquierda = ceder a lo que viene de frente. Ver Leyes → «Giro a la izquierda»."},{"id":6268,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70117.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder el paso al ROJO"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el ROJO"}],"sim":0.5,"es":"En esta situación debo:","explain":"CEDER EL PASO AL ROJO. Una sola correcta.\n\nQUÉ VES. Llevas el intermitente IZQUIERDO y vas a girar a la izquierda. De frente viene un coche ROJO con el intermitente puesto, que gira a SU derecha. Los dos vais a entrar en la misma calle (la de tu izquierda).\n\nCUANDO DOS VEHÍCULOS QUE VIENEN DE FRENTE VAN A LA MISMA CALLE, el que gira a la DERECHA pasa antes que el que gira a la IZQUIERDA. El que gira a la izquierda cruza la trayectoria del otro y le cede.\n\n«PASAR ANTES QUE EL ROJO» es el cebo de quien piensa que, como el rojo también gira, ya no hay que cederle.\n\nCLAVE: es la misma imagen que la 6266. Girar a la izquierda = ceder a lo que viene de frente. Ver Leyes → «Giro a la izquierda»."},{"id":6269,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70217.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar ANTES que el rojo"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder el paso al rojo"}],"sim":0.5,"es":"En esta situación debo:","explain":"⚠️ TRAMPA: aquí pasas ANTES que el rojo. Opuesto a las dos anteriores. La imagen determina quién tiene prioridad — lee cuidadosamente."},{"id":12041,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да увелича скоростта","ok":false,"i":null,"es":"aumentar la velocidad"},{"t":"да се движа възможно най-вдясно","ok":true,"i":null,"es":"circular todo lo posible a la DERECHA"},{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"}],"sim":0.5,"es":"¿Qué debes hacer en esta situación? (2 correctas)","explain":"⚠️ TRAMPA: circula a la derecha Y reduce velocidad. Acelerar nunca es la respuesta ante una situación de peligro o incertidumbre."},{"id":6511,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61772.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"ceder al TRANVÍA"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el TURISMO"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"ceder al turismo"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL TRANVÍA Y PASAR ANTES QUE EL TURISMO. Dos correctas.\n\nQUÉ VES. En el poste de la derecha hay una señal de VÍA CON PRIORIDAD con PANEL: el trazo GRUESO sube desde tu posición y gira a la IZQUIERDA. Por la izquierda, sobre la rama gruesa, viene un TRANVÍA. Por la DERECHA, por una rama fina, llega un turismo ROJO con el intermitente puesto. Tú vas a girar a la izquierda.\n\nAL TRANVÍA LE CEDES: está en la vía preferente, como tú, y el tranvía pasa antes que los coches.\n\nAL TURISMO LE PASAS TÚ: viene por la rama fina, la secundaria, así que te cede aunque esté a tu derecha.\n\n«PASAR ANTES QUE EL TRANVÍA» y «CEDER AL TURISMO» son las dos respuestas al revés.\n\nCLAVE: primero separa ramas gruesas y finas; luego recuerda que el tranvía va primero. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches."},{"id":6515,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61654.png","v":null,"a":[{"t":"да пропусна лекия автомобил","ok":true,"i":null,"es":"ceder al TURISMO"},{"t":"да пропусна трамвая","ok":true,"i":null,"es":"ceder al TRANVÍA"},{"t":"да премина преди лекия автомобил","ok":false,"i":null,"es":"pasar antes que el turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL TURISMO Y CEDER AL TRANVÍA. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES de prioridad. Por la izquierda viene un TRANVÍA. Por la DERECHA llega un turismo ROJO con el intermitente puesto.\n\nAL TURISMO, POR LA DERECHA. Sin señales, cedes al que te llega por la derecha.\n\nAL TRANVÍA, PORQUE ES UN TRANVÍA. En un cruce sin señales, el tranvía pasa antes que los vehículos sin raíles, venga por donde venga.\n\n«PASAR ANTES QUE EL TURISMO» y «PASAR ANTES QUE EL TRANVÍA» son las respuestas al revés.\n\nCLAVE: compárala con la 6511: misma escena pero SIN panel; sin señales, el rojo de la derecha recupera la prioridad. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha. Y el tranvía, en general, pasa antes que los coches."},{"id":6524,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57242.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el ROJO"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el AZUL"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA: pasas antes que el ROJO Y antes que el AZUL. Tienes prioridad sobre ambos en esta intersección específica."},{"id":6525,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57314.png","v":null,"a":[{"t":"само червения автомобил","ok":true,"i":null,"es":"solo al ROJO"},{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al AZUL"},{"t":"и двата автомобила","ok":false,"i":null,"es":"a los DOS"}],"sim":0.5,"es":"En esta situación debo ceder el paso:","explain":"⚠️ TRAMPA: solo al ROJO. El azul no tiene prioridad sobre ti en esta imagen."},{"id":6529,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61585.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"ceder al TRANVÍA"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el TURISMO"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"ceder al turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"DEJAR PASAR AL TRANVÍA Y PASAR ANTES QUE EL TURISMO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES ni semáforo. Vas recto (flecha). De frente viene un TRANVÍA con el intermitente, que gira por sus vías hacia tu derecha, cruzando tu trayectoria. Por tu IZQUIERDA llega un turismo ROJO que sigue recto.\n\nAL TRANVÍA LE CEDES. En un cruce de vías iguales, el tranvía pasa siempre antes que los vehículos sin raíles, gire hacia donde gire.\n\nAL TURISMO LE PASAS TÚ. Llega por tu izquierda: tú estás a su derecha, así que él te cede.\n\n«DEJAR PASAR AL TURISMO» y «PASAR ANTES QUE EL TRANVÍA» son las dos respuestas al revés.\n\nCLAVE: dos reglas a la vez: tranvía = primero siempre; entre coches = la derecha.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay panel bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Ver Leyes → «Quién manda sobre quién» y «Regla de la derecha»."},{"id":6533,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61451.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"ceder al TRANVÍA"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el TURISMO"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"ceder al turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL TRANVÍA Y PASAR ANTES QUE EL TURISMO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por la DERECHA viene un TRANVÍA. Por la IZQUIERDA, un turismo ROJO.\n\nAL TRANVÍA LE CEDES: en un cruce sin señales el tranvía pasa antes que los vehículos sin raíles (y además viene por tu derecha).\n\nAL TURISMO LE PASAS TÚ: llega por tu izquierda, así que te cede.\n\n«CEDER AL TURISMO» y «PASAR ANTES QUE EL TRANVÍA» son las respuestas al revés.\n\nCLAVE: tranvía primero; entre coches, la derecha. Compárala con la 6535. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). El tranvía, en general, pasa antes que los coches."},{"id":6540,"bg":"При тази ситуация водачът на зеления автомобил трябва да пропусне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68541.png","v":null,"a":[{"t":"само синия автомобил","ok":true,"i":null,"es":"solo al AZUL"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al ROJO"},{"t":"двата автомобила","ok":false,"i":null,"es":"a los DOS"}],"sim":0.5,"es":"En esta situación el conductor del coche verde debe ceder el paso:","explain":"⚠️ TRAMPA color: verde cede solo al AZUL. El rojo no tiene prioridad sobre el verde en esta imagen."},{"id":6542,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65568.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al AZUL"},{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder al ROJO"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL AZUL Y CEDER AL ROJO. Dos correctas.\n\nQUÉ VES. La misma escena que la 6541: CEDA EL PASO con PANEL cuyo trazo GRUESO baja desde ARRIBA y gira a la IZQUIERDA. De frente, por la rama gruesa, el ROJO; por la DERECHA, por una rama fina, el AZUL. Tú vas recto por la otra rama fina.\n\nAL ROJO, POR LA SEÑAL. AL AZUL, POR LA DERECHA.\n\n«PASAR ANTES QUE EL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: es la misma regla que la 6541, preguntada en formato de dos casillas. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Cuando la prioritaria cambia de dirección»."},{"id":6546,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68490.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el ROJO"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el AZUL"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"Esta es una pregunta multirespuesta (dos correctas: pasar antes que ambos coches). Eso significa que en esta intersección concreta TÚ tienes prioridad sobre los dos vehículos de colores — probablemente porque circulas por una vía con prioridad marcada con señal, o porque ambos coches están girando hacia tu trayectoria y deben cederte el paso a ti (el que va recto tiene prioridad sobre el que gira). Truco para identificarlo en la imagen: si ves que las flechas o posición de las ruedas de los otros coches indican que van a girar, y tú vas recto, tú casi siempre tienes prioridad sobre ambos."},{"id":6559,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68404.png","v":null,"a":[{"t":"да пропусне червения автомобил","ok":true,"i":null,"es":"ceder al ROJO"},{"t":"да пропусне синия автомобил","ok":true,"i":null,"es":"ceder al AZUL"},{"t":"да премине преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да премине преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"sim":0.5,"es":"En esta situación el verde debe: (2 correctas)","explain":"DEJAR PASAR AL COCHE ROJO Y DEJAR PASAR AL COCHE AZUL. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES ni semáforo. El coche VERDE (el de delante de ti en la imagen) lleva el intermitente IZQUIERDO: va a girar a la izquierda. De frente viene un coche ROJO, también con intermitente, que gira hacia la calle de la izquierda. Por la DERECHA del verde llega un coche AZUL que sigue recto.\n\nAL AZUL, POR LA DERECHA. Sin señales, el verde cede al que le llega por su derecha, y ese es el azul.\n\nAL ROJO, POR EL GIRO A LA IZQUIERDA. Quien gira a la izquierda cede a los que vienen de frente y siguen recto o giran a su derecha. El rojo viene de frente y gira a SU derecha (hacia la calle de tu izquierda): tiene preferencia sobre el verde.\n\n«PASAR ANTES QUE EL AZUL» y «PASAR ANTES QUE EL ROJO» son las mismas respuestas al revés: el verde no pasa antes que ninguno.\n\nCLAVE: el que gira a la izquierda en un cruce sin señales suele ser el último: cede a la derecha y a lo que viene de frente.\n\nMÉTODO: 1) ¿quién viene por la derecha? 2) ¿quién viene de frente, y gira a la izquierda yo? 3) cedo a ambos. Ver Leyes → «Regla de la derecha» y «Giro a la izquierda»."},{"id":6565,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68353.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"ceder al ROJO"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"ceder al AZUL"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"CEDER AL ROJO Y CEDER AL AZUL. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Llevas el intermitente IZQUIERDO: vas a girar a la izquierda. De frente viene un coche AZUL. Por la DERECHA llega un coche ROJO.\n\nAL ROJO, POR LA DERECHA: te llega por la derecha.\n\nAL AZUL, POR EL GIRO: vas a girar a la izquierda y viene de frente.\n\n«PASAR ANTES QUE EL AZUL» y «PASAR ANTES QUE EL ROJO» son las respuestas al revés.\n\nCLAVE: girar a la izquierda sin señales = cedes a la derecha y a lo que viene de frente. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Giro a la izquierda»."},{"id":6567,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68303.png","v":null,"a":[{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el AZUL"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el ROJO"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"ceder al azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"PASAR ANTES QUE EL AZUL Y PASAR ANTES QUE EL ROJO. Dos correctas.\n\nQUÉ VES. Un cruce SIN SEÑALES. Vas RECTO. Por tu IZQUIERDA llega una furgoneta AZUL que sigue recto. De frente viene un coche ROJO con el intermitente, que va a girar a SU izquierda cruzando tu trayectoria.\n\nAL AZUL LE PASAS: te llega por la izquierda; tú estás a su derecha.\n\nAL ROJO LE PASAS: gira a la izquierda y tú vienes de frente recto; el que gira a la izquierda cede al de frente.\n\n«CEDER AL AZUL» y «CEDER AL ROJO» son los cebos de quien cede «por si acaso».\n\nCLAVE: aquí nadie te llega por la derecha y el de frente gira a la izquierda: pasas tú primero. MÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? 3) ¿hay señal y panel? 4) si nada separa a los dos, decide la derecha (y el que gira a la izquierda cede al de frente). Ver Leyes → «Regla de la derecha»."},{"id":6574,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68169.png","v":null,"a":[{"t":"да пропусна мотоциклетиста","ok":true,"i":null,"es":"ceder al MOTORISTA"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el ROJO"},{"t":"да премина преди мотоциклетиста","ok":false,"i":null,"es":"pasar antes que el motorista"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"ceder al rojo"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA: cedes al MOTORISTA (tiene prioridad) y pasas antes que el ROJO. Las motos tienen exactamente las mismas reglas de prioridad que los coches."},{"id":6576,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67906.png","v":null,"a":[{"t":"да пропусна лекия автомобил","ok":true,"i":null,"es":"ceder al TURISMO"},{"t":"да пропусна товарния автомобил","ok":true,"i":null,"es":"ceder al CAMIÓN"},{"t":"да премина преди лекия автомобил","ok":false,"i":null,"es":"pasar antes que el turismo"},{"t":"да премина преди товарния автомобил","ok":false,"i":null,"es":"pasar antes que el camión"}],"sim":0.5,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ TRAMPA: cedes tanto al TURISMO como al CAMIÓN. Ambos tienen prioridad. El tamaño del vehículo no determina la prioridad."},{"id":5427,"bg":"В кои случаи автомобилът, спрян в лентата за принудително спиране на автомагистрала, задължително се сигнализира?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"през нощта","ok":true,"i":null,"es":"de NOCHE"},{"t":"при намалена видимост","ok":true,"i":null,"es":"con visibilidad REDUCIDA"},{"t":"винаги","ok":false,"i":null,"es":"SIEMPRE"},{"t":"при ограничена видимост","ok":false,"i":null,"es":"con visibilidad LIMITADA"}],"sim":0.5,"es":"¿En qué casos el vehículo parado en el carril de emergencia de autopista debe señalizarse? (2 correctas)","explain":"Regla de señalización obligatoria para vehículos detenidos en el carril de emergencia: debes señalizar (con triángulo de emergencia y/o luces de avería) en DOS situaciones concretas: durante la noche, y cuando hay visibilidad reducida (niebla, lluvia intensa, etc.) — no es una obligación constante en todo momento del día con buena visibilidad, sino específicamente cuando la luz natural no es suficiente para que otros conductores te vean a tiempo. Ojo con la trampa de la opción 'siempre' — el código no exige señalización permanente, solo cuando las condiciones de visibilidad lo requieren."},{"id":8280,"bg":"В кои случаи автомобилът, спрян върху площадката за принудително спиране на скоростен път, задължително се сигнализира?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"през нощта","ok":true,"i":null,"es":"de NOCHE"},{"t":"при намалена видимост","ok":true,"i":null,"es":"con visibilidad REDUCIDA"},{"t":"винаги","ok":false,"i":null,"es":"SIEMPRE"},{"t":"при ограничена видимост","ok":false,"i":null,"es":"con visibilidad LIMITADA"}],"sim":0.5,"es":"¿En qué casos el vehículo parado en área de emergencia de vía rápida debe señalizarse? (2 correctas)","explain":"⚠️ TRAMPA: igual que en autopista — noche Y visibilidad reducida. La diferencia entre 'reducida' y 'limitada' es sutil pero importante en la terminología búlgara."},{"id":11716,"bg":"Навлизането по автомагистрала е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при теглене на МПС с гъвкава връзка","ok":true,"i":null,"es":"cuando se remolca con cable FLEXIBLE"},{"t":"когато поради повреда МПС не може да се движи със скорост по-висока от 50 km/h","ok":true,"i":null,"es":"cuando por avería el vehículo no puede superar 50 km/h"},{"t":"при превоз на животни","ok":false,"i":null,"es":"al transportar animales"},{"t":"при теглене с твърда връзка","ok":false,"i":null,"es":"cuando se remolca con barra RÍGIDA"}],"sim":0.5,"es":"La entrada en autopista está PROHIBIDA: (2 correctas)","explain":"⚠️ TRAMPA: prohibido entrar a autopista remolcando con cable flexible (muy peligroso a alta velocidad) Y si no puedes superar 50 km/h. Con barra rígida SÍ está permitido entrar."},{"id":6683,"bg":"При теглене на повреден автомобил е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"превозване на пътници в тегленото моторно превозно средство","ok":true,"i":null,"es":"transportar pasajeros en el vehículo REMOLCADO"},{"t":"теглене с гъвкава връзка по хлъзгав път","ok":true,"i":null,"es":"remolcar con cable flexible en carretera resbaladiza"},{"t":"превоз на пътници в теглещото превозно средство","ok":false,"i":null,"es":"transportar pasajeros en el vehículo REMOLCADOR"},{"t":"теглещото МПС да е от категория, различна от тази на тегленото МПС","ok":false,"i":null,"es":"el vehículo remolcador ser de categoría diferente al remolcado"}],"sim":0.5,"es":"Al remolcar un vehículo averiado está PROHIBIDO: (2 correctas)","explain":"⚠️ TRAMPA: pasajeros en el REMOLCADO está prohibido (peligroso). Cable flexible en carretera resbaladiza prohibido. En el REMOLCADOR SÍ pueden ir pasajeros. La categoría diferente no es impedimento."},{"id":12081,"bg":"Тегленето на повредено МПС с допустима максимална маса над 5 t е разрешено да се извършва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с твърда връзка","ok":true,"i":null,"es":"con barra RÍGIDA"},{"t":"от автомобил със специално предназначение за тази цел","ok":true,"i":null,"es":"por un vehículo con equipamiento especial para ese fin"},{"t":"с гъвкава връзка","ok":false,"i":null,"es":"con cable FLEXIBLE"},{"t":"само от автомобил със специално приспособление","ok":false,"i":null,"es":"solo por vehículo con dispositivo especial de enganche"}],"sim":0.5,"es":"Remolcar un vehículo averiado con MMA superior a 5 t está permitido: (2 correctas)","explain":"⚠️ TRAMPA: vehículos pesados (+5t) solo pueden remolcarse con barra RÍGIDA o mediante grúa especializada. El cable flexible está prohibido para vehículos de más de 5t."},{"id":5580,"bg":"От коя страна на еднопосочен път в населено място е разрешено паркирането?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от дясната страна","ok":true,"i":null,"es":"por el lado DERECHO"},{"t":"от лявата страна","ok":false,"i":null,"es":"por el lado izquierdo"},{"t":"от двете страни","ok":false,"i":null,"es":"por ambos lados"}],"sim":0.5,"es":"¿Por qué lado de una calle de sentido único en zona urbana está permitido aparcar?","explain":"⚠️ TRAMPA: en sentido único el aparcamiento es solo por el DERECHO. El izquierdo puede admitir prestoy pero no aparcamiento completo."},{"id":5604,"bg":"Къде по пътищата извън населените места е разрешено паркирането?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"извън платното за движение","ok":true,"i":null,"es":"fuera de la CALZADA"},{"t":"на обозначените за тази цел места","ok":true,"i":null,"es":"en lugares SEÑALIZADOS para ello"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"en el extremo derecho de la calzada"}],"sim":0.5,"es":"¿Dónde está permitido aparcar fuera de población? (2 correctas)","explain":"⚠️ TRAMPA: fuera de ciudad aparcar fuera de calzada O en zona señalizada. En el extremo derecho de la CALZADA NO está permitido — diferente a dentro de la ciudad."},{"id":6136,"bg":"В коя част от денонощието остротата на зрението на човека намалява значително?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"в светлата част","ok":false,"i":null,"es":"en la parte OSCURA (noche)"},{"t":"в тъмната част","ok":true,"i":null,"es":"en la parte luminosa (día)"},{"t":"остротата на зрението не се променя през денонощието","ok":false,"i":null,"es":"la agudeza visual no varía"}],"sim":0.5,"es":"¿En qué parte del día la agudeza visual del ser humano disminuye significativamente?","explain":"⚠️ TRAMPA: la visión empeora de NOCHE, no de día. Parece obvio pero el examen pregunta de forma directa para confirmar el conocimiento."},{"id":5994,"bg":"Задължение на водача е превозваният товар:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да не закрива огледалата за виждане назад","ok":true,"i":null,"es":"no tape los retrovisores"},{"t":"да не закрива светлинните и сигналните устройства на автомобила","ok":true,"i":null,"es":"no tape los dispositivos de iluminación y señalización"},{"t":"да е укрепен","ok":true,"i":null,"es":"esté asegurada"},{"t":"да е застрахован","ok":false,"i":null,"es":"esté asegurada con seguro"}],"sim":0.5,"es":"El conductor está obligado a que la carga: (3 correctas)","explain":"⚠️ TRAMPA: la carga no debe tapar retrovisores + luces + debe estar asegurada mecánicamente. Tener un seguro de la carga no es una obligación de tráfico."},{"id":6008,"bg":"При движение през нощта по кой от изброените начини може да се обозначи товар, който излиза с повече от 1 м отпред на най-издадената част на превозното средство?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с бял светлоотразител","ok":true,"i":null,"es":"con reflectante BLANCO"},{"t":"с бяла светлина","ok":true,"i":null,"es":"con luz BLANCA"},{"t":"с червен флаг","ok":false,"i":null,"es":"con bandera roja"},{"t":"с червена светлина","ok":false,"i":null,"es":"con luz ROJA"}],"sim":0.5,"es":"De noche, ¿cómo puede señalizarse la carga que sobresale más de 1m por DETRÁS? (2 correctas)","explain":"⚠️ TRAMPA: carga sobresaliente por DETRÁS de noche = reflectante blanco O luz blanca. De día = bandera roja. No confundas delante/detrás ni día/noche."},{"id":6010,"bg":"При движение през нощта по кой от изброените начини може да се обозначи товар, който излиза с повече от 1 м отзад на най-издадената част на превозното средство?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с червен светлоотразител","ok":true,"i":null,"es":"con reflectante ROJO"},{"t":"с червена светлина","ok":true,"i":null,"es":"con luz ROJA"},{"t":"с червен флаг","ok":false,"i":null,"es":"con bandera roja"},{"t":"с бяла светлина","ok":false,"i":null,"es":"con luz blanca"}],"sim":0.5,"es":"De noche, ¿cómo puede señalizarse la carga que sobresale más de 1m por DETRÁS? (2 correctas)","explain":"⚠️ TRAMPA: hay dos preguntas similares (6008 y 6010) con respuestas diferentes. Esta versión acepta reflectante ROJO Y luz ROJA para la parte trasera. Compara con 6008."},{"id":6011,"bg":"При движение през деня, товарът, който излиза с повече от 1 м отпред или отдзад на най-издадената част на превозното средство, се обозначава:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с червен флаг","ok":true,"i":null,"es":"bandera ROJA"},{"t":"с червена светлина","ok":false,"i":null,"es":"luz roja"},{"t":"с бяла светлина","ok":false,"i":null,"es":"luz blanca"},{"t":"с червен светлоотразител","ok":false,"i":null,"es":"reflectante rojo"}],"sim":0.5,"es":"De día, la carga que sobresale más de 1m por DELANTE debe señalizarse con:","explain":"⚠️ TRAMPA: de DÍA por DELANTE = bandera ROJA. De noche por delante = reflectante/luz blanca. De noche por detrás = reflectante/luz roja."},{"id":6012,"bg":"Товарът не се обозначава, ако излиза отпред на най-издадената част на ППС на разстояние:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 1 м","ok":true,"i":null,"es":"hasta 1 m"},{"t":"до 1,5 м","ok":false,"i":null,"es":"hasta 1.5 m"},{"t":"до 2 м","ok":false,"i":null,"es":"hasta 2 m"},{"t":"до 3 м","ok":false,"i":null,"es":"hasta 3 m"}],"sim":0.5,"es":"La carga no necesita señalizarse si sobresale por DELANTE:","explain":"⚠️ TRAMPA de distancias: 1 metro por delante sin señalización. Más de 1m = obligatorio señalizar. Este umbral específico (1m delante) es diferente a los lados (0.2m) y detrás (1m también)."},{"id":6013,"bg":"Товарът не се обозначава, ако излиза отстрани на най-издадената част на ППС на разстояние:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 0,2 м","ok":true,"i":null,"es":"hasta 0.2 m"},{"t":"до 0,5 м","ok":false,"i":null,"es":"hasta 0.5 m"},{"t":"до 1,0 м","ok":false,"i":null,"es":"hasta 1.0 m"},{"t":"до 1,5 м","ok":false,"i":null,"es":"hasta 1.5 m"}],"sim":0.5,"es":"La carga no necesita señalizarse si sobresale POR LOS LADOS:","explain":"⚠️ TRAMPA de distancias: por los LADOS solo 0.2 metros sin señalización. Mucho menos que por delante o detrás (1m). Los lados tienen el umbral más restrictivo."},{"id":6014,"bg":"Товарът не се обозначава, ако излиза отзад на най-издадената част на ППС на разстояние:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 1 м","ok":true,"i":null,"es":"hasta 1 m"},{"t":"до 1,5 м","ok":false,"i":null,"es":"hasta 1.5 m"},{"t":"до 2 м","ok":false,"i":null,"es":"hasta 2 m"},{"t":"до 3 м","ok":false,"i":null,"es":"hasta 3 m"}],"sim":0.5,"es":"La carga no necesita señalizarse si sobresale por DETRÁS:","explain":"⚠️ TRAMPA: por DETRÁS también es 1 metro sin señalización, igual que por delante. Por los lados es solo 0.2m. Memoriza: delante=1m, detrás=1m, lados=0.2m."},{"id":11372,"bg":"Водачът на ППС е длъжен да не извършва маневри, изразяващи се в последователно внезапно преминаване в лентите за движение:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"само в населените места","ok":false,"i":null,"es":"en zonas urbanas Y fuera de ellas"},{"t":"само извън населените места","ok":false,"i":null,"es":"solo en zonas urbanas"},{"t":"в населените и извън населените места","ok":true,"i":null,"es":"solo fuera de zonas urbanas"}],"sim":0.5,"es":"El conductor no debe realizar maniobras de cambio de carril brusco y consecutivo:","explain":"⚠️ TRAMPA: la prohibición aplica EN TODOS LOS LUGARES — ciudad y carretera. No es una restricción solo urbana o solo rural."},{"id":11500,"bg":"За административно нарушение, установено и заснето с автоматизирано техническо средство може да бъде наложена глоба с електронен фиш, когато:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"за нарушението не е предвидено лишаване от право да управлява МПС","ok":true,"i":null,"es":"no tiene previsto privación del permiso"},{"t":"за нарушението не е предвидено отнемане на контролни точки","ok":true,"i":null,"es":"no tiene previsto retirada de puntos"},{"t":"за нарушението не е предвидено служебно прекратяване на регистрацията на МПС","ok":false,"i":null,"es":"no tiene previsto cancelación del registro del vehículo"},{"t":"за нарушението не е предвидено спиране от движение на МПС","ok":false,"i":null,"es":"no tiene previsto inmovilización del vehículo"}],"sim":0.5,"es":"Una infracción captada por cámara automática puede sancionarse con multa electrónica si: (2 correctas)","explain":"⚠️ TRAMPA: la multa electrónica (sin presencia del agente) solo puede aplicarse cuando la infracción NO lleva privación del permiso Y NO lleva retirada de puntos. Las otras condiciones no son criterios."},{"id":11646,"bg":"Когато пътник в лек автомобил не изпълнява задължението за използване на предпазен колан, наказание се налага:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"на пътника без колан и на водача на автомобила","ok":true,"i":null,"es":"el pasajero sin cinturón Y el conductor"},{"t":"само на пътника без колан","ok":false,"i":null,"es":"solo el pasajero"},{"t":"само на водача на автомобила","ok":false,"i":null,"es":"solo el conductor"}],"sim":0.5,"es":"Cuando un pasajero en turismo no lleva cinturón, la sanción recae sobre:","explain":"⚠️ TRAMPA: AMBOS son sancionados — el pasajero por no llevarlo y el conductor por no haberlo exigido. La responsabilidad es compartida."}];